/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20181210-6","meetingId":"h30-cm12","date":"2018年12月10日","dateIso":"2018-12-10","committee":"区民委員会","time":"午前１０時００分～午前１１時４５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件整理しています。","topics":[{"id":"topic-01","title":"第９１号議案 臨海部広域斎場組合規約の変更","agenda":"第９１号議案 臨海部広域斎場組合規約の変更","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"確認なのですけれども、北側駐車場に増設するということで用地取得はないと思っているのですけれども、別表に記載されている理由を伺います。今回の規約の変更で、利用者の利用料は上がるのかということを伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"北側駐車場の部分を活用して増築を行うものですが、将来的に用地を取得するケースもあり得ないとは言えませんので、一応そこで担保したものです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"この後も増築する可能性があるということなのか、見通しというのでしょうか、そこを伺いたいと思います。１日の限度が２５件の受け入れだと思うのですけれども、その日数の推移がどうなっているかというのがおわかりになればお答えほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"２０６０年度までは、６基増築することによって対応できるということなので、当面は用地取得をする必要はないだろうという見込みですが。利用実績、１日２５件、日数というのは具体的にどういうことでしょうか。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"私が聞きたかったのは、１日の限度の受け入れ件数というのは２５件だと思うのですけれども、その２５件いっぱいだった日数が何日だったかというのをお聞きしたかったのですが、今わかりますか。","respondent":"提坂戸籍住民課長","answer":"何日かという形ではお答えできないのですけれども、稼働率としては、９０％程度はいっていると思います。","id":"exchange-003"},{"speaker":"のだて委員","kind":"意見","question":"私も増設に向けての報告書を見させていただいて、限度いっぱいの日数が増えてきているということでしたので、やはりこの増設というのは、今９０％というお話もありましたので、必要なことだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"素朴な質問で申しわけないような気もするのですが、利用実績割の定め方ですけれども、管理運営経費のところでは「当該会計年度」になっていて、建設経費のところになると「前３会計年度」となっているのですけれども、これは定め方にどうしてこういう違いが出てくるのかお教え願えればと思います。","respondent":"提坂戸籍住民課長","answer":"負担割合が「前３会計年度」となっているということで、一定の期間の利用実績を用いることで単年度の振れ幅を平準化した割合を用いしています。一定程度に振れ幅がありますけれども、あくまでも該当年度の利用実績割合をあん分に用いることとしてこういう形で出しています。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"言ってみれば、建設経費みたいな固定的なものは毎年毎年出す必要もないだろうという感じですか。ところが、建設経費は前３会計年度ということは、でも前３会計年度でも毎年変動するわけか尋ねました。","respondent":"提坂戸籍住民課長","answer":"建設経費につきましては、各区の利用実績割合をなるべく正確な形で出す必要があるということで前会計年度を参考にして出すということです。年度によっては出っこみ引っ込みがありますので、それに基づいて、該当年度の利用実績割合をあん分するです。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"そのほうが３会計年度を平均した、でも３会計年度の平均というか、やはり毎年変わっていくのは変わっていくのですよね。でも、平準化したほうが単年度でやるよりはいいというか適切だという判断があるのだろうと思うのですけれども、それはどういったことか尋ねました。","respondent":"提坂戸籍住民課長","answer":"ほかの区が少なかったとか、そういうこともあり得ないとは言い切れませんので、３年度の実績をならして公正な負担割合を出そうという考え方から来ているものです。","id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"そのほうが公正になるだろうということか尋ねました。","respondent":"提坂戸籍住民課長","answer":"もう一回ご説明しますけれども、それを該当年度ごとに支出した費用ということで、該当年度の利用実績割合をあん分に用いることといたしております。建設経費につきましては、今申し上げました単年度の振れ幅を少しでも平準化しようということで出したものです。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"今どういう考えかというのが出ているならば教えていただきたいのですけれども、１５年後ぐらいには今よりも増えていく形になるわけですね。それとも、将来のことですから全く出てこないのか、もしわかれば。","respondent":"提坂戸籍住民課長","answer":"今回の施設整備基本方針を策定するにあたって、人口については１０年、２０年ずっと増え続けると。６基増設することによって、２０６０年度、あと４０年後までは何とか対応できるだろうという今のところの見通しは立っています。","id":"exchange-009"},{"speaker":"大倉委員","kind":"質問・要望","question":"今のお話でいうと、１０基での対応が限界というところでいうと、限界の考え方を教えていただきたいのです。２０２６年から２７年度が基本設計・実施設計で、着工が２８年度というところでいうと、このスケジュールの考え方についても説明を求めました。","respondent":"提坂戸籍住民課長","answer":"施設整備基本方針によりますと、ぎりぎりのところで火葬炉１０基ということで対応は可能なのですけれども、それ以降になるともう厳しいだろうと。来年度から１０年間積み立てをしていけば、ちょうどうまい具合に計画とマッチするという形で、この計画が出たものと考えます。","id":"exchange-010"},{"speaker":"大倉委員","kind":"質問・要望","question":"今の説明だと、２０２９年の限界に合わせて積み立てていくと、うまく合うというところ。その点についてもう一回改めて教えていただきたいのと、難しいと思うのですが、もっと早めの対応とかというのは考え方としてはいかがなのか尋ねました。","respondent":"提坂戸籍住民課長","answer":"稼働率９０％という、今手元に資料がないので正確な数字とは言えませんけれども、９０％程度だろうです。１３年の計画で積み立てていくとなると、１０年間の積み立てということで、計画を立てさせていただいたところです。","id":"exchange-011"},{"speaker":"大倉委員","kind":"質問","question":"その総合的な判断というところが、今の話だと、なかなか出てこないというところでいうと。というところが、もう少しお話しいただけると分かりやすいかなと思っているのですが、いかがか尋ねました。","respondent":"提坂戸籍住民課長","answer":"その辺の細かい今後の推計は区のほうではつかめてないので、あくまでも従来の私どもの臨海斎場の利用率と今後の人口ビジョンに基づいて推計したところ、２０２９年度までに工事を竣工させることが妥当だろうということで計画を立てさせていただいたです。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"今、大倉委員とのやりとりを伺っていてそうかと思ったのですけれども、稼働率はどういうふうに考えるかですよね。何でと伺うと、例えば亡くなってから３週間後、１カ月後でないと火葬できないとかいう状況になったらという心配もあるのです。","respondent":"提坂戸籍住民課長","answer":"なるべくお昼の時間に火葬をご希望される方が多いというのは事実として認識しておりますけれども。亡くなってから何日以内に火葬したかということについては、当方では把握してございません。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問・要望","question":"だって、朝６時、７時に告別式というのは厳しいではないですか。これが延びていく可能性が大ですというのだけは押さえていかないといけないのではないかと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"提坂戸籍住民課長","answer":"平均すると２日から４日程度というような話は聞いておりますけれども、それをなるべく延ばさないように工夫してやってまいりたいと考えています。その辺は葬儀業者などとも連携して、意見交換とかそういうものもやる必要があるかと考えています。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"現に１週間以上という、お通夜、告別式ありますよね。将来どうなるかというのを通じて出てくるわけですから、では将来どうしていこう、ああしていこうということを考えていくのが知恵ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問","question":"今お話の中で火葬炉がメインなのかなというところで伺っていたのですが、何で３室なのかという考え方について教えてください。品川区としては、なぎさ会館との関係とか、その辺のお話でどういうふうに考えられているのかというところをお聞かせいただければ。","respondent":"提坂戸籍住民課長","answer":"断言して申し上げることはできませんけれども、車で１０分かからないところになぎさ会館がございまして、各３室というところが妥当なところではないかと考えています。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問","question":"そのなぎさ会館がだめとか言うのではなくて、効率的に、効果的に土地とかも含めて活用ができるのではないかと思ったので伺いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"渡辺委員","kind":"質問","question":"炉が少ないとか、これは別に２０６０年のピークまでどうこうの話ではなくて、現在も含めて見直すべきところが多々あるような気がします。どうやって現状の課題を発信していくか、それとその根拠のところで民間の動向の捉え方、その辺を説明を求めました。","respondent":"提坂戸籍住民課長","answer":"他斎場の動向についても、臨海斎場組合を中心にアンテナを張って動向を正確につかめるように努めてまいりたいと考えております。２０２４年度を待たずとも緊急性のあるものについては随時、積極的に臨海斎場のほうにも提言をしてまいりたいと考えています。","id":"exchange-018"},{"speaker":"渡辺委員","kind":"質問","question":"その辺も含めて、現在も課題として、議題として捉えているかどうかだと思うのです。将来的に進めていけばいいだけの話ではないような気がしているので、現在もその辺、十分把握されているのかどうかだけ説明を求めました。","respondent":"提坂戸籍住民課長","answer":"先ほどもご説明申し上げたのですが、３年ごとに見直しを図るということで、その辺はいろいろと考慮してまいりたいと思います。","id":"exchange-019"}]},{"id":"topic-02","title":"目黒川みんなのイルミネーション２０１８ 冬の桜R)ウインターコンサートの開催","agenda":"目黒川みんなのイルミネーション２０１８ 冬の桜R)ウインターコンサートの開催","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"初めてであればどういった経緯で開催されるのか伺いたいと思います。基準というのでしょうか、条件というのでしょうか、そういったものがあったら教えてほしいと求めました。","respondent":"立川文化観光課長","answer":"３年前より品川区も参加いたしまして、全体で２.２キロにわたって目黒川のイルミネーションを実施しています。実施主体の考え方ですけれども、もともと目黒川のイルミネーションについては目黒川のイルミネーション実行委員会だけの単独開催でございました。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"少し確認をさせていただきたいのですけれども、目黒川みんなのイルミネーションは、冬の桜ということで廃油を利用したイルミネーションだったと思うのですけれども、今回もそうなのかということをまず説明を求めました。","respondent":"立川文化観光課長","answer":"今回もイルミネーションの発電につきましては、周辺地域から廃油を回収いたしまして、それをもとに発電しているものです。","id":"exchange-021"},{"speaker":"田中委員","kind":"意見","question":"９年前からと先ほどお話がありました。廃油を使ったリサイクルというか、そういう面をもっとアピールすべきだったのではないのかと思うのですけれども、そこのところを説明を求めました。","respondent":"立川文化観光課長","answer":"委員ご指摘のお話はごもっともだと思います。ただ、特に記載していないということですので、もし次回やるようなことがありましたらその辺も十分アピールしていきたいと考えております。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ、チラシのほうにも、小さくてもいいので、地域の方たちが育ててきたイルミネーションなので、ぜひ記載をしていただきたいなと思うのと、あと、すみません、少しお話が変わって予算額なのですけれども、予算額の内訳を教えてほしいです。","respondent":"立川文化観光課長","answer":"進行関連経費、会場関連経費、あとチラシの告知関連経費等です。照明および進行関連につきましては大体６０万円、会場関連につきましては３０万円、その他告知関連につきまして２７万円プラス消費税です。","id":"exchange-023"},{"speaker":"大倉委員","kind":"質問・要望","question":"改めて目的を教えてください。この日程についても、なぜこの日になったのか教えてほしいと求めました。","respondent":"立川文化観光課長","answer":"目的ですが、目黒川イルミネーションの中心地である五反田ふれあい水辺広場において和楽器アーティストらによるコンサートを開催するものです。日時につきましては、イルミネーションの開催期間ということで１２月１５日を選定したものです。","id":"exchange-024"},{"speaker":"大倉委員","kind":"質問","question":"目的はコンサートを開催することになるのですか。そのコンサートを開催して、その後どういったものにつなげるとかというところが目的なのかなと思うので、改めて説明を求めました。","respondent":"立川文化観光課長","answer":"それから、文化と観光を連携してやはり区内外にアピールしていくです。広く区内外に発信するとともに、和楽器文化の発展振興に資する、こういったことを目的にしています。","id":"exchange-025"},{"speaker":"大倉委員","kind":"質問","question":"１回やって終わりではなくて、この和楽器を広めていこうとか、どういうふうにこれを継続していこうというところの考え方。先ほど２７万円というところで、お金のかけ方については、何かその広報について工夫があれば説明を求めました。","respondent":"立川文化観光課長","answer":"１２月１５日になった理由も、実施時期については、この辺はいろいろなご意見をいただいて検討していく必要があるかと考えているところです。来られてない方に対する効果のほうが高いかなと考えているところでございまして、実際、広告を有効に活用していきたいと考えています。","id":"exchange-026"},{"speaker":"渡辺委員","kind":"質問","question":"となると、この場所もそうなのですが、では椅子をどのぐらい用意するのですかというのもあわせて教えてください。ポスターなのかチラシなのか駅張りなのかも含めて教えてほしいのと、どのくらい告知、チラシであれば幾らなのか。","respondent":"立川文化観光課長","answer":"初めて実施するということと、あと、屋外でやるということで、実験的に行う意味合いがありますので、無料というふうに決めたところです。","id":"exchange-027"},{"speaker":"渡辺委員","kind":"質問","question":"こういった地域と行政が一体となった行事が２０２０年に向けて、その後も、大なり小なり各地域で芽が出て展開されることが理想だと思っています。では今後、区全体で、翌年さらにその先、明確なものではなくても、理想を含めておありだったら説明を求めました。","respondent":"立川文化観光課長","answer":"２０２０年というのを１つの目標に実施していますけれども、品川区として積極的に取り組むことによって皆さんに満足していただきたいという思いがありますので、これからも品川区を盛り上げていきたいと考えているところです。","id":"exchange-028"}]},{"id":"topic-03","title":"品川区施設予約システムのリニューアル","agenda":"品川区施設予約システムのリニューアル","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"確認なのですけれども、今回は３月中旬ということで、３月中旬からが正しいということでいいのかということを確認させてほしいと求めました。事業者が今回撤退したということで、その撤退した理由と、新システムを委託している事業者というのはどういうところなのかを伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"３月中旬ということで、本日の委員会のご報告終了後に訂正できるものについては全て訂正する予定になっているところです。具体的には、事業そのものから撤退するという申し出がございましたので、それに基づきまして私どもとして再構築をさせていただいているところです。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"新システムを委託する事業者はどこなのかということもお伺いしたので、お願いします。","respondent":"池田スポーツ推進課長","answer":"新システムについて契約している事業者につきましては、ＮＥＣソリューションイノベータという会社です。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"それを改善するためにどれを変更するのかという形でご説明いただくとすごくわかりやすいのですけれども、お願いいたします。これは要望なのですけれども、貸室としても同じものなので一緒に見られるようにしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"こういったことも、そういったものをあわせて目的ごとに部屋の空き状況が確認できるようにということで今検討しています。支払い状況につきましても、口座引き落としということもいろいろな面で検討しています。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問","question":"今ご説明があった検索の仕方のところは、この変更点に書いてある施設検索機能の拡大のところのご説明だったということでよろしいですか。改めてになりますけれども、きゅりあんとスクエア荏原も一緒に見ることができるようになるということでよろしいのか伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"施設検索機能の拡大ということで、先ほどの目的別、日にち別ということが加わる、新しいものが加わってくるという説明をさせていただきました。その後にきゅりあん、今回、そういった拡大してきたものをなるべく統一しようということで作業を進めております。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"不具合の内容を教えていただきたいのと、さらに３月の中旬からはリニューアルがされるというということなのか、今の不具合の部分は１月４日から３月中旬までは継続されるのかというところをお知らせください。","respondent":"池田スポーツ推進課長","answer":"今あるシステムにつきましては、３月のリニューアルをするまではそのまま継続してご利用していただくことになります。そして３月にきちんと使えるようにということで今作業していますので、３月の時点でリニューアルするということで特段の影響はないところです。","id":"exchange-033"},{"speaker":"田中委員","kind":"確認","question":"利用者の方にとっての不具合が発生しているということですか、それとも、事業者間での不具合が発生しているのかということを確認したいのですけれども、お願いします。","respondent":"池田スポーツ推進課長","answer":"１月４日にやることにつきましては、このままやると利用者にとって不具合が発生するということがわかりましたので、３月に延期する。１月４日にもしそのままリニューアルした場合には、万全を期した形で３月にリニューアルするということで作業を進めているところです。","id":"exchange-034"},{"speaker":"田中委員","kind":"確認","question":"確認なのですけれども、利用者にとっての不具合が発生してしまうので、３月から新しくリニューアルされるというのはわかりました。その１月から３月にかけて利用者の方にとっての不具合が発生してしまう可能性があるのかないのかを確認したいのですけれども。","respondent":"池田スポーツ推進課長、安藤文化スポーツ振興部長","answer":"１月から３月までは、現在のシステムをそのまま使いますので、利用者にとって不具合が生じることはございません。利用者にとってはそのまま使えますので、何も変わりません。だから、不具合というのは、日立からＮＥＣに移行するデータに不具合があって、１月４日からできませんということです。","id":"exchange-035"},{"speaker":"田中委員","kind":"確認","question":"今のご説明でわかったのですけれども、とにかく私が聞きたいのは、利用者の方にとっての不具合が発生しないですよねということの確認を最後にさせてください。","respondent":"池田スポーツ推進課長、安藤文化スポーツ振興部長","answer":"３月に行われるリニューアルにつきましては、利用者にとって不具合がないように進めてまいります。 利用者の方々にとっては、一切不具合はありません。どの期間もありません。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"スポーツ推進課長としてお伺いしたいのですけれども、何でしたっけ、４つの。説明を求めました。","respondent":"池田スポーツ推進課長","answer":"予約システムにつきましても、こちらをつくるときに、「いつでも」「どこでも」「手軽に」ということで始めさせていただいたものです。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問・要望","question":"これを目標にやっていっていただきたいと改めて思うのですけれども、４つも書いてあるのですから。この４つをこういうふうにうたっているわけですから、どうしていきたいか、改めてご答弁いただけますか。","respondent":"池田スポーツ推進課長","answer":"「どこでも」というところで、携帯電話、それからスマートフォンでも利用できるようにということでスマートフォン対応にするところです。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問・要望","question":"一つ一つ伺うと、区民の方々が本当に「手間なく」「かんたんに」できるシステムをこれからもつくっていっていただきたいと考えていますので、改めまして今後とも前向きに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"田中委員","kind":"確認","question":"もう一つ確認なのですけれども、現在は引き落としのところでちょっとしたトラブルがあったとさっきご説明があったと思うのですけれども、その引き落としでのトラブルは、利用者の方がトラブルに遭ってしまったのか、それとも区と事業者の間でだったのかというところを確認させてください。","respondent":"池田スポーツ推進課長","answer":"そういったことを直すためにお時間をいただきたいということで、リニューアルを３月に延ばすということで説明をさせていただいたところです。ですので、現在のところ、利用者の方にそういった口座振替でのお手間をかけたことはないところです。","id":"exchange-040"},{"speaker":"おくの委員","kind":"質問・要望","question":"さらに、もしできるのならやっていただきたいということで要望を出しておきたいのですけれども、１月２０日なら２０日で押したときに。質問プラス要望、その辺まで考えられているのでしょうか、なるだけそれを可能な限り機能として入れていただきたいということです。","respondent":"池田スポーツ推進課長","answer":"すぐ対応できるかということになりますと、カスタマイズが大変難しいところですので、ご要望に添うことができないことはあるかと思います。そういったようなことでご承知いただければと思います。","id":"exchange-041"},{"speaker":"おくの委員","kind":"質問・要望","question":"私の使った実感として、とにかく強い要望としてお伝えしておきますので、今後もそういうことを念頭に発展させていただければなと思います。そこがないのが本当に面倒だなという感じだったも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、設備とかの話は表示があるというお話だったのですけれども、そこの確認と、何が表示されるのかを教えていただきたいです。","respondent":"池田スポーツ推進課長","answer":"施設につきましては６０施設ございまして、会議室とか集会室の数を数えると２００以上あります。全部を今確認していますので、どのような表示になるかというのはまだはっきりとしてないところです。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/374422?Template=document&Id=2826#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":29195,"voices":121}},{"id":"h30-20181210-7","meetingId":"h30-cm12","date":"2018年12月10日","dateIso":"2018-12-10","committee":"厚生委員会","time":"午前１０時００分～午後 ２時１７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件整理しています。","topics":[{"id":"topic-01","title":"第８３号議案 品川区立障害児者総合支援施設条例","agenda":"第８３号議案 品川区立障害児者総合支援施設条例","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今回の施設の設置条例なのですけれども、これまでの流れの中でちょっと確認をさせてほしいと求めました。そこら辺で帰ってしまったもので、その説明会での状況を先にご説明いただけますか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"１１月に区民向けに、この施設がおくれてスタートが１０月になるということで、その説明会をいたしました。現在こみゅにてぃぷらざ八潮３階の講習室を仮設使用できるように、今、話を進めているところです。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"確認","question":"そこら辺のところになってくると思うのですけれども、あのときに質問があった部分に対しての答えが変わってしまわないで大丈夫なのですかという、改めて確認なのですけれども。","respondent":"飛田障害者施策推進担当課長","answer":"今回、クリニックは指定管理にはしませんけれども、今まで同じように４つの法人とまた連携しながら、事業のほうは変わりなく行うということには変更はございません。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう少し後からもう一回聞きますが、全体的に説明会の中での話としては、皆さんご了解いただいたというふうに判断しているのでしょうか。大体の合意を得られたかどうか、対応について皆様理解していただいたかなということで、その辺はどうなのか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"今回説明会をやらせていただきまして、お話をさせていただいたところです。４月からの代替施設に向けて、今進めているところです。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"確認","question":"前の７月の説明の中では４つが指定管理の対象になるということでしたけれども、では３つ指定管理を受けてという方向に流れが変わってくるのか。決定はまだ後ですけれども、医療がなくなって、３団体でこれから進んでいくのかということで、確認なのですが。","respondent":"飛田障害者施策推進担当課長","answer":"今回条例を策定しまして、予定では指定管理者候補が３つの法人となりますので、３つの法人と個別に協定を組んでいくという予定です。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"確認","question":"決算特別委員会でもちょっとその確認をさせていただいた中で、やはり医療系の問題というのは少し質問させてもらったのですけれども、その辺はどのように判断したらいいのかわからないのですが。","respondent":"飛田障害者施策推進担当課長","answer":"議会へ報告しなければなりませんけれども、医療のレセプトの知識等も区にはありませんので、そこのところでもちょっと難しいのではないか。医療系サービス全般にわたって正しい判断が区にはできないということで、指定管理者制度での実施が困難と判断いたしました。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"意見","question":"そうすると、どこか指定管理を受けた法人は医療系に関してノウハウを持っているのかなと、逆に今の説明だとそこの横の関係です。区は全体を管理する立場として大丈夫なのかなというのが、今聞きながら引っかかったのですけれども、そこら辺はどのように感じていますかとの意見を述べました。","respondent":"飛田障害者施策推進担当課長","answer":"その医療のお金のところというのは、やはり区もなかなか難しいというところがありますので、今回指定管理から外したということです。今回、医療のところでは児童精神の方を入れて話を進めていまして、そういうことでまた連携を図っていきたいと考えております。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"意見","question":"お金の話というのは、逆に区とではなくて、その指定管理を受けた法人と別の法人がその医療を運営するわけですね。だから区は直接ではないけれども、法人間の問題も絡んでくると思うのですけれども、そこら辺は区として何か管理しないでいいのかということですとの意見を述べました。","respondent":"飛田障害者施策推進担当課長","answer":"今回３つの法人と別々に協定を結びますので、区としてもモニタリング等で確認していきたいと考えております。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、前はＡがやっていて、医療系はＢだとなっていたのが、そこのＡがＢもひっくるめてやるということになりますよね。別々の法人が２つの事業をひっくるめて、向こうの問題だからいいのかなと受け取ってしまうのか、これも区が管理しなければいけないのではないか尋ねました。","respondent":"飛田障害者施策推進担当課長、松山障害者福祉課長","answer":"別々といいましても、今までどおり各法人連携をとっていきます。ただ、お金の流れとしては個別となります。委員お尋ねの法人との関係なのですけれども、それぞれの法人と独立して、医療系サービスにつきましても独立した形でということで行ってまいります。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"意見","question":"そこが今後も全体として管理していくという、向こうの中での管理という部分が出てくると思うのですけれども、その３つの法人が指定管理を受けた。そことその３つがフリーユニティーという法人を持っていて、その辺の管理体制はどのようになっているのかなということの意見を述べました。","respondent":"飛田障害者施策推進担当課長","answer":"区はあくまでも３つの法人と指定管理の協定を結ぶ予定であります。そちらのお金の流れとか、そういうところはないように、こちらのほうでも見ていきたいと考えております。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"確認","question":"ちょっと気になったから確認させてもらいます。１階から５階までは何でないのかなと思ったのだけれども、まさか６階にだけだれでもトイレがあるということではないよねというその辺の確認です。","respondent":"飛田障害者施策推進担当課長","answer":"ここの地下１階では４カ所、だれでもトイレを考えております。５階も肢体不自由の方などが入られる予定ですので、ちょっと多めに予定していまして、そこに設置しております。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"確認","question":"丁寧にありがとうございました。当然どこかにいっぱいあるだろうと思っていたけれども、ここだけだったので、ちょっと図面上気になったので確認をさせてもらいました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"どのような施設になるのかというのを中心に伺いたいと思うのですけれども、その後、１月に出されたこの資料と定員に変更はないのか。その定員をどう考えるのかというところでも、変わっていないのかということと一緒に、そういう定員の考え方を教えていただきたい。","respondent":"飛田障害者施策推進担当課長","answer":"定員につきましては、前回１月２２日に説明したことと変わっておりません。徐々に施設と利用者、職員、その対応をみながら順にこの１月２２日に説明した定員に少しずつ増やしていこうと考えております。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"今日いただいた資料の中の事業のサービス内容についての施設の区分のところの２番、この特定相談支援事業の中に児童も入るのかを伺いたいと思います。それがそっくりここに移動してくる、移るということなのか、伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"そういうところも鑑みて、定員を１０名増やしたところです。ただ、先ほど区のほうがそっくりそのままということではなく、一部をというふうに考えてあります。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、児童の障害児の指定特定相談は、この総合施設でもできるし、区でもやるということで、２カ所になるということか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"はい、そのように考えております。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"３番の訪問系サービスなのですけれども、今までも区でやられていたのか、ちょっと確認をさせていただきたいなと。訪問系のサービスを区内でやるのは初めてなのではないかとちょっと思ったものでそこの確認と、あと、対象地域があるのかを伺いたいのですが。","respondent":"飛田障害者施策推進担当課長","answer":"実際今までもやっていたのと変わりはないのですけれども、受けてくれる事業所というのは非常に少ないというのが現状です。今回、区内でサービスを行っていく予定です。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"訪問系サービスを受けていたかもしれないのですけれども、区内にその事業所があったということでいいのでしょうか。それを伺いたいと思うのです。","respondent":"飛田障害者施策推進担当課長","answer":"実際今、その支援をしてくださる法人がいないということが実情でありまして、今回新たにこちらのほうで行うということです。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、すごく広がるのかなと思うのですけれども、その訪問系サービスの対象地域も伺ったので、説明を求めました。","respondent":"飛田障害者施策推進担当課長","answer":"一応品川区内というところで、自転車で移動するという前提で考えております。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうですか、わかりました。２階に在宅介護支援センターとヘルパーステーションが入ると図で示されていたのですけれども、どうなったのか伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"今のところ在宅支援センターは、今のままのところでやるということで考えておりますので、今回は図面から落としております。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"確認","question":"先ほどもちょっと医療系サービスのところでいろいろお話があったと思うのですけれども、確認をすると、場所を貸すということでいいのですね。この診療所がここで区に賃料を払って、ここの場所で診療をするということで、独立採算になっていくということでいいのか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"基本的には医療系のサービスのところについては独立採算ということになります。とはいえ、児童精神科というところでは児童学園との連携も必要になりますので、そこのところについては必要に応じて援助等も考えております。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはりこの施設の説明、いろいろ指定管理も４つと別々で組んでいくというのが３つになったり、ちょっと変わってきている部分もあると思うのです。ですので、そういった方々にまだまだ丁寧な説明が必要なのではないかと思うのですけれども、この説明についてはどのように考えているか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"今回１１月に区民に向けて説明会を行ったところです。今度１０月開設になりましたけれども、４月以降、春ぐらいに新たにまた説明会を開く予定です。","id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問","question":"本当に期待されている施設であるというのと同時に、地域の理解と、それから利用者の方々が安全安心に利用できるというところを小まめに丁寧に説明していただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ちょっと今気になったのは、これで設置条例を制定して、指定管理者の指定は当初は来年の第１回定例会で予定ということだったのですけれども、開設は１０月になるということは、その辺の指定管理者の指定の時期というのはどのように変わってくるのかとの意見を述べました。","respondent":"飛田障害者施策推進担当課長","answer":"第１回定例会で考えております。施設条例の施行は、先ほど説明したとおり、１０月１日と考えております。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今の指定管理の日にちなのですけれども、ここの６番のところには公布の日とすると書いてありますね。４月から指定管理を結ぶのはどの事業者になって、どの事業者が仮設で４月から始められるのかということについて説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"この設置条例の公布日というのはいつになるのでしょうか。それと、指定管理者として指定管理が開始されるというのは、１０月１日ということでいいのか確認いたします。","respondent":"飛田障害者施策推進担当課長","answer":"平成３１年１０月１日から施行です。","id":"exchange-024"},{"speaker":"若林委員","kind":"提案","question":"その中で、地下１階の診療所の部分は、この条例の中でどのような理解をしたらいいですか。この総合施設という施設の条例が今回提案をされて、私は出てきていないのかなと読んでしまったのですけれども、そこら辺の位置づけをとの意見を述べました。","respondent":"飛田障害者施策推進担当課長","answer":"今回の条例には、その地下１階の医療系サービスのところは入っていません。","id":"exchange-025"},{"speaker":"若林委員","kind":"質問","question":"施設の条例なので、さっき質疑で医療系の部分はこういう形でとありましたけれども、それは条例には本来入れるべきものではないのですか。そこら辺が、ちょっと施設の条例としてはこれで十分なのかなという疑問を持ってしまうのですけれども、採決にあたってどのように理解したらいいのか。","respondent":"飛田障害者施策推進担当課長","answer":"現在そこの地下１階のところでは、区としましては行政財産の使用許可というところで考えております。","id":"exchange-026"},{"speaker":"若林委員","kind":"質問","question":"ということで、この施設条例には入れなくていいと、ほかの条例もそのようになっているという理解をしようと今思っているのですが、見解を伺います。","respondent":"飛田障害者施策推進担当課長","answer":"そのとおりです。行政財産の使用許可にて行いたいと考えております。","id":"exchange-027"},{"speaker":"若林委員","kind":"確認","question":"説明会のお話がありまして、サービスが半年、開所・開設が延期されるということで、区民、主に利用者に向けての説明会が１１月１５日に行われたと。そういう意味では地域での説明会というのは、この辺は今まであったのか、今後どうされるかをちょっと確認しておきたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"地域に関しましては、今のところは広くビラを配って、また児童学園に近いところには一軒一軒対応していく考えです。","id":"exchange-028"},{"speaker":"若林委員","kind":"質問","question":"これまでの経緯から、いわゆる近隣地域の方のかかわりというのは相当深い。やはりここの地域でいろいろな方のお話を伺っている議員もいますので、同じ説明で質疑を受けるということで、いかがか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"現在のところでは、地域で集会所を借りて行うということは予定しておりません。ただ、やはりポスティング、また一軒一軒丁寧にお伺いして説明したいと考えております。","id":"exchange-029"},{"speaker":"若林委員","kind":"確認","question":"先ほどの説明ですと、いわゆる個別の説明をさせていただいて、ポスティングで、私の質問に対しては特にやる予定という言葉は一切なかったのですが、元々そういう計画があったという、これからやりますという考え方を持っておられたのですねという確認を。","respondent":"飛田障害者施策推進担当課長","answer":"工事担当の施設整備課と相談しまして、検討させていただければと思います。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"改めてちょっと確認させていただきたいのが、改めてそこで実施される事業というのは、４番のアとイということで確認させていただいていいでしょうか。ここの中に書かれていて、実際にこれはされていて、これは１０月１日ですというあたりを、改めて確認させてほしいと求めました。","respondent":"飛田障害者施策推進担当課長","answer":"それと、仮設で実施する事業は基本的には生活介護と就労継続支援Ｂ型の対象の方をと考えております。日中一時支援は同じく１０月と考えております。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"では、４番のアとイは生活介護と就労継続支援Ｂ型のそれぞれが１０名ずつで、合わせて２０名という考え方なのでしょうか。先ほどの医療系サービスなのですけれども、そういうのは、もちろん事業者は了解済みということでよろしいのでしょうかという確認もさせてください。","respondent":"飛田障害者施策推進担当課長","answer":"アとイのところですが、１０名、１０名ではなくて両方合わせて１０名と、部屋の大きさから考えてそのように考えております。医療系サービスについては、今法人とも話し合いを進めているところです。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"これは設置条例ですけれども、１０名前後というと職員の配置は何名くらいになるのでしょうか。これは本当に受ける事業者側の責任ではなくてこういう状況になったわけですから、そこら辺のところはしっかりと対応が必要だと思うのですけれども。","respondent":"飛田障害者施策推進担当課長","answer":"先ほど１０名前後というのは、現在利用の話し合いをしている中で、保護者の希望等でそういう１０名前後かなというところで、今、対応しているところですが、そこのニーズ等もみて事業者とも今後相談しながら決めていきたいと考えております。","id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ここでは４０名・２０名というのが元々の計画だと思うのですけれども、そこまで増やせるのか、希望者があれば増やせるということで考えていいのか。確保した職員に対しての補償という点については、区としてどう考えられているのかというところはどうか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"それは１０人以上というのは児童学園部門も合わせての人数ということで聞いております。そこは各事業者においてその金額を挙げていただきまして、その金額を適切にこちらのほうでも判断しながら考えていく必要はあるかなと思います。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"こういう半年おくれという形になったことに対して、きちんと補償はしていくということで確認させていただいていいでしょうか。それをお願いします。","respondent":"飛田障害者施策推進担当課長","answer":"延期してしまったというところもありますので、そこはまた法人とも話し合いながら、適正な対応をしていきたいと考えております。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう点では、このことによって本当に１０月１日に大変な状況になるということがないように、ぜひとも区としては対応をお願いしたいと思います。もっと質問をしながら、４月をまたずに説明会をぜひしていただきたいということで、強く要望をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ここまで来てうまく立ち上がってきた、条例自体は賛成するのですが、先ほど来、今までの流れでいろいろありました。その辺の説明を皆様にすると同時に、区の中でももう少し整理しておいてもらいたいというところも感じますので、それは要望としながら賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"石田（ち）委員","kind":"質問","question":"別紙２のＡ３の資料で、ほかの区のこうした指定管理者の選定などを見ていると、こういう項目によってそれぞれ点数で採点をしているのです。この今出されている資料の別紙２の選考基準で点数はつけられているのかどうか伺いたいのと、あと、入っていないのはなぜなのか伺いたいと思います。","respondent":"大串福祉計画課長","answer":"入所系サービス、大項目としては４つほど、さらにそこに中項目がぶら下がっているといったことになっております。事業者からいただく事業計画書等々にはそういった文言も入っておりまして、そういったものも加味した上で検討させていただいているです。","id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"改めてまた５年間ここに指定管理者として任せていく、また課題等も含めて、大丈夫ですから信じてくださいと言われているのと同じかなと思うのです。今、そして人件費が何％ぐらい割かれていたのかというのを教えていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"大串福祉計画課長、寺嶋高齢者福祉課長、松山障害者福祉課長","answer":"様々な資料等々もお出しをさせていただいているという中で、ご判断いただければと考えているところです。それ以外のモニタリング等々を通じた中で総合的に… ちょっとこの場で数字を細かくお答えすることができないのですが、考え方になってしまいますが、ここまでの回答になります。障害者福祉課所管の３施設も同様に、モニタリングの中できちんと財務状況、収入および収支の状況を確認しております。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"指定管理者が労働法令を遵守することは当然ですから、先ほど言ったように、ちょっと私たち議員としてはならないなと思っています。そして指定管理に関する業務の収支という資料を出していただきたいと思うのですけれども、ご検討いただきたいのですけれどもいかがか尋ねました。","respondent":"大串福祉計画課長","answer":"指定管理に対してといったところにつきましては、区全体の考え方になってまいります。全体の考え方を検討と聞いておりますので、そうした中で、この委員会での提出資料のことについても検討していきたいと考えております。","id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"ちょっと個別のところを伺っていきたいと思うのですけれども、訪問もやっていこうと考えていますとあるのですね。訪問」というこの３セットが基本なのかなと思っていたのですけれども、どうしてないのかを伺いたいと思うのですが、いかがか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"ちょっと私の認識と異なっている部分があるので、基本的に小規模多機能の中で行っているという認識だったのですけれども、すみません、ここはちょっと人数までは把握していなくて申しわけないのですが、小規模多機能の中の事業として行っているという認識をしています。","id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問","question":"ちょうど５年前の、「訪問介護についてはされないのでしょうか」という委員の質問に対しては、訪問という項目はないのです。ですので、ないのかなと思ったのですが。","respondent":"寺嶋高齢者福祉課長","answer":"いわゆる２５名の登録者に対する訪問、それはやらないというふうにおそらく回答しているのかと、そういうふうに考えられると思われます。訪問は利用率という考え方を持っていなくて、ほかの小規模多機能の施設についても訪問介護は利用率には表記していなかったと思われます。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"小規模多機能のところではやられているということで、はい、わかりました。離職率、離職率がわかれば教えていただきたいのと、人材不足に対しての区からの支援といったものはあるのか伺いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"１０％を切ったという状況、この会社が心配するように、２０％というのはやはりちょっと大きな数字だというところは区としても認識しております。","id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"されてきたのか、しようとしているのかというのは、事業計画や報告書で私たちにも示していただけたらなと思っています。それと、区として具体的にこの地域交流に対して求めていることは何かあるのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"先ほどの選定理由の中で挙げさせていただいたまず１つは、併設ということもありまして、これはもう開設時から力を入れているところです。","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それはるる伺ってきたので中身等々はあれなのですが、しかも今までにない条件を別につけて、そういったものも出していただけたらなと思うところです。それとやはり人材確保の面は、この心身障害者福祉会館はどのようにお考えか尋ねました。","respondent":"松山障害者福祉課長","answer":"前回の厚生委員会でもご説明したとおり、ほかの２施設も、人員基準は満たしております。改めて、今後の心身障害者福祉会館の５年間をどうしようかというところでかなり議論がされ、かなりきめ細やかな計画を立ててあります。","id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"次の第９５号議案、Ａ型からＢ型に移られた方は２人だったというお答えがあったのですけれども、やはりその当事者の方の給料が下がるわけですね。それと、Ａ型とＢ型の仕事の中身がどのように変わってきているのか、Ａ型とＢ型の内容をちょっと教えていただきたいです。","respondent":"松山障害者福祉課長","answer":"委員ご指摘のとおり、２名のうち１名の方が障害者雇用で就労されて、やはりＢ型が適しているだろうということでＢ型になっております。は清掃作業、Ａ型と比べてＢ型の作業のほうが種類が豊富で、それぞれに合わせた形での作業内容となっております。","id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問","question":"モニタリングのところでは、自主製品というのに力を入れていきたいと、「自主製品の商品力向上」というのがあるのですけれども、これなどは、要は水耕栽培でとれるものということなのか尋ねました。","respondent":"松山障害者福祉課長","answer":"こちらで言っています自主製品というのは、主に雑貨ですね。キャンドル、ろうそくですとか、あとくるみボタン等々が自主製品となっております。","id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問","question":"それは議事録というのはつくられているのでしょうか。それが情報公開請求をすれば見られる形にはなっているのかを伺いたいのと、あと、それぞれ伺いたいと思います。","respondent":"大串福祉計画課長","answer":"それから、選定委員会等々の議事録、これについても作成をしています。それから、各施設ごとでの第三者評価をやっておりますので、そういったところで総合的に判断しています。","id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"質問","question":"それは情報公開とかをすれば見られるのか、それとも課に見せてくださいと言えば見られるのか、ちょっとお伺いします。","respondent":"大串福祉計画課長","answer":"議事録等々につきましては、情報公開という形にさせていただいています。","id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう方向で、課のほうからもぜひ言っていっていただきたいなと思うのですけれども、その点が１つです。モニタリングのシートというのは、この程度で出していきましょうというのは各課で統一されたものでこのようになっているということなのか尋ねました。","respondent":"大串福祉計画課長","answer":"そうした中で、他区の事例も出していただきましたように、その辺も参考にしながら区全体として考えていくものかなとは考えているところです。","id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう点については、ぜひこれまで申し上げてきたように資料を出していただきたいと思うのですけれども、その点お聞かせほしいと求めました。３、４と大体ありますけれども、施設ごとに点数をお聞かせいただけたらと思います。","respondent":"大串福祉計画課長","answer":"指定管理のご議決をいただく際には、そういったところを踏まえた上での資料提供を考えていきたいと思います。ちょっと今日はその辺は持っておりませんので、総合的に判断したという形で、本日のところは資料を出させていただいているところです。","id":"exchange-051"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"後でちょっと教えていただきたいのと、その点、改めてお聞かせほしいと求めました。そのようなところでは、この附帯条件をつけたということでは、これは基本協定というのはこれから結んでいくということになるのか尋ねました。","respondent":"大串福祉計画課長、松山障害者福祉課長","answer":"点数等々の掲出についてはある程度全体の流れといったところになりますので、その辺はまたちょっと検討させていただければと思います。協定書については、各法人ごとに結んでいきます。 心身障害者福祉会館につきましては、こちらのご参考のところで議会にも報告させていただきましたとおり、この条件については基本協定の中にきちんと含めて締結したいと考えています。","id":"exchange-052"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"４議案とも自民党賛成です。その辺を充分チェックしながら、今後も運営に努めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"若林委員","kind":"質問・要望","question":"４議案とも賛成です。過去そういうことがあったと思いますけれども、またしっかりケアしながら充実した施設運営をお願いをしたいという要望を添えて、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"意見","question":"株式会社であるからこそさらに透明性を持って報告されるべきだと思いますし、そしてやはり株式会社は、この第９３号議案は反対です。そして、第９４号議案、第９５号議案、第９６号議案は賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"}]},{"id":"topic-02","title":"第９７号議案、指定管理者の指定","agenda":"第９７号議案、指定管理者の指定","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"ここは５年前のときに公募型プロポーザル方式で、この住友不動産エスフォルタ・ＮＴＴファシリティーズの共同事業体が指定管理者になったと。その前はコナミでしたかとの意見を述べました。","respondent":"川島健康課長","answer":"その前の前です。","id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"意見","question":"ここに選考基準というのがありますけれども、公募せずに……。〔「いや、公募したの」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうですね。では、継続の判断基準を説明を求めました。","respondent":"川島健康課長","answer":"そちらは、ほかの応募した事業体には具体的なそういったものがなかったのですが、水道料金削減の具体的な提案があったというようなところも評価が高かったと認識しています。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"（２）とあるけれども、この（１）の事業実績の中では、その中でも細かく判断の項目が分かれているわけですよね。その採点の評価、点数を教えていただきたいのですが。","respondent":"川島健康課長","answer":"それから、建物の維持管理に関する取り組みというのがもうかなり高い得点であったということです。合計得点は、１０００点満点のうちの８割以上を、今回１位の選定した事業体が獲得したです。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"提案","question":"これはやはりこの事業者のそういった取り組みや提案や工夫といったところで利用者が増えて、指定管理料も増えたということになってくるのですか。わかれば教えていただきたいのですが、収入と支出、それからの人件費分というのがわかれば説明を求めました。","respondent":"川島健康課長","answer":"利用料金収入が増えているということをご説明させていただいたところで、その収入自体、前年度よりも８００万円ほど増えているというようなことです。","id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問","question":"この職員とか働く方の入れ替わりとかは、それほど激しくはないのでしょうか。離職率やスタッフ配置とかはどのようにされているか、先ほど言った入れ替わりや離職率のところを説明を求めました。","respondent":"川島健康課長","answer":"トレーニングルームの責任者が１人、受付責任者が１人という形で、余り常勤の方の入れ替わりというのはないとこちらでは認識しています。トレーナーの方とかは、多分入れ替わり等があるのかなと思っているところです。","id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、離職率という形でもしとるとすれば、その常勤のところでしかとれないのですか。アルバイトというところは確かに入れ替わりがあるかと思うのですけれども、そういったところを含めた離職率というのは出るのか尋ねました。","respondent":"川島健康課長","answer":"そちらのほうは離職率という形では把握してございません。","id":"exchange-062"},{"speaker":"鈴木（真）委員","kind":"質問","question":"利用者の方何人かからお聞きして、やはり評判がいい状況です。今回も賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"石田（ち）委員","kind":"質問","question":"以前も、やはり区民の健康づくりを進める場に株式会社というのはふさわしくないということで、反対してきました。株式会社なのでやはり利益を追求するわけですから、そして突然撤退ということもあり得るのが株式会社ですので、反対します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"}]},{"id":"topic-03","title":"平成３０年陳情第２１号、放課後等デイサービスに関する補助事業等の実施を求める陳情","agenda":"平成３０年陳情第２１号、放課後等デイサービスに関する補助事業等の実施を求める陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私たちはいつも区民からのこうした請願・陳情への意見陳述は、議論の前にしていただきたいと思っていますし、その陳述を聞いて、そしてさらに議論を深めるということをすべきだと思いますので、ぜひ議論の前に意見陳述をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"芹澤委員","kind":"確認","question":"確認なのですが、今１２カ所あって、そこは先ほどお話のあったような何か民間とかの方法で送迎がなされているということなのでしょうか。この青海地区以外のところの方々からの声というのは、特に今のところ品川区としては受けていないということでよろしいのか尋ねました。","respondent":"松山障害者福祉課長","answer":"それから、保護者の方からお電話をいただいておりますのは、まだ臨海青海特別支援学校に決まってはいないということはあります。品川特別支援学校を逆に希望していらっしゃる方もいらっしゃいますので。","id":"exchange-066"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほど、新１年生でこの臨海青海特別支援学校エリアの人は１８人ということでした。障害者団体からも、そこに対して、品川区からは何か当時意見などを言われたりされたのか尋ねました。","respondent":"松山障害者福祉課長","answer":"保護者の方からは、臨海青海特別支援学校を希望されるというよりは、やはり品川特別支援学校に行きたいというお声のほうが大多数を占めておりました。臨海青海特別支援学校に行かれるのか、それともまた特別支援学級に行かれるのか、現在はまだ決定はしておりません。","id":"exchange-067"},{"speaker":"石田（ち）委員","kind":"確認","question":"やはりこの臨海青海特別支援学校のエリアの方が、この品川区内の学校にということで越境を望むと、スクールバスは使えなくなるのですよね。そこの確認をしたいのと、品川特別支援学校はそこまではしないということになっているのか、ちょっとそこを確認させてください。","respondent":"松山障害者福祉課長","answer":"品川特別支援学校に越境するとスクールバスが使えないのではないかですが、今のところ、現段階では区はそのような形での情報はいただいておりません。それから、そういうスクールバスに関してはまだまだ就学相談途中ですので、そこまでの話は全く情報がないです。","id":"exchange-068"},{"speaker":"石田（ち）委員","kind":"質問","question":"要は補助事業をしてほしいということなのですけれども、すごく不安を持たれているということで、ちょっとスクールバスのことも聞いてしまいました。そういった部分に放課後等デイサービスを誘致する、もしくは区が建てるといった対策が必要だと思うのですけれども、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"民間のほうでの相談、支援事業所からの状況を把握し、必要性については判断していくということを考えております。現段階では、まだわからない状況が多数ありますので、今のところは補助事業ということで実施というのは考えておりません。","id":"exchange-069"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"以前からやはり放課後等デイサービスを増やしてほしいという要望は当事者や家族の皆様からはあったものですよね。以前からも誘致をすべきだということで私たちも求め続けていましたけれども、この臨海青海特別支援学校の状況も出てきたからこそ、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"９月１日時点では目黒区が１１カ所、渋谷区が１０カ所ということになっております。現段階では民間の相談支援事業所からも、その状況を鑑みると、現段階で補助事業の実施をすべきということは考えておりません。","id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今までは１０日という利用日数の制限があった中で、それがだんだん今は相談に応じてちょっと日数も広がってきている。やはりこうした補助事業をつくって、ぜひそこはさらに増やすという立場で検討していただきたいなと思うのですけれども、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"放課後等デイサービスにつきましては、区内の状況や民間の状況等を鑑みながら、必要性について検討していきたいと考えております。そのため、今の状況としては、なかなか私どもにまだ正確な情報がございませんので、情報をいち早く把握して検討していきたいと考えています。","id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問","question":"ぜひよろしくお願いします。先ほど連絡会を開かれているということで、その連絡会というのはどのようなもので、どれぐらいのスパンで開かれているものなのか伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"１回目は６月に開催いたしまして、今のところ次回は来年早々１月に開催する予定です。事業所については、近隣区含めまして対象となる事業所は３９の事業所です。","id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問","question":"今年度初めてこの連絡会というのが始まったというのは、目的は何だったのかを伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"放課後等デイサービスの事業所連絡会の目的ですが、まずは各事業所の状況の把握、それと意見交換。それから、私どもといたしましても放課後等デイサービスの数が増えるだけではなくて、きちんと質の担保を図っていくというのが目的となっております。","id":"exchange-073"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"例えば新１年生が１８人ということなのですけれども、その対象者のうち何人ぐらい通われているのかなというのを教えてほしいと求めました。小学生・中学生の人数がわかったら教えていただきたいのと、９学年で何人くらいいるのかというのがわかったら、教えていただけたらと思います。","respondent":"松山障害者福祉課長","answer":"申しわけありません、品川特別支援学校に通っている生徒数と、そのうち放課後等デイサービスの人数ですけれども、ちょっと資料がないので。大体一般的にというのはちょっと難しいかと考えています。","id":"exchange-074"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そうなった場合に、放課後等デイサービスの需要がどれぐらい見込まれるのかというあたりは全く皆目わからないという、そのような感じなのでしょうか。認められるとなったら、そこら辺のところはどうなっていくのかがわかったら教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"確かに臨海青海特別支援学校よりは品川特別支援学校のほうが便利で通いやすいというお声はいただいております。私も臨海青海特別支援学校のほうに問い合わせは既にしておりますが、その面談を通じてということで、まだはっきりとした回答はいただいておりません。","id":"exchange-075"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そういうことが認められるのですかと言ったら、使えないという状況になってしまうのではないかというのが今回の陳情の趣旨だと思うのです。品川で断られているという例が結構あるとお聞きしているのですけれども、区としてどう思われているかについてもお聞かせいただけたらと思います。","respondent":"松山障害者福祉課長","answer":"確かに将来的にこの臨海青海特別支援学校が９年生までということであれば、区内の状況がどうなのか、まずは民間でできるところはやっていただいて。今の時点では、なかなかすぐ補助事業の実施を判断するにはちょっと材料としては難しいと考えています。","id":"exchange-076"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１８１名通われているということなのですけれども、このエリアの子どもさんというのは何割ぐらいいるかということがわかったら教えていただきたいのと、その点についてもちょっとお願いしたいと思います。","respondent":"松山障害者福祉課長","answer":"現在の１８１人のうち、このエリアにお住いのお子さんが何人いるかということですが、それについてはちょっと私どもではつかめない状況です。","id":"exchange-077"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひしてほしいと求めました。それが引き続き判断の材料になっていくと思いますので、ぜひ陳述をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"鈴木（真）委員","kind":"質問","question":"自民党としてもいろいろ検討させていただきました。１つ課題としては、民間から複数申し出もあるという状況の中からも、この陳情については不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"若林委員","kind":"質問・要望","question":"送迎が確保されないで、放課後等デイサービスに行けないという子どもは一人も決して出してはいけないという区の姿勢も確認させていただきましたので。会派としては、それはもうちょっとできかねるというさまざまな理由がありますので、この内容については不採択ということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"石田（ち）委員","kind":"意見","question":"結論を出すで、採択をお願いします。そしてまた今区内で放課後等デイサービスを望みながら通えない方々への支援にもなりますので、こうした補助事業が必要だと思いますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"木村委員","kind":"意見","question":"結論を出すで、不採択でお願いします。これからもう少しいろいろ議論をしていくべきであろうと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-082"}]},{"id":"topic-04","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"石田（ち）委員","kind":"確認","question":"そこをちょっと品川区にも確認したいというのと、あと、厚生労働省が出している留意事項は守っているということだったのですね。留意事項を適用する趣旨だと思うのですけれども、ちょっと答弁がはっきりしなかったので、そこも伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"石田（ち）委員","kind":"確認","question":"解消していくべき繰り入れの分野が出ているのですけれども、そこに当てはまっていないというのが厚生労働省から出ているのです。ですので、保険料減免のために法定外繰入をすることはできると思うので、そこを確認したいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/731730?Template=document&Id=3524#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":51417,"voices":224}},{"id":"h30-20181210-8","meetingId":"h30-cm12","date":"2018年12月10日","dateIso":"2018-12-10","committee":"建設委員会","time":"午前１０時００分～午後 ２時３１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を88件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"予定も含めてなかったということなのですが、この面談というものはいつ決まったのか、どのような経緯で決まったのか伺いたいということが１つです。それと今回、再三再四議会でも指摘しましたが、今回の面談の記録というものは公文書で残したのかどうか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"面談の決定日時についてですが、担当者レベルでは、区のほうでぜひ国のほうにお伺いして、要望等を行いたいというところの調整はしてまいりました。１１月１６日の決算特別委員会でご質問をいただいたときは、その旨回答したわけですが、１１月２２日に実施されたです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"この委員会資料とかなり違う内容なのか、その辺を少しお伺いしたいということが１つあります。本会議での、おくの区議の一般質問で、しっかり届けていないのではないかと思うのですが伺います。","respondent":"鈴木都市計画課長","answer":"国の回答というところが、口頭でのやりとりという中での議事録が、今回委員会のほうで示させていただいた内容です。これは区のほうでも教室型説明会、こうした実施が区民の方からも非常に声として大きいというところ、その一連の流れの中でやりとりとして出たです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"これを届けない、届けていないということはなぜなのか、区民の中に多くの反対意見があるとは認めないということなのですか。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"決して反対意見があるということを伝えないということではございません。やはり非常に声として大きい教室型説明会をしっかりやっていただいて、品川区民に向けてこの計画案を説明していただいて、やはり理解の度合い。","id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"伺いますけれども、この冊子のこの箇所というものを区は読んだことがないのですかということを伺いたいということが１つです。それともう一つ、この落下物対策基準の実効性というものが担保された場合、落下物はゼロになるのかということもあわせてお伺いしますとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"環境影響に配慮した取り組みの中で、これも騒音環境の低減に向けた取り組みをそれまで区が再三再四要望してきた中で、国の対応があります。やはり国のほうはこうした取り組みを進めて、落下物ゼロを目指すという形で取り組んでいるということで承知しているものです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"落下物対策の実効性ということを求めるのであれば、それを求めていただきたいのですけれども、落下物との関係でいかがですか。それが最大の落下物対策ではないのですかと伺います。","respondent":"鈴木都市計画課長","answer":"区のほうとしては、これまでお話ししてきたとおり、落下物対策については少しでもゼロに近づけるというところの中で、国に再三再四求めてきたところですので、そうした取り組みをさらに実効性あるものとしていけるように、引き続き国のほうに交渉していきたいです。","id":"exchange-005"},{"speaker":"筒井委員","kind":"確認","question":"当然品川区の職員の皆さんも含めて、そうした状況というものをまず国はしっかり認識されているのでしょうかということをお聞きしたいのですけれども。そういったことを確認したいので、その国の、区のマイナスの状況についての認識はあるのかということをまずお聞きします。","respondent":"鈴木都市計画課長","answer":"ただ、これにつきましては国のほうからも伊丹や福岡の事例も挙げて、その直接的な因果関係は示されていないというところのお話があったところです。","id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"品川区にとってマイナスな状況があるとわかっていても、やはり国としてはこの羽田新飛行ルート案、どうしてもやりたいというお立場なのか尋ねました。","respondent":"鈴木都市計画課長","answer":"これは事実だと思います。そのようなことも含めて国は実施するのかですが、そうした国のほうの説明は、それでも進めるのかというお話をいただきましたが。","id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"それは国は確かにそのようなお考えだということはわかりましたけれども、品川区にとって先ほどお話ししたマイナスの状況というか、影響もあると。やはり影響が大きいからとか、住民の反対が大きいからとか、まさにこの新ルート案だけというようなお考えだったのか尋ねました。","respondent":"鈴木都市計画課長","answer":"例えば羽田空港を活用する方策、あるいは今お示しいただきましたが、首都圏のほかの空港を活用する方策についても議論がなされてあります。","id":"exchange-008"},{"speaker":"筒井委員","kind":"質問・要望","question":"５番目の滑走路を新設するとか、わずかでも可能性が、区としてもやはり国にそれをぜひお伝えしていっていただきたいと考えております。今回の、品川区としてまず常設型展示による情報発信というものを要望しているわけですが、この常設型展示について国はどうお考えなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"教室型説明会、常設型展示というところはしっかりお伝えをして、やりとりの中で地域ごとの説明会という発言は国のほうからあったものです。常設型展示の設置についても、今対応に向けて検討いただいているという理解、受けとめ方です。","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問","question":"では、担当者レベルでそのようなお話は進められているので、将来的には、いつかの段階では実施、実現に向かっているということでよろしいか尋ねました。","respondent":"鈴木都市計画課長","answer":"この面談の中で、国のほうで具体的な常設型展示という言葉は出ませんでしたが、受けとめ方としては、これをぜひ実施していただくように、しっかり区のほうでも協議をさせていただいているです。","id":"exchange-010"},{"speaker":"筒井委員","kind":"確認","question":"この新飛行ルート案をやっていくというスタンスだということはもう確認されましたけれども、私としてはもちろんやめてほしいのですが。一般住宅まで防音措置というものをぜひやってほしいというお声が多いのですけれども、国はどのようなお考えなのか、それをお知らせください。","respondent":"鈴木都市計画課長","answer":"国のほうは法律を、施行令を改正して、その対象を広げたというところが１つ事実としています。この新飛行ルート案がもし実施された場合、住宅の場合、都内にはそういった対象になるようなエリアは出ないというところで聞いているところです。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問","question":"特に直下の地域については、これは最低限一般住宅にも防音工事助成をするべきだと思うのですけれどもいかがでしょうか。これはもう、特例措置などといったことをぜひ設けていただいてやってほしいのですけれども、その点ぜひお伝えをお願いしたいのですが。","respondent":"鈴木都市計画課長","answer":"先ほどちょっと数字をお示しできませんでしたけれども、住宅であればＬｄｅｎ６２デシベル以上というところが対象になるわけです。そうした地域が品川区内では住宅地のほうには発生しないというところで、国のほうからは聞いているです。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"その従前の法律というものは、なぜその基準値を設定したのかということはおわかりでしょうか。恐らく余り広げ過ぎると、莫大な費用がかかってくるとか、そういった理由だろうと思うのですけれども、わかれば説明を求めました。","respondent":"鈴木都市計画課長","answer":"住居系の場合やその他の場合というところでいろいろ定めがありますので、そうした基準にのっとってこの数値は定められているというものです。その対象が広がるから、その数字を上げる、下げるという形で設定されているものではございません。","id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"学校の施設や医療施設はやってくださるということなのですか。それは法律の例外としてやってくれるということか尋ねました。","respondent":"鈴木都市計画課長","answer":"おおむねその中の３時間というところでございまして、時間を限定する形でより多くの施設が対象となるというようには国から聞いてあります。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問・要望","question":"これはもう品川区は一番最悪な被害を受けるところですから、区民にとってもマイナスしかないと思いますので、その点を改めてよろしくお願いします。いかがお考えか尋ねました。","respondent":"鈴木都市計画課長","answer":"住宅の場合は先ほどご説明したＬｄｅｎ６２デシベルですが、その他の施設についてはＬｄｅｎ５７デシベルと。児童福祉法の中の家庭的保育事業というところの分類をさらに細かいところまで対象を広げてきたというところが、国の取り組みとしています。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問・要望","question":"それを２４時間で時間をならすという考えは、今課長おっしゃられたように、一般住宅の防音措置ということを要請していってほしいと求めました。その点もう一言、。","respondent":"鈴木都市計画課長","answer":"どういった形で住宅まで広がるかというところは、何度もこれはやりとりさせていただいて非常に難しいといいますか、もともと設定しているベースがございましたので、ただいろいろな場面、担当者レベルのやりとりの中では、その話はさせていただきたいというふうに考えてあります。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問・要望","question":"質問としては、これ発生したときには適時的確な区への情報提供を図られたいというところでわざわざ要望されている、その背景。これが担保と言えるのかどうかというところで、かなり踏み込んだ話があったのかどうかというところを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"世界に類のない初めてという形で国内、やはりこれが確実に実施されて初めてその全体の取り組みが実効性があるものとなっていくです。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これがまず全戸配付をされたのかどうかということ、これは第２回定例会でも我々は求めていましたけれども、周知というところでですね。第５フェーズですか、これは載せられなかったのかという疑問、これについて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"聞いているのが約１１万１,５６０世帯というところでございまして、品川区の世帯数が２１万５,０００世帯ですので約５１％程度の周知です。それからもう１点が、教室型説明会の周知ですが、なかなかまとまらなかったというところが現状です。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問","question":"まあ本気なのでしょうけれども、間に合わなかったということであれば仕方がないとは思うのですが、一歩前進と捉えていきたいと思います。私も自分の地域は、自分の地域ですから出たいと思っているのですが、当然ここには区の職員もいらっしゃるということでよろしいか尋ねました。","respondent":"鈴木都市計画課長","answer":"説明していただくのは国のほうが前面に座って説明していただきますが、区のほうでもその会場には参加といいますか、当然いるようにしたいです。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"といいますのは、第２回定例議会のほうであくつ委員が一般質問されていまして、「会派として新飛行ルート案を容認することはできない」と。この再考というものは求められたのか、関心があるところなので、その辺はいかがなのかということをまずお伺いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"意見","question":"区民の不安を利用するようなことは我々はくみしない、このように考えておりますので、それが全てですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"再考を強く求めていただいたのかということの答えがないのですが、答えられないということなのかわかりませんけれども、ぜひその辺は明らかにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問","question":"今のこちらに対する質問ですけれども、先ほど申し上げたとおりです。党利党略に利用されるつもりはありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは間違いなのでしょうか。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"これは区のほうで再三教室型説明会をやっていただきたいというところは要望として申していまして、どちらが主催といいますか、ある意味一緒にやると。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、共催なら共催と書いてほしいと求めました。ポスターなど、ぜひ掲示していただきたいのですが、それぞれいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"当然それは否定するものではございませんで、区としてもより多くの方に来ていただきたいですので、それはぜひお声をいただければです。ただ、まずはやはり管内の町会の方に回覧をもってしっかり、あるいは区のホームページをもってしっかり周知をするです。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"その説明の内容なのですけれども、最小限にしていただいて、質疑の時間を十分確保すべきだと思うのですが、いかがでしょうか。これも伺います。","respondent":"鈴木都市計画課長","answer":"今現在国のほうとは協議中ですが、どの程度説明に時間を要するか等も含めて、その辺は国と協議してまいりたいです。最後に何を説明するかですが、落下物対策や、そういった説明はその説明会の中でもしていただけるのではないかと思います。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"なぜ難しいのか伺います。その辺を少し確認したいと思います。","respondent":"鈴木都市計画課長","answer":"いろいろな説明会があろうかと思いますが、私はもう少し質問したいのだという方も、状況によってはあろうかと思います。これはオープンハウス型でも手法として実施されておりますけれども、既に案内しているとおり、この記載の時間の中で進めていきたいです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"チラシのほうはなぜ難しいのかということをお伺いしたいのですが、その辺なぜ難しいのかということを伺ったのでお答えほしいと求めました。ですから、区民の声をつかむ必要があると思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"説明会実施に当たって、やはり一定広く区民の方に向けて行う説明会につきましてはホームページ、回覧等々で周知を行っているです。それからアンケートの実施ですが、やはりこれもご答弁差し上げているとおりですけれども、やはりこれは国の事業です。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"区民の声をつかむ必要があるのではないですかということを伺いたい。そもそも区民の意向をつかむ必要があると区は考えていないのか尋ねました。","respondent":"鈴木都市計画課長","answer":"これまでもさまざまな機会を捉えて国のほうには伝えているところでございまして、その１つとして教室型説明会が今回実施されると。それからアンケート、これも重ねてですが、やはりこれは実施については、もしやるのであれば国のほうが国の責任においてしっかりやっていただくと。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"そもそも区民の意向をつかむ必要がないと区は考えていらっしゃるのですか。区民の意向をつかむ気がないと、そのようなことなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"区民の意向を区が把握する必要がないということは、これまでも全く申してございません。それを実施していくのは、これは事業主体である国が行うべきというところを再三申し上げているところです。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですからこういったことを区がなぜやらないのか。アンケートの必要性についてどのように考えているのか、最後にもう一度伺います。","respondent":"鈴木都市計画課長","answer":"先ほど委員からもご紹介いただきましたが、これ説明するべきは国です。地域の理解を得ること、丁寧に説明していただくこと、これは事業主体である国がしっかり行っていただくと。","id":"exchange-031"},{"speaker":"大沢委員","kind":"質問","question":"天候はいろいろとあるわけでありまして、このゴーアラウンドに対しての、他の空港におけます対応はどのようにとられているのか。これは区の範囲ではないかもわからないですけれども、ご存じであればそこのところを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"詳細にほかの空港について直接、あるいは国のほうに確認はしてございませんが、ゴーアラウンドへの対応はどこの空港、あるいは自治体でも同じかと。","id":"exchange-032"},{"speaker":"大沢委員","kind":"質問","question":"同じということで、では実際に他の自治体、他の空港に関しても、品川区と同様で情報の提供を図るということで終わっているという、このようなことでいいのか尋ねました。","respondent":"鈴木都市計画課長","answer":"あるいは関係する自治体にお知らせをするということは、ほかの空港、自治体でも同じかというような理解です。","id":"exchange-033"},{"speaker":"大沢委員","kind":"質問","question":"気象、気流等々で難しいと思うのですけれども、このゴーアラウンドについての決まった航路という、そのようなものはあるのですか、ないのか尋ねました。","respondent":"鈴木都市計画課長","answer":"基本的にはそこに待機している飛行機の数や、そのときの進入ルート等で判断するので、決まった定期ルートはないというところは聞いてあります。","id":"exchange-034"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、今後実施される教室型説明会について、先ほど課長はその対象地区の方を優先にされるというような旨のお話をされましたけれども、その点何か、その対象地域の人かどうかということを判断する方法というものは、どのようにお考えなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"それも今ちょっと国のほうと協議中なのですが、やはりどのような説明会もそうですけれども、まず一定お名前とご住所をお書きいただくと。地域の中の方なのか、外の方なのかということを確認しながら、地域の方を優先していきたいという形で進めたいと考えています。","id":"exchange-035"},{"speaker":"筒井委員","kind":"意見","question":"先ほど国の責任においてやるべきというご答弁がありましたけれども、昭和５１年の９月には区がやられておるのです。この場合は品川区が主体としてやったのですけれども、なぜ今回は国でやるべきというご主張なのかとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"今ご紹介いただきました、あるいは請願の中にもあります、昭和５１年当時の意識調査、これは区が実施しています。事業主体の国のほうが行う事業として説明を行っているものですので、これは当然、実施するべきは国のほうが行うべきというものです。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問・要望","question":"品川区としては国に対してそのようなアンケート調査をやるべきだということを求めているのかということと、また私は、その点いかがでしょうか。ぜひ品川区としてもアンケート調査をやってほしいのですが、その点いかがお考えなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"これは議会のほうからも要望として出ている内容ですが、教室型説明会、丁寧な区民への周知というところを再三再四国のほうには求めているところです。","id":"exchange-037"},{"speaker":"筒井委員","kind":"質問・要望","question":"次、その教室型説明会をやっていただきたいという要望なのですが、やはり防音措置や区民の不安払拭に努めなくてはいけないと考えています。平成２８年９月１日の広報しながわに載っていますとおり、私としてもぜひやっていただきたいと思っていますが、その点いかがお考えなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"その具体的な内容をこれから行われる教室型説明会で国が行うかどうかは。ご質問の中でのやりとりになるかもしれませんが、国のほうとはこれからしっかり協議をしていきたいです。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"教室型説明会で品川区関連事項の説明をやってはいかがですかというお話なのですけれども、品川区関連事項のお話をするという説明会、この実施についてなのですが。","respondent":"鈴木都市計画課長","answer":"いろいろな手法を活用して、しっかり区民の方にも説明していきたいというふうに考えてありますが、今予定はしてございません。そうしたやりとりについてはしっかり区民の方に、いろいろな手法を活用して発信していきたいです。","id":"exchange-039"},{"speaker":"松永副委員長","kind":"確認","question":"私からは確認でご質問します。確認ですが、そこで多分ご質問等があるとは思うのですが、その状況についてお伺いしたいと思います。","respondent":"鈴木都市計画課長","answer":"これも今現在協議中ですが、撮る角度によっても個人のプライバシーもありますし、今のところはご遠慮いただこうかなというふうに考えているものです。","id":"exchange-040"}]},{"id":"topic-02","title":"平成３０年請願第１９号 特定整備路線 放射２号線 現状を見直し改善を求める請願","agenda":"平成３０年請願第１９号 特定整備路線 放射２号線 現状を見直し改善を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"現在の放射２号線の土地の買収率といいますか、取得率をお伺いすることと、それと資料の写真の中に車がとまっていると思うのですけれども、これは誰が使っているものなのか、わかれば説明を求めました。","respondent":"鈴木都市計画課長","answer":"現在の放射２号線の用地取得率ですが、１９％程度です。都の職員等々がこちらに来て、この放射２号線関係で仕事をするに当たって、仮にとめている状態かというふうに考えられます。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、区内ではこのように暫定公園として活用されてきた例というものは結構あると思うのですが、このような将来の事業予定地ですね。それらがどこにどのような例があるのか、わかれば教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"これまでさまざまなところで都市計画道路が進められ、都であったり、区であったりですが、過去の事例としては、一定程度の形がまとまったところは協議をして、そうした区民への貸し出し等のために、一定暫定的に使わせていただいたという事例はあります。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"あるいは必要なのかどうか、求められているのかどうかということをしっかりと、つかんだ上でチェックしていくということが私は必要だと思うのです。私はこの手引きにしたがって、この放射２号線というものを見直す必要があると思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"先ほどの過去の活用の事例で、少し説明が不足していたところがあります。都のほうが進めていくところにしっかり協力をするというスタンスです。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"それでまともな道路、まともな都市計画になるのですかと私は思うのですけれども、これでいいのでしょうか。伺いたいと思います。","respondent":"高梨木密整備推進課長、鈴木都市計画課長","answer":"最初に私から、今ご紹介のありましたのんき通り沿い、もしくは二葉にあります暫定公園についてご説明をします。さらなる、いわゆる防災広場としての拡張が見込まれるといったようなことで、暫定的にあのような形で整備しているです。 当然ながら今回事業決定するに当たっては、東京都において住民説明会、あるいは法に基づく公告縦覧など、しっかり手続きを踏んで計画が進められているです。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは一度も計画の賛否を問われることなく、この計画が事業化されているということでいいのですかと伺いました。、答えるよう求めました。","respondent":"鈴木都市計画課長","answer":"事業主体の東京都がしっかり手順を踏んで進めていっているですので、地域の防災性の向上のため取り組んでいるというところについて、区のほうもしっかり協力をするというスタンスです。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"請願の３つ目の理由について関連して伺うのですけれども、避難ルートだというお話が、説明でもありました。こうした道路というものは、本当に住民を交えてその賛否を含めて再検討しなければいけないのではないかと思いますけれども、いかがか尋ねました。","respondent":"古巻防災課長、高梨木密整備推進課長","answer":"３・１１のときのことを事例に出されていますけれども、いわゆる今後発生するであろう首都直下地震とかなり状況は違うのかというふうに考えています。とりあえず状況としてお答えしました。私からは、今このような道路予定地が囲われて、何の効果も発しないといったところについてご説明をします。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"ですから私は、一定の延焼遮断効果はできるわけですから、そうすれば一定防災性も向上しているわけです。ですから、膨大な労力と膨大な経費と、そして犠牲を払って、このような道路を遮二無二つくっていくということは、私は見直すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"大沢委員","kind":"質問","question":"公園について伺いたいのですけれども、そのように簡単に公園というものはできるものではないと私は思っているのですけれども、そこのところをどのように考えているのか説明を求めました。","respondent":"溝口公園課長","answer":"委員のご指摘のように、やはり公園に適した敷地を確保していくということは非常に難しいところです。区の一定の方針としましては、引き続き公園の整備、そういったものには取り組んでいきたいと考えているところです。","id":"exchange-048"},{"speaker":"大沢委員","kind":"質問","question":"公園が２つぐらい近隣にはあると思うので、地元の自治体である品川区の皆さんが近隣の住民の方とお話をされている部分も多いと思うのですけれども、実際はそのような声というものは上がっているのか尋ねました。","respondent":"鈴木都市計画課長","answer":"個別具体の対応は東京都が行っているわけですが、具体的に地域の方から、この地域に公園が少ないので、暫定的といえどもこの空間を公園として整備してほしいなどという具体的なお話はいただいておりません。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"確認","question":"本日結論を出すで、会派の地元の議員にも確認をしてまいりましたが、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択です。計画そのものを見直すべきだということもあわせて、採択したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"筒井委員","kind":"意見","question":"本日結論を出すで、不採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"}]},{"id":"topic-03","title":"平成３０年請願第２１号 都営地下鉄中延駅（東中延２丁目口）のエレベーターなどの設置に向け、品川区が東京都と連携して取り組むことを求める請願","agenda":"平成３０年請願第２１号 都営地下鉄中延駅（東中延２丁目口）のエレベーターなどの設置に向け、品川区が東京都と連携して取り組むことを求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"あるとしたらどのような内容だったのでしょうか。Ａ３口の利用状況について、どのような結果だったのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"都営中延駅におけるエレベーター設置についての東京都とのやりとりですが、これまでそうした場を設けて、現在まで行ってはございません。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"お伺いしたいのですけれども、この駅利用者数の推移というのですか、そしてこのＡ３口の利用割合というものはどれぐらいなのか、教えてください。それと、区としてはこのＡ３口へのエレベーター、またはエスカレーター設置の必要があると考えているのかどうか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"それから、区としてこの出入り口のエレベーターの設置が必要かどうかですが、法的にはワンルートが確保されている状況です。東京都としてどう考えるかというところもありますが、エレベーターがあれば利便性が高まるというところは、現地を見て感じたところです。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから非常に、やはりＡ３出口にエレベーター、なかなかこれは大変な状況だということを現地で私も実感をいたしました。財政的な問題だけクリアできれば、別に問題なく設置できるものなのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"Ａ３出入り口のほうに、ちょっと引きの写真で非常にわかりづらくて申しわけございませんが、交通局が管理をします出入り口のための建物があります。いろいろ検討しなければいけないところが、現地を見た限りですが、印象を持ったところです。","id":"exchange-055"},{"speaker":"安藤委員","kind":"確認","question":"技術的に難しいということですけれども、区としては技術的に無理だということはないと。設置不可能だということではないことでよろしいのか、確認をお願いします。","respondent":"鈴木都市計画課長","answer":"今申し上げましたように、目視ですので技術的な検証は全くしてございませんので、当然ながら技術的に検証を行うべきは東京都ですので、できるかどうかということは、ちょっとこの場ではお答えできないです。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問","question":"その辺はどうなのか。今言ったような課題というものは、区としては特に把握していないということなのか、もう一度お伺いします。","respondent":"鈴木都市計画課長","answer":"そこの部分に都市計画道路補助３０号線、また国道のほうは放射１号線、今ちょっとお答えしかねるです。","id":"exchange-057"},{"speaker":"安藤委員","kind":"質問・要望","question":"設置されることによって利便性は向上するということですから、若干生煮えの状況といいますか、必要なことだと思います。測量なども行っておりましたので、ぜひ区として都としっかりとこれから連携をして、協議をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問・要望","question":"確認のために申し上げますけれども「Ａ３出入り口は東急大井町線中延駅の最寄りの出入り口であることから、現地測量や流動調査を行ってきた。その上で私も地元の議員に確認をさせていただいて、ぜひ東京都のほうともこの可能性について協議をしてほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"東京都のほうに確認させていただきながら、この箇所へのエレベーター設置について協議といいますか、やりとりはしっかりさせていただきたいというふうに感じているところです。","id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問・要望","question":"失礼しました。協議という言い方をして大変失礼申し上げたのですけれども、連携をとっていただいて、そこについては確認をしていただきたいということであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"筒井委員","kind":"質問","question":"それとも容易になる方向に行くのですか。どうか尋ねました。","respondent":"鈴木都市計画課長","answer":"現在の出入り口が、先ほどご説明した第２京浜、またそれに交差する形の補助３０号線、その拡幅後のラインを避けた形で建ってあります。仮に事業決定されて今後整備されれば、今都市計画道路内にはそうしたエレベーターの出入り口等は法的にも設置できないです。","id":"exchange-061"},{"speaker":"筒井委員","kind":"質問・要望","question":"これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"今のところは、この３０号線の予定があるということなのですけれども、この用地、３０号線の道路は区道の都市計画道路の予定ですが、そこの三角の土地である用地の所有者というものは、今現状どうなっているものなのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"その隅切り部分のことだと思いますが、その部分については東京都の所有地です。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"ですから品川区が東京都と協議して、必要なことだと思うのですけれども、いかがでしょうか。これはつくれないという法律的な根拠というものはあるのかないのか伺いたいと思いますし、区内に限らずほかにないのか伺いたいと思います。","respondent":"長尾建築課長、鈴木都市計画課長","answer":"都市計画法の第５３条の中で、計画道路等の都市計画施設の中に建築する場合に関する制限があります。現状ですと建物ですと３階建てまで、地上１０ｍの高さまでということで、現状の第５３条に基づく許可の運用状況になっております。どうしても今回地下構造物が伴うというところで、先ほどのご紹介の中にはなかなか困難さがあるというところがあったのかというふうに認識しています。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問・要望","question":"私が伺ったのは、エレベーターというものがつくれないという法律的な根拠はあるのですかというか、その法律の内容を説明してほしいのですが。ですから、ちょっとそれはおかしいということを言いたいと思います。","respondent":"長尾建築課長","answer":"地下の構造物をつくるということになりますので、都市計画法の第５３条の許可要件に合致してこないということになりまして、つくれないということになります。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問","question":"ただ、それでいいのですかという問題はあるかもしれないですけれども、運用の工夫でこういった混雑にも対応できるのではないかと。だからエスカレーターの設置というものは現状でも可能なのではないかと思うのですけれども、区のお考えがあればお伺いします。","respondent":"鈴木都市計画課長","answer":"それが、乗るところの空間だけを捉えれば設置が可能ということですけれども、東京都がしっかり検証していただくというところかなと。やはり細い１人乗り用のエスカレーターを設置すれば、これは東京都がしっかり検討いただくことですけれども、その検討の中において。","id":"exchange-066"},{"speaker":"大沢委員","kind":"質問・要望","question":"さまざまなものの１つにエレベーター、エスカレーターの設置を求めるという声が請願として出てきておりますけれども、継続でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"松永副委員長","kind":"意見","question":"この請願に書かれているＡ３出口へのエレベーター・エスカレーターの設置についてですが、物理的に難しいと理解しております。Ａ３出口を利用される方は約８割を超えておりますので、決めていかれることが望ましいと考えまして、この請願については継続としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"筒井委員","kind":"質問","question":"都と協議や話し合いをされていくということで、その都との話し合いの内容を、引き続きその推移を見守っていきたいと。それでまた議論していきたいということで、継続でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問","question":"気軽に外出できるようになるということが区の事業の活性化にもなるし、本人の健康づくりにとってもいいことだし、本当にいいことだと思うのです。そうすべきだと思うのですけれども、またどのように検討していくお考えなのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今ご紹介いただきましたように、さきの第３回定例会の一般質問の中でもご答弁差し上げましたとおり、来年度からしっかり検討してまいりたいです。","id":"exchange-070"},{"speaker":"安藤委員","kind":"質問","question":"今の時点でどのように考えているのか、伺いたいと思います。私もそうあるべきだと思うのですけれども、これについての区の考えは、現時点でどうなのか伺います。","respondent":"鈴木都市計画課長","answer":"そうした既存の枠組みなどを総合的に勘案して、来年度以降しっかり検討していきたいです。これも第３回定例会でご説明しましたけれども、例えば鉄道、バス等が区民の生活には本当に必要不可欠なインフラだというようには認識しています。","id":"exchange-071"},{"speaker":"安藤委員","kind":"質問・要望","question":"それ以外は１００円程度の低廉な料金にするようにということを会派としては求めたのですけれども。やはり区民の生活向上、そして移動する権利をしっかり保障するという観点から必要な事業なので、そこはなぜなのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"さまざまな視点で検討していかなければいけないわけですが、頭から事業採算性を外して検討するということはなくて、いろいろな各区の状況を見る中で。その中でこの視点を抜きにして進めるということは、しっかり総合的に検討していきたいというふうに申し上げているところです。","id":"exchange-072"},{"speaker":"安藤委員","kind":"質問・要望","question":"その会議体の話で、先ほど平成２６年設置の検討会を活用しながらという話もありましたけれども、これを再開するということなのですか。そもそもこの会議体の目的というのは何を検討していくのかということも含めてもう少し具体的にお伺いしたいと思います。","respondent":"鈴木都市計画課長","answer":"来年度以降まずは検討を進めていくわけですが、単年度のみということではございませんが、数年かけてしっかり検討していきたいです。そうした法定会議体への移行が必要になってきますので、そうしたところもしっかり行っていきながら検討を進めていきたいです。","id":"exchange-073"},{"speaker":"安藤委員","kind":"質問・要望","question":"検討メンバーについて改めて誰が入っているのか、そしてそれに加える考えはあるのか伺いたいと思います。各一定のエリアそれぞれから満遍なく、複数の公募区民の参加というものが必要だと思うのですが、あわせていかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"地域交通検討会のメンバーについてですが、現在学識が２名、今の会議体です。区民の方にどういった形で入っていただくかというところは、しっかりその会議体へ移行していく中で検討していきたいです。","id":"exchange-074"},{"speaker":"安藤委員","kind":"質問・要望","question":"このようなものはやるべきだと思うのですけれども、いかがでしょうかということをもう一度お伺いしたいと思います。ネットワーク状況など、行き先との関係での調査というものが私は必要だと思うのですけれども、この点はいかがということを２つ目にお伺いします。","respondent":"鈴木都市計画課長","answer":"それから、あわせてやはり検討、あるいは実施に向けて進んでいく中で、区民の方の声というものをこの計画を進める上でしっかり反映させていきたいと。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問","question":"最後、ごめんなさい、１点だけ。そういうもの、行き先との関係での調査というものはどうしても必要だと思うのですが、その点についてもう一度お伺いします。","respondent":"鈴木都市計画課長","answer":"今ご紹介いただいた内容も含めて、しっかり検討していきたいです。","id":"exchange-076"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、品川区としては地域公共交通会議等々で想定外の出来事がない限り、品川区としてコミュニティバスを運行させるという方向でよろしいのか尋ねました。","respondent":"鈴木都市計画課長","answer":"基本的には実施していく方向で検討していきたいですが、まずはどういった枠組み、あるいはそういった事業採算性を含めて、ゼロベースというわけではございませんけれども、導入を見据えておりますが、やはり基礎的なところから積み上げていきたいと考えています。","id":"exchange-077"},{"speaker":"筒井委員","kind":"質問","question":"地域公共交通会議でいろいろとお話しされることだと思うのですけれども、まずこのコミュニティバスは完全に区営でやっていくのか、それとも民間委託でやっていくのか、その辺の方向性は今どの程度お考えなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"そこもしっかり検討していく予定なのですが、今のところないかなと思いますけれども、いろいろな視点で検討はしていきたいとは思っております。","id":"exchange-078"},{"speaker":"筒井委員","kind":"質問","question":"区内企業の広告を載せたり、品川区のシティプロモーションのラッピングなどもやってもいいかとも思うのです。いろいろアイデアやお考えはあると思いますけれども、今言ったように防災や環境、その点品川区としてはいかがお考えか尋ねました。","respondent":"鈴木都市計画課長","answer":"この段階でも調べてみますとコミュニティバスの運行経費、約３分の２以上が人件費というところで、非常に大きいということは聞いてあります。検討していく中で、そうした、そうしたところを加えて多角的に検討していきたいというところは考えてあります。","id":"exchange-079"},{"speaker":"筒井委員","kind":"質問","question":"地域公共交通会議の人選についてなのですけれども、やはり今までの地域交通検討会がベースですと、ちょっと人数が足りないのかと考えています。やはり品川区の１３地区から代表を出して参加していただくことや、また、その点いかがお考えか尋ねました。","respondent":"鈴木都市計画課長","answer":"平成２６年に設置して、あるいはその移行後の会議体の区民の方の参加についてもしっかり検討しながら行っていきたいというところとあわせて進めていく中では、しっかり検討していきたいです。","id":"exchange-080"},{"speaker":"大沢委員","kind":"質問・要望","question":"慎重な議論をしながら進めていくという認識で私はおったのですけれども、ずっとここ数年、何かなし崩し的に進んでいる感がどうしても否めない。やめることはなかなかできないものですから、１００円バスなどいろいろな名前、このコミュニティバスの議論を深めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"あくつ委員","kind":"提案","question":"まずこの法定の地域公共交通会議というものを設置して調査をしてみたらどうだというご提案をさせていただいて、区のほうでは法定ではないけれども。ですから、これをしっかりと選定していただきたい、このように考えておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-082"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択でお願いしたいのですけれども、やはりコミュニティバス導入ということは、切実な区民の暮らしの実態から出てくる声なのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"松永副委員長","kind":"意見","question":"我が会派は、継続とします。その検討会の動向を見て、今後について考えていきたいと考えていますので、この請願に関しては継続としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択ですが、コミュニティバスの運行をしてくださいという内容なので、採択してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"}]},{"id":"topic-04","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"報告第２４号で、これ「同車の後輪等を破損した」ということで、損害賠償云々かんぬんで修理費等という、「等」には何が含まれるのか尋ねました。","respondent":"多並道路課長","answer":"後輪、後ろのタイヤのパンクした修理費用と、あとスタンドが破損したということです。その修理に１日かかってしまった関係で、そのバスの費用と電車の費用ということで、合わせて１万３,９１５円となっているものです。","id":"exchange-086"},{"speaker":"安藤委員","kind":"質問","question":"その状況から、なぜ街路樹が強風に耐えられなかったかなどの原因というものは判明したのでしょうか。報告第２４号は、歩行者や自転車の転倒、同様の箇所がないかという点検の体制というものはどうなっているのかお伺いします。","respondent":"多並道路課長","answer":"今後の対応といたしましては、点検を徹底していきたいということで、我々としては行っていこうと思っています。路面だけではなくて、集水ますについても点検していくということで、重層的に点検しようとしています。","id":"exchange-087"},{"speaker":"筒井委員","kind":"質問","question":"この２件とも、過失というのは区の点検義務違反によるものだということ、そういった意味で過失とおっしゃったのか尋ねました。","respondent":"多並道路課長","answer":"今委員のご指摘のとおり、我々の今までの事例と、あとは契約されている保険会社といろいろなほかの過去の事例などを勘案して協議させていただいて、ご本人と示談した結果、やはり区のほうが全体的に過失があるということで、このような結果となりました。","id":"exchange-088"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/146532?Template=document&Id=4250#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":62565,"voices":257}},{"id":"h30-20181210-9","meetingId":"h30-cm12","date":"2018年12月10日","dateIso":"2018-12-10","committee":"文教委員会","time":"午前１０時００分～午後 ２時０３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件整理しています。","topics":[{"id":"topic-01","title":"第９２号議案、指定管理者の指定","agenda":"第９２号議案、指定管理者の指定","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"４の候補者選定経過のところの（１）、ここの品川区指定管理者制度活用に係る指針のところにかかわって教えてほしいと求めました。","respondent":"吉田保育施設調整担当課長","answer":"ホームページでも公開しておりますけれども、品川区指定管理者制度活用に係る指針というのがございまして、その中で、一定程度、継続性とか、特殊な事情が必要なものにつきましては、候補者を公募しないで選定委員会を行っても構わないこととなっております。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"１つ質問したのですけれども、４６人中１７人の回答とあるのですけれども、第三者評価を受けたのは認可保育園の部分だけなのでしょうか。認可の施設の３歳から以降の評価はどこにされているのかというのが疑問だったので、ここのところを説明を求めました。","respondent":"吉田保育施設調整担当課長","answer":"保育サービス推進費等を活用しまして、特別賞与を上げるなど、そのような対応を積極的に行っております。そういう意味で勤務継続も、今は４.４年ぐらいまで延び、職員の雇用も比較的長くなってきております。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"保育園は認可なのだけれども、ここでの働きをカウントされないことに問題を感じているというところは改善されたのかどうか、そこが１点です。３歳以上の、第三者評価的なものできちんと評価をされているのかどうか、そこをもう一回お伺いします。","respondent":"吉田保育施設調整担当課長","answer":"幼児教育部門につきましては無認可扱いになりますので、認可保育園に勤めたというキャリアには確かにならないところがあります。現行の仕組み自体がゼロ歳児から２歳児までが保育園でございまして、３歳児から５歳児までにつきましては幼児教育施設、今も変わっておりません。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"一般の幼稚園とか区立の幼稚園に勤めると経験年数が加算されるけれども、ぷりすくーるのここは加算されない。認定こども園に移行すれば、ここのところは改善されていくのかどうか、そこがとても気になっているので説明を求めました。","respondent":"吉田保育施設調整担当課長","answer":"認定こども園に移行した場合は、認定こども園という施設になりますので、認定こども園で働いたというキャリアになるところです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"乳幼児教育の幼稚園の部分も、そこをもう一回お伺いしたいのと、この先の見通しが何かあるのだったら教えてほしいと求めました。どこがどう評価しているのか、３歳以降のことをさっきから伺っているのは、そこの評価が探せなかったのです。","respondent":"吉田保育施設調整担当課長","answer":"あくまで就学前のゼロ歳から２歳までは保育を実施する、それから、それ以降のところでは教育を実施する。幼児教育部門、就学前保育から教育までを一貫して考えるという制度ができたところで、国の制度のほうが今は追いついているというのが現状です。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"課題が何なのかをもう一回明確に教えてほしいのですが、この間、園庭が今の状態だと認定こども園にならない。社会福祉法人化が多分平成３２年、法人化されていない、クリアしなくてはいけない問題が何かあったら聞かせてほしいと求めました。","respondent":"吉田保育施設調整担当課長","answer":"ただし、現状のぷりすくーる西五反田においては、必要な園庭の部分の面積を、約１００m2近く満たすことができません。そのため、幼保連携型認定こども園化は、現在のところそこでの調整は進展しておりません。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"意見","question":"今、社会福祉法人化が平成３２年ということなのですけれども、指定管理が今回５年です。その辺の課題、何かクリアするような問題があるのかどうか、聞かせてくださいとの意見を述べました。","respondent":"吉田保育施設調整担当課長","answer":"答弁が漏れました。そのまま継続して指定管理をするということについては、他の自治体でも例はありますので、特に問題がないと認識しております。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"何かめどがあるのかどうかを教えてほしいのと、このままやっていくのかどうか、そこの２点だけ教えてください。最後にします。","respondent":"吉田保育施設調整担当課長","answer":"園庭問題につきましては、ぷりすくーるの屋上を園庭にできないかと今まで検討してまいりました。その関係の階段を用意しようと検討はしたのですけれども、工事を調整していったところ、現実的にはできなかったというところになります。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"どういうふうに考えているのかというのが１つと、一般的には公務員の保育士も、私立で働いてきた部分は２分の１加算というのがあります。さっきの質疑を聞いていて思ったのですけれども、その辺についてどうなのかを伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"その点で、改善すべきところは改善していくことで、対応できればと考えております。認可保育園に勤務したという経歴になりますし、ぷりすくーるの幼児教育部門であれば、幼児教育部門という対応になると考えております。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"できるだけ私は長く、４.４年にとどまらずに、１０年、１５年とその地に足をしっかりつけて、保育という仕事に専念していただきたいと思うわけです。どうしたらいいかというところでの考え方を、区としてはどういうふうに持つのかという、そこのところをまず聞きたいと思っているのです。","respondent":"吉田保育施設調整担当課長","answer":"区としましては、例えば長く勤めていただくというのは、ある意味、質の向上につながるのかなと考えておりますので、キャリアアップ補助金とか、各種補助金とか、その辺を含めまして、できる支援を行っていくところです。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"それで、ここに勤めていても、なかなか認可保育園に勤めていたというキャリアにならないと先ほど説明されていました。同じように該当させるべきではないかと思って、そういう意味で先ほど質問したのですけれども、その辺についてはどうなのでしょうかということです。","respondent":"吉田保育施設調整担当課長","answer":"認可外にいるときも２分の１をキャリアにするという意味なのでしょうか。一般的には、履歴書とかに書かれたところを受けとめて、どう評価するかというのは、採用する側の判断と考えております。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"その人にとって不利益になるわけですから、今はとりわけ人材確保という点からも、必要なのではないかと思うのです。その辺についてもう一度答弁していただいて、もしなければ、検討は絶対していただきたいと主張したいと思います。","respondent":"福島子ども未来部長","answer":"ただ、どういった形での認定こども園になるかは、これから検討しますけれども、いずれにしましても、国から認められるような認定こども園化を目指す。これについても、区として全面的に支援していきたいと考えているところです。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"社会福祉法人化の中で解消できるという話なのですけれども、それはそれとして受けとめたいと思っています。一定考慮していくべきではないかと思いますので、繰り返しますけれども、ぜひ検討していただきたいということを強くお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、利用者、保護者の方の評価を正しくつかむのと、どこでも見られるように公表していただきたい、ガラス張りとしていただきたいというのが１点です。２つの法律の中で、ぜひその辺の支援を十分してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"意見","question":"賛成です。ぜひスピーディーに進めて、品川区の施設のさらなる発展のために、ぜひ区として支援をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-02","title":"第９８号議案、訴訟上の和解","agenda":"第９８号議案、訴訟上の和解","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"訴訟になったというお話も伺っていましたし、今回議案として、こういうことが提示されてきました。当然６年前のことで中学生ですから、今回出てきた議決にどういう態度というのがあるのだけれども、わかれば教えてほしい。","respondent":"有馬庶務課長","answer":"この間３５回、最終的に証人尋問が終わったのが平成３０年１月１０日ということで、和解のタイミングもそこになったということです。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問・要望","question":"ある中で、この議案に示されているような、今後また同じことが繰り返されないようにというところでやっていかなければならないと思います。これからいじめに対する取り組み、教育委員会の考え方を、一言ここで聞かせてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"オール品川で、地域の方やさまざまな団体の方とも情報を常に共有しながら、本区のいじめ対策を今後も途絶えることなく継続していきたいと考えております。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"議会も相当具体的な、わかった時点でわかった内容を教えてほしいと、私もたしか決算特別委員会だったのですけれども、やったことを記憶しています。まずそこは伺っておかなければいけない問題だと思いますので、その点について、区の見解を伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"全てを根絶するにはなかなか難しい道のりではありますが、早期のうちに対応するということは、これまでも継続してきたことです。したがいまして、いじめを見逃したことにより命が失われてしまうという事案は、その後は起きていないと教育委員会事務局としては認識しています。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"区としては、そこをどういうふうに思っているのか、見解を伺いたいと思います。大事なところだからそこを伺いたいと思います。","respondent":"塚本委員長、大関教育総合支援センター長、有馬庶務課長","answer":"かなり裁判の中身の非常に難しいところにも触れているので、答えられる範囲でということでお願いします。本区でも、これは教育委員会だけでなく、品川区としても取り組んでいるところです。今後とも学校といたしましても… 議案書の前文の（１）に書かれてあることが、最終的に原告の方がこの和解に合意したときの内容ですので、こういう理由だとは受けとめています。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"それを全ていじめではないと思っていいということですか。最終的に確認をしたいと思います。","respondent":"大関教育総合支援センター長、有馬庶務課長、熊谷指導課長","answer":"いじめを起因とする事案はないと認識しております。 ここの調査が必ずしも十分でなかったという点についてなのですけれども、最終的にこれは和解となっております。最終的には… 実際にこういった悲しい事案が起こる前に、しっかり調査をしたかどうか、そこのところが不十分であったです。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことをしてはいけないと指摘をして、改善を求めるという質問をしました。しかし、そういうことが……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"簡潔です。人の命がかかっている問題だから、議案ですから言っているのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、ぜひそういうことについての見解を伺いたいと。それと、この和解については両当事者の間の合意ですから、これについてどうこう言うつもりは全くありません。","respondent":"大関教育総合支援センター長","answer":"学校が組織的に対応して、さらに教育委員会がそこを支援できるように、学校支援チーム。年３回、小・中・義務教育学校が連携して情報共有をして、対策を充実させてまいりました。","id":"exchange-023"},{"speaker":"つる委員","kind":"質問・要望","question":"確認があったとおり、今、区としてさまざまな取り組みが展開されていると。さらにこれからも、そうしたことのない区にしていこうということでの取り組み強化、そうしたことのお考えを改めてお聞かせほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"さまざまな取り組みが決して風化してしまう、状況を見ながら、今後ともできる取り組みはしっかりとやっていきたいと思います。今後ともこれを継続して、二度とこのような悲しい事案を生まないように、努力を継続してまいります。","id":"exchange-024"},{"speaker":"つる委員","kind":"質問","question":"すごく大事だと思うということを申し上げて、たしか既に現教育長が地域に出て、さまざま皆様の声を聞いていくことがあったということも伺いました。今ここにこうやっていられるわけですから、そうした希望となる現場の教育の支援になることを、これからも一生懸命お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここに結実するのですが、ここは簡単には言えない中身というのでしょうか、私は報告書をもう一度読み返してみました。だから、教育委員会だけの問題ではありませんが、そういうのを発信する教育委員会に変わっていただきたいと思うのですが、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"これは今も継続しておりますし、今後も続けていきたいと考えております。さまざまなヒントを得る場というのは、これまでもございましたし、今後もそういった場を活用しながら取り組んでいきたいと考えています。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"とても長い時間を学校で過ごしているという子どもたちの状況を、真摯に受けとめて、大きな視野のもとで捉えて改善をしてほしい。そういった立場に立っての発信をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"いじめ専用電話はいじめのことだけでなく、さまざまな子ども自身からの発信をまとめております。中には直接教育総合支援センターに来て、いろいろな形で子どもの意見というものは拾っていき、丁寧に対応していきたいと考えております。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"表面化していないところにも、ぜひ目を向けていただきたいという意味で、私は教育総合支援センターの部分をもっと充実させていただきたい。独立したところで扱っているというのを聞いたので、ぜひ教育総合支援センターの充実をお願いして、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"自殺に関してもしっかり教育委員会として、若年層の自殺がないように、ぜひさらなる取り組みをしてほしいと求めました。しっかりサポートを続けていってほしいと求めましたが、その点について何かあれば、説明を求めました。","respondent":"大関教育総合支援センター長","answer":"そういったところで専門の心理士が対応していますので、年齢に応じて的確な対応をできる部署が区内にはたくさんありますので、寄り添った対応を心がけてまいります。","id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"質問","question":"この（１）から（６）、（７）をどうするかはあれなのですけれども、そういうのはどのような扱いをする感覚なのかということ。（７）の品川区が賠償をするという本件解決金ということなのですが、区立学校ということで、それを含めてということなのか尋ねました。","respondent":"有馬庶務課長","answer":"教諭の部分については、教諭それぞれ考えていただくべきものかなと捉えてあります。今回の解決金については、品川区に関する内容ということになっているものです。","id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうあります。そういったことも含め、今後の対応は未来につながるような形で、しっかりやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"大人にしっかり援助を求める態度というのは非常に大切だということを、今現在、その取り組みに関してはどうなのかということを１点お伺いしたい。年１回やられていますけれども、もう少ししっかりした大々的な取り組みを全庁的にするべきだと思うのですが、これに関してはいかがなのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"子どもたちに対応する部分につきましては、友達の悩みを聞いたときにはどうしようかという部分を、子どもに実際に考えてもらう。これは保健予防課とも連携を進めておりまして、どういうふうに子どもたちのＳＯＳに対して対応するのか、そんな部分を毎回。","id":"exchange-032"},{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"もう少し具体的な自殺予防の取り組みというのは、何か試みだとか、今検討されていることとかあるのでしょうか。いじめというのは一部だけですから、１つの希望も交えて、質問させていただきたい。","respondent":"大関教育総合支援センター長","answer":"あるいは必要な内容について講義いただくなどの機会、さまざまな方法はあろうかと思いますので、関係機関とも連携して充実してまいりたいと思います。","id":"exchange-033"}]},{"id":"topic-03","title":"平成３０年請願第２３号、学校給食の牛乳にプラスチックストローを使用しないことを求める請願","agenda":"平成３０年請願第２３号、学校給食の牛乳にプラスチックストローを使用しないことを求める請願","exchanges":[{"speaker":"南委員","kind":"確認","question":"先ほどの話ではなかなか難しいというのが先に立ってしまう答弁かなとは思うのですけれども、改めてその辺を確認したいと思います。とりあえず今の２点、。","respondent":"篠田学務課長","answer":"すぐに何か変更していこうという形で声を伝えていくということは考えていないのですけれども、その内容については真摯に伝えてまいりたいです。","id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"瓶のリユースを考えていくということも１つの方法だと思いますし、私も子どものときですから、それで飲んでいたと。そういう問題についてどういうふうに考えているのか、一つひとつの問題について、その３つの点についてご答弁をお願いします。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"１つはリユースに関しまして、瓶の場合には８回から１０回程度、実はそんなには使えるものではないとお聞きしています。教育委員会としても今後はどういった形で対応ができるのか、必要なのかといったことに関しては… きちんと処分をされないと環境問題になるのだなということを認識したり、あるいは、さまざまな機会で考えるきっかけになろうかと思います。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、品川区から都・学校給食会・乳業者の３者へ声を挙げて頂きたく要望させて頂きますという請願の内容なので、発信をしていくと。その発信が日本の国の政府に届いて、そこの先鞭をつけられるような今回の結論にしていきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"渡部委員","kind":"質問","question":"３者に伝えることは伝えられるというところなのだけれども、実際問題として、さまざまな取り組みがあるではないですか。難しいのか、簡単にできるような気もしないではないのだけれども、実際どうなのか尋ねました。","respondent":"篠田学務課長","answer":"そうしますと、なかなかきれいに洗い切れるのかどうかとか、そういったところもきちんと考えていかなければいけないだろうと思っています。","id":"exchange-037"},{"speaker":"渡部委員","kind":"意見","question":"いろいろ考えていかなければならないのですけれども、例えば東京都２３区の清掃工場だと、きっとこれは焼いてしまえば済む話なのだと思うのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"つる委員","kind":"確認","question":"幾つか確認で、先ほどご説明の中では、紙ストローが１０倍ぐらいになる様子である。供給されているもので結構なのですが、プラスチックストローの単価というのはお幾らなのか、わかれば説明を求めました。","respondent":"篠田学務課長","answer":"請願を受けまして、製品の製造コストにかかる部分なものですから、正式なところはメーカーからは教えていただくことができなかったです。市販でいくと１本当たり０.５円ぐらいで販売されていますので、当然、それよりはるかに安い金額ではあるのだろうなと考えているところです。","id":"exchange-039"},{"speaker":"つる委員","kind":"質問","question":"例えばナショナルチェーンのコーヒーショップというところでは紙製ストローに変えるとか、いろいろそういう民間的な動きはあります。品川区で提供されている牛乳の形というのが、三角形とか四角形とかありまして、どちらなのか分からないのでそこを説明を求めました。","respondent":"篠田学務課長","answer":"例えば５００ミリリットルとか１リットルの牛乳パックと同じような、その上の斜面のところをめくると穴があって、そこにストローを差し込むという形になっています。","id":"exchange-040"},{"speaker":"つる委員","kind":"質問","question":"衛生的にどうなのかとあるわけですが、飲み切りサイズというか、２００ミリリットルぐらいになるのでしょうか。だから、まずマナーとか、また自分で飲み干すのだから、衛生的にどうだという、この辺の考え方を説明を求めました。","respondent":"篠田学務課長","answer":"基本的には、実際にそういった形で実施がされている学校もあるですから、直飲み自体が不可能ということにはならないと思います。品川で実施した場合に、２年生あたりになると、導入ができるのかどうかというのは検討していく価値はあるのかなと考えているところです。","id":"exchange-041"},{"speaker":"つる委員","kind":"質問・要望","question":"もっともっと動いていただきたいというところがあるのですが、実は来年の４月の製品発表に向けて、進めているということを確認できました。各課、区長部局とも連携をとって進めていっていただきたいと、最後は要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"石田（し）委員","kind":"質問","question":"東京都と学校給食会と乳業者がいて、品川区だけでプラスチックストローを使わないということが、現実的にできるのかどうかというのが、まず１点。できないのであれば、どうやったらそれが可能になるのか、その方法というのがあるのかどうか、まず説明を求めました。","respondent":"篠田学務課長","answer":"現状は東京都と学校給食会と乳業者の３者協定という形で結んでいまして、安定供給のためにやっている。当然それは話ができませんから、先ほど来お話が出ていたような形で、利用していく必要があるのか考えていく必要があるところです。","id":"exchange-043"},{"speaker":"石田（し）委員","kind":"質問","question":"要は、飲み口がついているパックというのが今はあるわけではないですか。契約上可能なのではないかと思うのですけれども、そういうやり方もできなくはないのかどうか、説明を求めました。","respondent":"篠田学務課長","answer":"容器の形態自体が変わりますので、１つはそういった形態のものが、学校給食用として業者が対応できるのかどうかという検討が必要になると思います。実際に話し合ってみないとわかりませんけれども、そういうことが可能なのかどうかも含めて、検討が必要なのかなと思います。","id":"exchange-044"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私はこれはぜひ進めていっていただきたいと思うし、２３区でみんなでやろうよというのは、私はこれは真剣に考える余地があるのではないかと。こういう発信をしてくれているというのは、私は本当にすごいことだと思うので、ぜひこれは前向きに教育委員会としても捉えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"質問","question":"都内の教育委員会の指導課には課長会があるとお聞きしているのですが、今みたいな形で、課長会の中でこういった話題は出たりしているのでしょうか。そこを伺います。","respondent":"篠田学務課長","answer":"学務課長会の中で、環境面に配慮したプラスチックストローの見直しといったテーマについては、今のところ声は出てきてございません。まだ全体として、こういったものが特別区の中で、動きとしてあるということは把握していないです。","id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"意見","question":"ぜひ、先ほどのお話にもありましたけれども、品川区が先頭に立ってというところも期待したいと思います。それこそ直飲みに合うようなパックを考えつく方も、必ずいると思いますので、そっちの方向もいいかなと思ったりしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問・要望","question":"教育なので、現状のごみになったものがどうなるかというのも、しっかり教えてほしいと思っています。質問は、紙のパックとストローと包んである容器が、飲み終わった後、どういうふうに処理されているのかを説明を求めました。","respondent":"篠田学務課長","answer":"こちらは先ほど申し上げたとおり、容器リサイクル法の対象外になっておりますので、リサイクルの体制が確立してございません。こちらに関しては、まとめて廃棄をして、品川区内では燃えるごみとして扱われますので、焼却処分がされているというものです。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"紙パックは良質で、多分、紙にリサイクルをされていると思うのですが、ストローと包装は容器リサイクル法にならないのですか。どうしたらこの地球環境を守れるのかという立場で、ぜひ教育に役立てていただきたいと思うのですが、その点はいかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"子どもたちは見ておりますので、極力ごみは出さないようにしようと品川の子どもたちは自分で考えだしていると認識しています。今後ともさまざまな機会を通じて、環境について、まず３Ｒという部分はしっかりと学ばせていきたいと考えています。","id":"exchange-049"}]},{"id":"topic-04","title":"平成３０年陳情第２２号、すまいるスクールの利用者ニーズ把握のためのアンケート調査の実施を求める陳情","agenda":"平成３０年陳情第２２号、すまいるスクールの利用者ニーズ把握のためのアンケート調査の実施を求める陳情","exchanges":[{"speaker":"南委員","kind":"質問","question":"アンケート調査は３,０００世帯ということで説明がありましたけれども、ここの陳情に書かれてある、そのことを１点伺いたいと思います。区としてどのように把握しようとしているのか、区はどのように満足度について捉えようとしているのか、それを伺いたいと思います。","respondent":"高山子ども育成課長","answer":"本年度実施いたします３,０００世帯規模の調査が、保護者と利用する児童、双方の意見を踏まえられるような形で実施するものです。","id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"あえて申し上げますが、ここの前文に書いてある、小学４年生以上になってしまうと１８時までしか利用できなくなると。それ以降も、具体的な１つの例を挙げて質問ですが、そういうふうに受けとめる調査でいいということで理解していいのか尋ねました。","respondent":"高山子ども育成課長","answer":"あるいは利用料金なども含めて、一通りのものを聞かせていただいて、そうした意見の趨勢を捉えてまいりたいと考えているところです。そうした意味では、調査の結果を踏まえて今後の制度の見直しを図るという点については、スタンスとして変わるものではございません。","id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひやっていただきたいということで、具体的に具現化するのは来年度からと受けとめていいのかどうか、その２点をお願いします。","respondent":"高山子ども育成課長","answer":"一定程度予算立てをしないと実現できないようなものにつきましては、平成３１年度を検討期間とする見直しに反映させてまいりたいと考えております。","id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"利用料金についても調査をとるような説明でした。上げるということではない方向で検討もしていただきたいと思っているのですが、その辺についての感触というのは、もしあれば伺いたいと思います。","respondent":"高山子ども育成課長","answer":"減免の制度もこの月額の利用を導入する際に検討して、そうした減免の制度も含めまして、この機会に確認しておきたいというものです。したがいまして、少なくとも保護者の方の受けとめ方については、この機会に把握してまいりたいと考えるものです。","id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"私はできれば上げない方向で検討していただきたい。負担感のところと、できるだけ負担を和らげるという角度で検討をするべきだと考えていますので、意見として申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"具体的に何点かお伺いしたいと思いますが、小学４年生以上になると、親が就労している場合でも１８時までしか利用できなくなる。この辺はいつ、どのような中身で見直しをしていくのか、この３点をまずお伺いします。","respondent":"高山子ども育成課長","answer":"したがいまして、これは区の実施している家庭あんしんセンターにおける費用です。３点目の不断の見直しにつきましては、まさにすまいるスクール事業を継続的にいいものにしていく、折々で見直しをしていくといったものです。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ具体的に対応していただきたいと思うのですが、こういった意見は幾つか出されているのかどうか、そこを１点お伺いします。利用していない人の意見も聞くことが、すまいるスクールをよりよいものにしていくことになると思うのですが、その点はいかがか尋ねました。","respondent":"高山子ども育成課長","answer":"それに見合った職員を加配という形で対応することが、すまいるスクールにおける一般的な対応ということになってまいります。我々としても最大限努力はしてまいりますが、大きな方向性として、利用者ニーズを把握するには最適だと考えているところです。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"よりスムーズに一日が過ごせるという立場においては、ぜひ差別なくというか、その子に合った利用方法を考えてほしいと思います。いろいろな手だてがあるので、それを選んでほしいというのではなく、この点はいかがか尋ねました。","respondent":"高山子ども育成課長","answer":"支援員となるに当たっては、そこの部分の意に十分沿うというのは、なかなか難しい部分があります。受け入れる体制の底上げというのも一方では必要だと考えておりますので、そうした部分を並行して進めてまいりたいと考えております。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今は発達障害とか、横の連携を十分にとって、すまいるスクールをどの子も居心地のいい場所にしてほしいと求めました。ここに、子ども・子育て会議において多くの委員から意見を求めたうえで検討するようにしてくださいとありますが、最後にお考えを説明を求めました。","respondent":"高山子ども育成課長","answer":"もともと子ども・子育て支援新制度の発足とともに立ち上がった会議体でございまして、保育でありますとか、あるいは子育て短期支援事業。そうした議題として、もとより想定しているものですので、今後議題として取り上げていくことは十分考えられると考えております。","id":"exchange-058"},{"speaker":"渡部委員","kind":"意見","question":"それをどういうふうにやっていくかというのは非常に難しいけれども、家庭の中でもいろいろ知恵を絞っているのかなとは思います。これだけ役所のほうもアンケートをとって、これからまたやっていくということですので、話が戻りますけれども、不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"つる委員","kind":"質問・要望","question":"社会全体で言われている働き方改革１つとっても、果たして今の働く世代の人たちがどうあるべきなのかということも、一方で思っているところです。アンケートに寄せられる声を中心に、見直すべきところは見直していただくということを、しっかりとやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本来放課後ですから、どう楽しく遊んで、幅広く意見が聞かれるようなアンケートにしていただきたいと思っています。どの子も大切に、成長と発達を支えていくすまいるスクールであってほしいと思う観点から、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"石田（し）委員","kind":"質問","question":"結論を出すで、不採択です。それ以上のものが必要というのはどうなのかなと思って、やっていかれるかと思いますので、この陳情に関しては不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"質問を見ることができないのですが、もう決まっているのでしょうけれども、このアンケートを有効に活用してほしいと求めました。３,０００世帯ということで、１万のうちの３,０００ということですから、よりよい仕組みがつくられていくのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/971992?Template=document&Id=4958#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":55543,"voices":173}},{"id":"h30-20181210-5","meetingId":"h30-cm12","date":"2018年12月10日","dateIso":"2018-12-10","committee":"総務委員会","time":"午前１０時００分～午後 ２時３６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を87件整理しています。","topics":[{"id":"topic-01","title":"「議案審査」を行います。 初めに、(1)第８４号議案、品川区議会議員および品川区長の選挙における選挙運動の公費負担に関する条例の一部を改正する条例","agenda":"「議案審査」を行います。 初めに、(1)第８４号議案、品川区議会議員および品川区長の選挙における選挙運動の公費負担に関する条例の一部を改正する条例","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"公費負担の額は、区長選挙が７円５１銭で、１万６,０００枚、区議会議員選挙が新たに創設されて７円５１銭で４,０００枚とのことですが、この公費負担額の算定根拠を説明を求めました。","respondent":"秋山選挙管理委員会事務局長","answer":"７円５１銭についてですけれども、これは公職選挙法に規定をされておりますので、それを条例でも横引いています。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"どうすることもできないと思うのですが、通常であれば、枚数が多ければ単価は下がるということを頭の中に入れておいていただきたい。例えば７円５１銭というのは、この７円５１銭という単価が安いのか、今後何かやるときにお考えほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"ビラを公費負担とした理由を伺いたいと思います。できる規定なのかと思うのですけれども、選挙管理委員会としてどういう判断をしたのか、その理由についても伺いたいと思います。","respondent":"秋山選挙管理委員会事務局長","answer":"区条例でも公費負担を行うのがよかろうということで、今回、改正を行うものです。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的に説明していただきたいのですけれども、選挙管理委員会に届け出たというところですけれども、これは立候補のときに届けるのでしょうか。改正する条例の内容をご説明ほしいと求めました。","respondent":"秋山選挙管理委員会事務局長","answer":"サイズはＡ４に決まっておりまして、内容に関しては特に基準はありませんが、印刷者の氏名を記載しなければならないということがあります。これは、告示の日の立候補者届けのときに持ってきていただいて、引き換えに証紙をお渡しするという形になります。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"今の続きみたいなのですけれども、政策を知らしめるための手法がありますね。ビラの使い方について品川区として何か規制があるのかないのか、その点について説明を求めました。","respondent":"秋山選挙管理委員会事務局長","answer":"この条例に関しましては、公費負担の条例になりますので、区として条例で使い道を定めているものではないのですが、公職選挙法上、ビラの頒布方法は決まっておりますので、使い方はそちらに定められております。","id":"exchange-005"},{"speaker":"伊藤委員長","kind":"質問・要望","question":"１点だけ私から要望ですけれども、そういうときにはぜひ、具体的でわかりやすい説明をしていただきますようにお願いをしておきます。採決に入ります前に、第８４号議案、各会派の態度を確認いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"順番を変更しまして、(6)の第８９号議案、第二戸越幹線整備工事（上流部シールド）請負契約","agenda":"順番を変更しまして、(6)の第８９号議案、第二戸越幹線整備工事（上流部シールド）請負契約","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"区立宮前坂広場に深さ３０ｍの立坑を掘ると説明がありましたが、この辺は道が狭いのだけれども、ここから残土を搬出するのではなくて、西品川公園まで持ってきて出すのか、それとも、この区立宮前坂広場公園で残土を搬出するのかということを確認します。","respondent":"持田河川下水道課長","answer":"残土に関する搬出のご質問ですが、区立宮前坂広場での工事につきましては、道は狭いのですが、この場所から残土を搬出するという形で考えてあります。","id":"exchange-007"},{"speaker":"いながわ委員","kind":"質問・要望","question":"どれぐらいの残土が出るかわからないですけれども、結構なダンプの台数が出入りするのでしょうか。それと地域への説明とかはお済みになっているのか、それとも、これからなのか、説明を求めました。","respondent":"持田河川下水道課長","answer":"１日当たりの施工量はなかなか多くはできないということから、ダンプでの搬出は１日あたり一、二台というふうに考えてあります。しっかり事業者とともに地元で工事の説明という形で、ダンプでの搬出なども含めて説明をしっかりと行っていきたいと考えています。","id":"exchange-008"},{"speaker":"いながわ委員","kind":"質問・要望","question":"とにかく狭い道路なので地響きとかいろいろあろうかと思いますので、可決した暁にはしっかりやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"公園を利用されている方や、その周辺の方への説明は丁寧に行ってほしいと求めました。今後の見通しだけご説明いただけますか尋ねました。","respondent":"持田河川下水道課長","answer":"第二戸越幹線の事業につきましては、現段階では、平成３６年度の完成という形で、少し時間もかかりますが、事業を進めているところです。","id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"疑問に思うのは、会社の大きさが違うので、それぞれの会社の持つ経費も違う。こういうふうになったのかというような疑問を私は抱くのですが、この辺について、経理課としてはどのように考えられていますかとの意見を述べました。","respondent":"立木経理課長","answer":"予定価格は東京都等の積算価格等から適正に算出しているものなのですけれども、それぞれの共同企業体で、積算した金額と予定価格を見まして。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"平成３１年からの債務負担行為による工事だと、平成３１年に始まっている工程はないわけですが、どこに当たるのか尋ねました。","respondent":"持田河川下水道課長","answer":"このバーで言うと下から２つでございまして、平成３０年度中に着手ということで、まず暫定貯留工という工事を行う。今の予定では平成３２年度の頭からシールド工に入っていくということで、全体の事業としましては、平成３０年度から平成３３年度までとなっています。","id":"exchange-012"},{"speaker":"吉田委員","kind":"確認","question":"では、平成３０年度だけれども、もう平成３１年に実際は入っていて、この真ん中の棒の当初からの分というふうに理解してよろしいですか。それだけ確認させてください。","respondent":"立木経理課長","answer":"契約自体は、こちらの議決をいただいた後、契約をするということで、工事自体が終了するのが平成３３年ということになりますので、その分までの債務負担行為を今年度中に定めするという形のものですので、契約ができましたら平成３０年度中に始まるという形のものです。","id":"exchange-013"}]},{"id":"topic-03","title":"第９０号議案、第二戸越幹線整備工事（下水道本管立坑整備）請負契約の変更","agenda":"第９０号議案、第二戸越幹線整備工事（下水道本管立坑整備）請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどの説明ですと、変更理由はシールドマシーンの到達部を補強する必要があるということですけれども、資料に記載してある変更内容は、どういうものなのか、どういう状況があって補強する必要が生じたのか、もう少し具体的にご説明ほしいと求めました。","respondent":"持田河川下水道課長","answer":"今年の７月に、それにあわせてこの補強タイプのセグメントに変えまして、下流部にシールドマシンが到達しても構造的に大丈夫なような形に変更した。そういった理由により変更を行う案件です。","id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問","question":"この深さ約４０ｍというのは、路面から４０ｍ掘るということですか。そういうことでいいのか尋ねました。","respondent":"持田河川下水道課長","answer":"そのとおりでございまして、公園のところを少し掘削をして１ｍほど下げた基盤面から４０ｍ、これから掘っていくです。","id":"exchange-015"}]},{"id":"topic-04","title":"平成３０年請願第２０号、国に対し「消費税増税中止を求める意見書」の提出を求める請願","agenda":"平成３０年請願第２０号、国に対し「消費税増税中止を求める意見書」の提出を求める請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"消費税１０％中止を求める意見書の提出を求める請願ですけれども、一致点を見出して、その一致点をもって意見書提出をしたいと考えています。１０％にすれば、来年１０月の消費税１０％は中止してほしいと、各委員の率直なご意見をお伺いできたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"意見","question":"２０１９年、来年の１０月に、大変厳しい状況がいまだに続いております。国も軽減税率制度、少しややこしい部分もありますけれども、そういった制度も導入していただきながら、１０％は当然必要ではないのかと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですから、品川・生活者ネットワークは、消費税という制度自体には必ずしも反対ではない。中塚委員の発言でありましたけれども、消費税そのものへの反対意見ではなくて、今回の１０％引き上げへの中止を求める意見書というのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"いながわ委員","kind":"質問・要望","question":"医療費が上昇しているから何とかしなければいけないと一方で言われているわけですから、８％が１０％になるというのは、私はやむを得ない。それから、委員長、今回は理事者に何も聞いてはいけないのか尋ねました。","respondent":"伊藤委員長","answer":"そんなことはありません。例えば、現状の方向性であるとか、制度の考え方などについては、当然、聞いてくださって結構です。","id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問","question":"プレミアム商品券を発行するのかどうなのか、いろいろ飲食店に対してはしっかりとした助成金という言い方なのか、何かしらの対策をお考えでいるか。これは、むしろ平成３０年度予算ですでに準備をしていかなければいけない段階なので、その辺について行政側としてはどうお考えなのか尋ねました。","respondent":"品川財政課長","answer":"過去を見れば、現時点で具体的にどのような対策というのは、まだまだとることは難しいかというふうには考えております。やはりその辺の状況もしっかりと踏まえて、どのような対策を打っていくかというところは考えていくという準備は、現時点でもしています。","id":"exchange-020"},{"speaker":"いながわ委員","kind":"質問・要望","question":"国がどういう措置を講ずるかわからないのですが、品川区としては、そういうところを地元の行政としてしっかり見ていただきたいのです。全ての区民の人たちが、そういったステージをつくるというのが大前提の中での１０％への改定というのは、いたし方ないところなのかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、それだけは避けるべきではないかといつも思っております。タイミングが悪い消費税増税中止を求める意見というのはわかりますけれども、国の将来、消費税増税はやむを得ないというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"時期がどうかというところを問題点として挙げておりますが、消費税を１０％に上げる議論の中で、当初より軽減税率の導入を推進してまいりました。今現在、されているのかどうかというところも確認させてほしいと求めましたが、いかがか尋ねました。","respondent":"伊東税務課長","answer":"区といいますか、これは税務署のほうで、さまざまな機会を捉えて、各種団体、税関係の団体とかに軽減税率の話ですとか、先ほどのレジの改修費用等の補助金の関係の話ですとかを行い進めているというふうに聞いております。","id":"exchange-023"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"現状、まだ８割が準備に取りかかっていないという現状もあるということで、できるところに対する周知にしっかりと取り組んでほしいと求めました。いくべきところに給付がいかないという、この消費税の１０％というのは、お金が回っていくような形を捉えているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"ただ、皆さんのご意見を伺う中で、この厳しい経済の中で１０％にしてよいのかというところでは、さまざまな一致点はあるのではないかと思うのです。この時期に１０％に上げることは中止してほしいと、この１点で意見書が上げられたらと改めて述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問・要望","question":"国民に理解を求めるというのならわかるのですけれども、片やじゃぶじゃぶお金を使っておいて、私は大半の国民には理解されないと思います。そういう方向で進めていったほうがいいのではないかと、今回も絶対に国民には納得されない増税だというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、社会保障の財源を確保するため消費税だけにそれを求めるという今回の消費税増税の議論の仕方が、ちょっとどうなのかというふうに思います。そういう意味でも、今回のこの８％から１０％への増税というのは、中止を求める意見書というのは妥当性があるのではないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"中塚委員","kind":"意見","question":"来年１０月に１０％に引き上げるべきではないというのは、多くの皆さんの共通する考えだと思いますので、その点をもって意見書を出したいと思います。結論としては、採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１０％になって全ての物の値段が上がれば、政府も住宅などに関しては、いろいろな減税策を考えていると思います。ただ、そこはしっかりとやって区民がマイナスにならないよう、不利益を被ることがないようにフォローをしていただきたいということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"本当に大半の国民にとってかなりの負担になると思いますが、そこは理解していただきたいというふうに思います。今回の請願に関しては、不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"今回の消費税増税中止を求める意見書ということであれば、今日結論を出すということで、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"松澤委員","kind":"質問・要望","question":"本日結論を出してほしいと求めました。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"いながわ委員","kind":"質問・要望","question":"もしそこに重大な瑕疵があった場合には、指定管理者を変えるという仕組みといいますか、いわゆる強権発動と言うのでしょうか。私の会派、民主党時代からずっと要望していたのですが、労務監査というのもたしか今、試行的やられていると思います。","respondent":"柏原企画調整課長","answer":"１点目のところは、その指定に関して、指定管理者としてはこれはできませんという指導的なことはやります。ほかの外部チェックについても今検討しているところですが、そういったものを入れながら、公平性を担保していきたいと思っているところです。","id":"exchange-033"},{"speaker":"いながわ委員","kind":"質問・要望","question":"創出というところだと思うのですけれども、それは仕組みの中でどうにでもなる部分だと考えていますので、よろしくお願いしたいと思います。それが機能することで、実効性が担保されるということが大切なので、しっかりやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"指定管理者制度について、現状の何を課題と捉え、どこが課題と考えているのかをご説明ほしいと求めました。いわゆるガイドラインに沿うという説明だったのでしょうか、公開を行うということでよろしいのか、そこについてもご説明ほしいと求めました。","respondent":"柏原企画調整課長","answer":"その１つに、それを今、検討しているといった現状があるというものです。それは、全体の見直しの中でそれを除いた形で公表といいますか、皆様に見ていただける形にするかというのもあわせて検討しているといったものです。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"議会に議決を求める際の資料や、検討を進めてほしいと求めましたけれども、お伺いしたいと思います。伺いたいのは、こうした現状について区は課題と捉えているのか、そして、どう対応していくのか、お考えを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"今、検討していますので、どういった形がいいかは引き続き検討させていただければと考えています。ただ、結果的に一社しか出てきていないというのは、指定管理者制度の運営を全体的にどう見るかというのは検討していきたいとは思っております。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"駐輪場などがあたるのでしょうか、福祉施設の継続性とは異なり、いわゆる指定管理者制度の目的である民間活力を生かすということは必要だと思います。今後どのように行っていくのか、重なる部分もありますけれども、改めていかがか尋ねました。","respondent":"柏原企画調整課長","answer":"例えば、たとえ一社でもそれは指定できないことがありますというような考え方を持ちながら、我々も各所管も指定を行っているというところがあります。今後とも、区の施設だということを理解しながら、指定管理制度がきちんと運用されるように取組んでいきたいと思います。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"あれもできます、どの辺の事業が求められているのか、やっぱり一定金額で判断するということも必要なのではないかと思います。品川区がどのレベルを求めていてというのがもう少し明瞭でないと、その辺をもう少しイメージできるようにお話しいただけるとありがたいと思います。","respondent":"柏原企画調整課長","answer":"その募集の際に説明会をやったり、それは区の考え方に基づいてつくっておりますので、それが出ているというふうに理解しています。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"競争原理とか、その中で品川区がどういうふうに選定していくかということがすごくまた品川区としての力量も求められるのではないかと思います。先ほどの質問と少し重なるかもしれませんけれども、今後オープンにしていくということについて、もし何か見解をいただければ。","respondent":"柏原企画調整課長","answer":"区としての指定管理のあり方、考え方というのは、もう少し整理をする必要があるだろうというふうには思ってあります。その内容や考え方などを入れながら、区の指定管理者制度をどういった形でお示しできるかというのは十分検討しながらやっていきたいと思います。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"後の評価ということと、まず最初の意欲ある事業者が手を挙げやすいような制度の運用の仕方というのは、ぜひ検討していってほしいと求めました。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"意見","question":"本日結論を出すということでお願いします。今回のこの陳情は、区として、今現在、やるべきことをやっておられると思いますので、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"新妻副委員長","kind":"意見","question":"本日結論を出すでお願いいたします。指針等についてもしっかりと検討されているというお話がございましたので、そのことも含めて、この陳情は不採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問","question":"一方で、新しい法人の応募により、新しい風を入れて活性化させるという点もあわせて大事だと思います。その手法はさまざまありますが、陳情にある制度改善や研修などの必要性について、その趣旨は理解できますので、趣旨採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"いながわ委員","kind":"質問・要望","question":"先ほど質問したように、今度新たにお考えの社会保険労務士を入れた労務管理は、行ってほしいと求めました。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"須貝委員","kind":"質問・要望","question":"ガイドラインの作成と人材研修の実施を求めるということですが、区民、品川区の指定管理者制度をよりよいものにしていってほしいと求めました。今回のこの陳情に関しては、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"吉田委員","kind":"質問・要望","question":"指針でも結構ですけれども、それの作成と、それを活用できる区の職員の研修を求めるというのは当然のことではないかというふうに思います。指定管理者がどういうふうな事業者かは、それを区議会から区に求めるというこの陳情については採択が妥当ではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"吉田委員","kind":"質問","question":"確かにこの文章のとおりでなくても、例えば、指針でもいいわけですし、とりあえずはガイドラインなり指針の作成ということで、人材研修というのは、それに伴うものですから、この文章のとおりではないという意味では、趣旨採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"}]},{"id":"topic-05","title":"第８５号議案、（仮称）品川区立障害児者総合支援施設新築工事請負契約の変更","agenda":"第８５号議案、（仮称）品川区立障害児者総合支援施設新築工事請負契約の変更","exchanges":[{"speaker":"いながわ委員","kind":"意見","question":"代替施設といいますか、そういうものをしっかり準備されているのかどうなのか。多分、そのほかに関しては、その工事に伴って工期が延伸することによって発生する施工者の４カ月分の人件費相当という考え方でいいのかどうなのかとの意見を述べました。","respondent":"小林施設整備課長、飛田障害者施策推進担当課長","answer":"１つ目につきましては、所管課の障害者福祉課のほうで利用者向けに、１１月１５日に、２回に分けて説明会を開いたということです。それと２つ目につきましては、そのとおりでございまして… 代替施設の質問がありましたので、私からお答えします。説明会では、現在、こみゅにてぃぷらざ八潮３階の講習室で話を進めているところです。","id":"exchange-048"},{"speaker":"いながわ委員","kind":"質問・要望","question":"先ほど、施設整備課長から説明会が実施されたという話ですけれども、ぜひわかりやすい丁寧な説明をしっかりとしていただきたい。理解を求めるよう頑張っていただきたいというと言い方はおかしいですけれども、ご努力をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問","question":"第４回会定例会に契約議案が提出されたわけですけれども、いつの時点で金額の変更が必要だと判断されたのか伺いたいと思います。いつの時点で４月の開設が延び、契約金額を変更するという判断に至ったのか、その状況を伺いたいと思います。","respondent":"小林施設整備課長","answer":"今回の変更理由における、衛生工事業者および工事を管理している設計事務所、それと品川区で何度も工期短縮を図るための打ち合わせを行いました。そこから工期の延伸についての打ち合わせを行っていったです。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問","question":"４月から利用される方が現にいらっしゃる中で、利用者への報告は、１０月上旬に判断した時点で速やかにすべきだったのではないかと思います。１０月上旬に一定の判断をしたのであれば、現時点で振り返ってみてどう思われるか、ご見解を伺いたいと思います。","respondent":"小林施設整備課長","answer":"５カ月なのかとか、６カ月なのかとか、いろいろ工期延伸についての話し合いを何度も行いながら進めていったところです。固まった段階で所管と話し合いを進めていたのですが、そこで固まった時点で改めてそういう説明だとか、そういうところを進めていったです。","id":"exchange-051"},{"speaker":"中塚委員","kind":"質問","question":"経費などの積算もあるでしょうから、１０月上旬の判断で、議会にも示すことができたと思うのです。やはり、直接利用される方へのとりわけ丁寧な説明が必要だったのではないかと思うのですけれども、その点はいかがか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"１０月上旬のころ、我々も連絡を受けまして、また運営事業者とも今後について話し合わないといけないということで話を進めておりました。今回、１１月１日の広報しながわに説明会の開催を掲載し、１１月１５日に説明会を２回に分けて実施したところです。","id":"exchange-052"},{"speaker":"中塚委員","kind":"質問・要望","question":"１０月上旬にそう判断され、説明会が結果として１１月１５日になったというのは、説明を行うまでの期間が長いと指摘せざるを得ないと思います。４月から、ほかの施設とは少し性格が変わってくると思いますので、今後はしっかりと利用者への丁寧な説明を強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"吉田委員","kind":"確認","question":"４カ月延伸の契約できちんと立ち上がるということを確認しないといけないかというふうに思っております。１０月に判断されたということですけれども、今は１２月ですから、それからまた進んでいる部分があるわけですね。","respondent":"小林施設整備課長","answer":"そういう状況で進めていて、今言った４カ月、これは業者からも言われている数字です。打ち合わせを何回も繰り返しまして、その４カ月で固めて、今回、最終的に４カ月の延伸ということで議案を上げた次第です。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"危険負担条項というのですか、もし不測な事態が起きた場合は区が負担するという契約だということは確認しましたけれども、どうなのでしょうか。そちらがきちんと解決しないと、これがあと４カ月で大丈夫という判断をこの総務委員会でやっていいのかというのは、その辺はいかがか尋ねました。","respondent":"小林施設整備課長","answer":"工法の変更だとか、２月の履行に向けて、そういう打ち合わせを数回持ちました。徹夜だとか突貫工事で工事を進めていくには、１０月の上旬にいろいろと検討していったところ、最終的に一定の判断を下したです。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問","question":"ここまで進む予定だったけれども、もう少し細かくやるべきだったのではないですかと、それがきちんとされていたのですかということなのです。だから、それがどう機能していたのでしょうかということなのです。","respondent":"小林施設整備課長","answer":"それと工事を管理している設計事務所が一丸となって、想定外のものも含めて、２月の下旬に履行しようという努力を今までずっとやっていたわけです。１０月上旬に、本当に苦渋の決断をし、４カ月の延長となったところです。","id":"exchange-056"},{"speaker":"吉田委員","kind":"意見","question":"それから、突貫工事で何が何でも２月竣工を目指すべきではないと判断されたのも理解できるのです。そして今回、これで大丈夫という判断をされたのかがよくわからないので、その辺をもう１回だけとの意見を述べました。","respondent":"小林施設整備課長","answer":"ずっと進めていたところなのですけれども、１０月の上旬に、苦渋の選択をしたです。ただ、東京２０２０大会の影響もあるのではないかというのが率直な意見です。","id":"exchange-057"},{"speaker":"吉田委員","kind":"質問・要望","question":"は要望です。事業者への努力を求めながら、ぜひ工程管理をきちんと、その辺はきちんとやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"須貝委員","kind":"質問","question":"区の契約条項には、工期が延びた場合には、その分、増額しなければいけないというルールがあるのですか。その点について説明を求めました。","respondent":"小林施設整備課長","answer":"工事の当初から考えていたものではなくて、想定外のものが発生したということで、業者の責任でもない。４カ月延びることによる人件費、そういった４カ月分の経費を見込んで、変更を提案したです。","id":"exchange-059"},{"speaker":"須貝委員","kind":"質問・要望","question":"費用が日数に応じて確かに発生するのでわかるのですが、民間ではあまりこういう事例は少ないので、それでお聞きしたところです。そして、いや、今回も事故のないように工事を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"高橋（伸）委員","kind":"確認","question":"今、本当に東京２０２０大会に向けた整備の影響で、人手が少ないという現状があります。１点だけ確認ですけれども、孫請けなのかどうか、お聞きしたいと思います。","respondent":"小林施設整備課長","answer":"建築でいくと３つの会社が共同でやっているのですが、いろいろその中でも分かれておりますので、基本的には所長と副所長は入っています。それと打ち合わせの議題によっては、プラス、専門の担当者も入ってきて、打ち合わせをしています。","id":"exchange-061"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"１つだけ確認をさせていただきたいのですが、当初、２月２８日に工期終了で４月開園という予定になっておりました。当初は工期終了から１カ月間ですが、今回、３カ月間あいている理由は何か尋ねました。","respondent":"小林施設整備課長","answer":"そちらの仕様説明をまずその後にします。それと、今回そういうものも見て、３カ月後の１０月という形をとらせていただいたところです。","id":"exchange-062"},{"speaker":"新妻副委員長","kind":"質問","question":"では、当初は１カ月しかなかったということはそういうことをしないということか尋ねました。","respondent":"小林施設整備課長","answer":"２月履行に向けて、多分４カ月延伸だと、工事だけで終わるのではないかと。そういう機器の説明、本来は２月のところの中でおさめようと思っていたのですけれども、一応そういう形です。","id":"exchange-063"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。とにかく利用者の方が一番心配されているところかと思いますので、またそこも確認をしていただきながら進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"必要な工事ですので賛成いたしますが、一言、まず利用者への丁寧な説明はしていただきたいということと、もちろん今回も工期をしっかり守ってほしいと求めましたが、やはり工事は安全が第一ですので、そこも強調した上で賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"吉田委員","kind":"質問・要望","question":"これはこれで進めていただきたいですけれども、同じ契約の中に、それをちゃんと区に対して請求するということが定められております。こういう工期の契約を議会として議決をするというのも議会としての責任もとても重いわけですから、今回、あえて要望としてつけ加えさせていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"中塚委員","kind":"質問・要望","question":"説明会では、４月開設を期待して待っていた方にとっては、緊張感ある状態だったのかと思います。工事を管理する施設整備課の出席を求める内容の陳情ですけれども、工事内容についてもさまざま質問に答えるために、いかがか尋ねました。","respondent":"小林施設整備課長","answer":"あくまでも今回のところについては、施設を利用する方への説明会ということでありましたので、その点で施設整備課は出席しなかったです。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問","question":"質問者の疑問にしっかり答えるというのは、やはり所管が異なりますから、納得を得る説明を行うのは難しいのではないかと思うのです。この陳情にあるように、説明会を開催すべきと思いますけれども、いかがか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"ですので、今、骨組みのところはでき上がったところという説明をしました。本当に１０月には開設できるのかというところで、そちらには１０月開設を目指して今頑張っているところですという説明をしております。","id":"exchange-068"},{"speaker":"吉田委員","kind":"質問・要望","question":"開設がきちんとされるのだろうかという疑問にもつながると思いますので、そこを払拭していただくためにも、施設整備課の説明会は難しいのでしょうか。その辺の見解を教えてほしいと求めましたが、いかがか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"質疑応答のところでも、１時間以上を割き丁寧に説明をしたところです。実際に質問票を出された方としては、たしか１５名程度いたのですけれども、そういうところでまた丁寧に対応していきたいと考えております。","id":"exchange-069"},{"speaker":"吉田委員","kind":"質問","question":"では、施設整備課が参加する説明会は行われないということなのでしょうか。もう少し広い説明会、施設整備課が参加し、それはもう行われないということなのか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"今回の説明会、午前が１１３名、その中で工事の進捗がどういうふうになったと質問されたのは１人だけでございました。今のところは、施設整備課からの説明は時間の関係でもできないかと考えております。","id":"exchange-070"},{"speaker":"吉田委員","kind":"質問・要望","question":"実際問題難しいと思いますので、その辺の必要性も考えると、今後ぜひ検討してほしいと求めました。もし何か施設整備課のほうで見解があればお伺いいたします。","respondent":"小林施設整備課長","answer":"先ほども所管のほうでお話ししましたけれども、今回の説明が利用者のための説明ということと、なおかつ、１時間以上、質疑応答を行ったということと、さらに、その場で質問ができなかった方、しづらかった方につきましては、質問票ということで丁寧な対応を行っているところです。","id":"exchange-071"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのときに、工事の専門的な説明がその場ですぐきちんとできるという人が同席する説明会について、ぜひ今後検討してほしいと求めました。これは要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"いながわ委員","kind":"質問・要望","question":"確認したいのですけれども、車両出入口の縮小の2)、近隣への配慮なわけですね。そうなってくると、また延伸する可能性も出てくるという考えも１つあるという認識でいいのか尋ねました。","respondent":"小林施設整備課長","answer":"北側ゲートと東側ゲートという２つのゲートを当初考えていたところですけれども、控えてほしいというお話があったので、今まで控えておりました。","id":"exchange-073"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"には、やはり近隣の方への配慮ということで、そこは丁寧に行っていただきたいと思うのです。１１月１５日の説明会は、近隣の方々への配慮ということでご説明は今後どのようにされていくのかというところを１点だけ確認をさせてください。","respondent":"小林施設整備課長","answer":"変更契約後に速やかに近隣を回って、これは１軒１軒訪問して、個別対応による説明をしていこうという考えを持っています。連絡場所、問い合わせ場所を決めておりますので、そこで個別の対応をしていきたいと考えております。","id":"exchange-074"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。ご要望が出るようであれば、それはまたしっかりおこたえほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"新妻副委員長","kind":"確認","question":"結論としては不採択です。丁寧な説明をしていただいているということも確認できましたけれども、また今後も引き続き丁寧な説明をお願いして、不採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"中塚委員","kind":"意見","question":"その方法、スケジュールについても質疑があることは十分考えられますので、両方の出席が必要だと思います。よって、陳情の要旨や理由等に賛同しますので、採択ということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"いながわ委員","kind":"意見","question":"結論を出すということで、不採択。それがどうこうというよりは、むしろ１日も早く、安全にスムーズに竣工していただくことを祈っておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"須貝委員","kind":"質問・要望","question":"今後、区民の信頼を損なうことがないように努めてほしいと求めました。この件に関しては、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほどのいながわ委員からご質問がありましたけれども、やっぱり今後の工事の適切な工程管理を区に求めるというのも陳情内容に入っております。適切な工程管理ということは、ぜひ区に求めていきたいと思いますので、この陳情については採択をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"松澤委員","kind":"質問・要望","question":"本日結論を出してほしいと求めました。不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"}]},{"id":"topic-06","title":"「」を聴取いたします。 初めに、(1)専決処分の報告","agenda":"「」を聴取いたします。 初めに、(1)専決処分の報告","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"事故のないように注意してほしいと求めました。１点だけ、決め方について伺いたいのですけれども、この損害賠償額の決定の経過についてご説明ほしいと求めました。","respondent":"島袋人権啓発課長","answer":"こちらは、区の契約しております保険会社との内容に基づきまして確定させていただいたものでございまして、修理費とありますが、撤去費、新たな工事費など全てのものを含んです。","id":"exchange-082"},{"speaker":"須貝委員","kind":"質問・要望","question":"やっぱりそういうふうに安全にお金をかけて、もし区民に万が一のことがあったら、ご本人も、ぶつけたほうも大変です。だから、そういう工夫をやっていく時期に来たのではないかと思いますので、要望だけいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"いながわ委員","kind":"質問・要望","question":"保険に関してはリースだと品川区がかけなくていいですから。今後やっぱり全体的に考えていかなければいけないと思うのですが、車のリースをどうこうではなくて、保険に関してはわかる範囲で教えていただきたい。","respondent":"立木経理課長","answer":"委員おっしゃるとおり、事故等の実績、そういったものを勘案した中で次年度の金額が決まってくるというところではあります。その都度その都度、どちらの方式がいいか検討した上で決めていければというところで、今やっている最中です。","id":"exchange-084"},{"speaker":"いながわ委員","kind":"意見","question":"事故を起こした方も、何カ月か運転をしてはだめですという話なのか、それとも１回、教習所に行ってもらうのか、いろいろ考え方もあると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"}]},{"id":"topic-07","title":"「その他」を行います。 まず、今定例会の一般質問に係る所管質問でありますが、今定例会の一般質問中、総務委員会にかかわる項目","agenda":"「その他」を行います。 まず、今定例会の一般質問に係る所管質問でありますが、今定例会の一般質問中、総務委員会にかかわる項目","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"この間の一般質問のご答弁と、先ほどのご説明だと、今、試行的に社会保険労務士と公認会計士による外部評価の導入を検討しているというご答弁でした。どのように行われていて、現段階の検討段階がどの辺まで来ているのかとかなどについてもう少し詳しいご説明があればしていただきたいという質問です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"吉田委員","kind":"質問・要望","question":"その検討段階、どういうふうに検討されているのかということと、現在どの辺まで検討が進んでいるのか。できることなら、いつぐらいから本格実施になるのかとかまでわかれば教えていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/147246?Template=document&Id=2124#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":58974,"voices":255}},{"id":"h30-20181211-6","meetingId":"h30-cm12","date":"2018年12月11日","dateIso":"2018-12-11","committee":"区民委員会","time":"午前１０時００分～午後 ２時０９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"渡辺委員","kind":"質問・要望","question":"最初からパーフェクトを求める事業はおそらく民間も含めて易しいことではないと思うのです。その辺のお考えを２つ目に質問。","respondent":"立川文化観光課長","answer":"例えば、そのころはやはりまち場の方は熱意を持って少しずつ取り組んで、それに対して行政がいかに支援できるかということでやってきたと。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問・要望","question":"イベント１つとってみても行事でもいいのですが、もちろん税の投入もあるときに、では効果検証どうだろうとこれはよく言われますよね。品川区も広いですから、行政が役割として求められている、こんな制度を研究されたらどうかなというのを踏まえて伺います。","respondent":"立川文化観光課長","answer":"民間でご活躍されているコーディネーターというかアドバイザー的な方は何人かいらっしゃいます。まち場のいろいろな課題を解決するためにご意見をいただけるような仕組みを今後検討・研究していく必要があるのかなと考えております。","id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"でも、受け手からしたら、１位は何だろうとか上位の方に関心が行くではないですか。今は動画の時代ですから、「ようこそ品川へ」というテーマで３０秒コメントしてくださいとか、「何とか品川」でもいいのです。","respondent":"立川文化観光課長","answer":"皆さんが応募されるわけではないのですけれども、誤解を生まないように行政としてはいろいろ表現していかなければいけないというのがまずあります。遊び心は、事業によってはその辺を発信力として活用してやっていくというのは、大変貴重なご意見だと考えています。","id":"exchange-003"},{"speaker":"渡辺委員","kind":"質問","question":"前も伺ったことあるのですが、品川区が何かしらでもっと上位に行ってほしいなと。それを最後に説明を求めました。","respondent":"立川文化観光課長","answer":"ただ、「羽田空港を観光資源にするなんていう、そんなつまらないことは考えていない」といったニュアンスのことをお話しいただいたのです。渋谷区、新宿区、実際何もしなくても人が集まるような地域と品川区が張り合うようなことはしたくないと考えております。","id":"exchange-004"},{"speaker":"渡辺委員","kind":"意見","question":"情報を得て刺激になって、こちらの品川区の施策のモチベーションが上がるという意味では、大田区に行ってみたくもなりますしね。そういうのを意識されるってとても大事なことだと改めて思いましたので、またそういう情報があったらぜひお知らせいただけるといいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"商店街の皆さんなり、だからこういうふうに集中的に平成二十四、五年ごろから平成２８年ごろにかけて各区がこういうプランをつくってやっているのか。全然勉強できていないですから、素朴な疑問として思ってしまったのですけれども、そこら辺を解説いただければありがたいなと。","respondent":"立川文化観光課長","answer":"２３区内のほとんどの区が目指す観光は、まず、住んでいる人に楽しんでもらうと。いわゆる従来型の観光ではなくて日常生活の中にそういった観光を意識していこうといったことが平成２０年前後から各区で広がってきたと捉えています。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問・要望","question":"そういう住民の要望なり、あるいは口に出して言う要望ではなくても、何となくそういう雰囲気が平成２０年ごろからできていったという、実態としてあったということですかね。","respondent":"立川文化観光課長","answer":"ざっと見ますと平成２０年ごろから始まっていますので、議会からの要望だとか、そういったことを経て各区はプランをつくってきたと認識しております。","id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、外から人を呼び込む観光というよりは、住んでいる人に楽しんでもらう、気持ちよくなってもらうというか、そういう趣旨の観光ということか尋ねました。","respondent":"立川文化観光課長","answer":"今委員おっしゃった、まず住んでいる方、区民の方に楽しんでもらう、なおかつ区外からの来街者の方にも楽しんでもらう。ここ数年外国人旅行者が増えておりますので、日常生活などに触れてもらうことで楽しんでもらう、そういったところで都市型観光は展開されております。","id":"exchange-008"},{"speaker":"おくの委員","kind":"意見","question":"平成２８年策定の都市型観光プランの目標としては、これだけ外側から呼び込みたいとか、持たれているわけですよね。品川区の観光プランの目標というか、あるいは観光をこうやって議論しようという目標・目的みたいなところをご説明ほしいと求めました。","respondent":"立川文化観光課長","answer":"平成２８年に都市型観光プランをつくりまして、観光のコンセプト・目標についてもう一度ご説明いたします。都市型観光の継続的な展開、新たな時代への適切な対応ということで、繰り返し訪れて楽しい観光都市づくりです。","id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"平成２８年からまだ２年ですが、効果はこれぐらい上がったとか、こういう流れになってきたよとかいうのはあるのでしょうか、ないならないで仕方がないなと思うのですが、まだ２年たっていないわけですから。","respondent":"立川文化観光課長","answer":"それから、外国人観光客、シニア世代、こういった方々が具体的なターゲット、マーケットの考え方です。実際に商店街などで聞きますと、やはり日本の商店街自体が物珍しいということで訪れていただける方は増えています。","id":"exchange-010"},{"speaker":"大倉委員","kind":"質問","question":"イルミネーションはここがすごいですよという宣伝がうまくできてくると、回遊性という面でも上がってくるのかなと思いました。入場料１,８００円は少し高いというお話もあったと思うのですけれども、商店街も絡めながらみたいな、それについていかがか尋ねました。","respondent":"立川文化観光課長","answer":"それから、旅行代理店と連携する、関係者の方が１つの資源を磨き上げるところで力を出し合っていくということが一番重要なことだと思っています。そのつなぎ役として行政としてできることがあると思いますので、その辺については検討していきます。","id":"exchange-011"},{"speaker":"大倉委員","kind":"意見","question":"そのためにも、やはり先ほど言った分析とか調査とか、チャレンジしていくところでもしっかりとそのチャレンジがどうだったかということも精査しながら進めていくといいと思うので、ぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"そもそも論をお伺いするのですが、この資料を今回つくったと思うのですけれども、１番が千代田区、２番が中央区、３番が港区となっていますけれども、この順番の根拠は何か尋ねました。","respondent":"立川文化観光課長","answer":"冒頭でお話ししていなかったのですけれども、一番下にあるように、観光政策はさまざまな課が予算を持っている可能性があります。今回出した金額については、各区の観光関係施策の全体や総額をあらわすものではないことをお断りします。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"今日それ初めて知りました、品川区は背番号が９だと。続けてお伺いしますけれども、今日この都市型観光でほかの区が出ているのであえてお伺いしますが、どこに連れて行かれますか。","respondent":"立川文化観光課長","answer":"それから、広町の山手線の基地、区外におきましては、近いところで東京タワーのふもとに行って見上げてもらいます。お金を払って上までは行かないと。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"伺ってよかったです、この質問。今回も明治維新という形で特別展をやられていたけれども、個人的な考えなのですけれども、その辺については今後も含めていかがか尋ねました。","respondent":"立川文化観光課長","answer":"過去に取り上げたかどうかはいま確認できないのですけれども、全国的に有名な方ですので、歴史館等と連携して、どういうふうに伊藤博文公を品川の観光資源としてアピールできるかは研究していく必要があると思います。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"今年のいつだかにも伺っているのですが、都市型観光に力を入れている区を幾つか以前教えていただいたと思うのですけれども、それをまた説明を求めました。","respondent":"立川文化観光課長","answer":"そのとおりの答えができないかもしれないのですけれども、近隣では、港区、大田区、その辺は間違いないです。","id":"exchange-016"},{"speaker":"田中委員","kind":"意見","question":"暮らしや生活文化に根ざした資源を通して、来訪者が区民と触れ合い交流することで、繰り返し訪れて楽しい観光都市を目指すものですと書いてあります。","respondent":"立川文化観光課長","answer":"都市型観光の考え方としましては、沿線市民、まずその辺をターゲットとして考える必要があると思います。それから、外から来ていただける方もいらっしゃいますので、そういった方にも楽しんでいただきたいという思いで挨拶文を書いたと理解しております。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"住民が置いていかれているような、何となくそんな気がしていたので、その住人の方たちがまず楽しめるような視点は忘れずにいてほしいです。ここにも書かれているように、生活文化に根ざした資源という、今ある資源を活用してほしいというのを強く要望したいです。","respondent":"立川文化観光課長","answer":"ただいまご指摘のありました、いわゆる生活文化、身近な資源、こちらは大変大切だと。同時に新たな観光資源として区の目玉になるようなものも必要かなと、総合的に施策については推進していきたいと考えております。","id":"exchange-018"},{"speaker":"本多委員長","kind":"質問","question":"今実際には東京には２つの大森貝塚がありますが、そこを品川区としても「大井貝塚」と名称を変えていくべきだという、何か動きとかあるのか。もしないならこれから働きかけしていくのか、その辺だけ簡潔に説明を求めました。","respondent":"安藤文化スポーツ振興部長","answer":"実際に品川区ではこれまでに３度ほど調査をやって、今の大森貝塚公園が本当にそこにあった場所だというのが歴史的に証明されているところです。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問・要望","question":"それももっと強く言っていただきたいのと。何で大森という名前がついてしまっているのというのも、まさに委員長と一緒の考えなので。","respondent":"安藤文化スポーツ振興部長","answer":"かつてお答えしましたとおり、品川区の大森貝塚が正解ではないですけれども、正しい場所です。大森の由来については知識がありませんので、今ここで答えることは難しいです。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/374422?Template=document&Id=2828#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":17951,"voices":57}},{"id":"h30-20181211-7","meetingId":"h30-cm12","date":"2018年12月11日","dateIso":"2018-12-11","committee":"厚生委員会","time":"午前１０時００分～午後 ２時１０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)「第３期品川区地域福祉計画（素案）」およびパブリックコメントの実施","agenda":"はじめに、(1)「第３期品川区地域福祉計画（素案）」およびパブリックコメントの実施","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それから、策定委員会が３回行われてきましたけれども、これは議事録などは公開されているのでしょうか。そこの点についても教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"ご説明または意見交換をさせていただいたところ、その支え愛活動会議につきましては、それを構成するメンバー各地区でそれぞれです。議事録についても公開をしておりますので、もしよろしければご覧いただければと思います。","id":"exchange-001"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"一般区民に対しての説明会、これを説明していただく機会をぜひつくっていただきたいと思うのですけれども、その点について１つ。冊子が欲しいという方に対しては、ぜひ提供できるようにしていただきたいというふうに思うのですけれども、その点と合わせて。","respondent":"大串福祉計画課長","answer":"住民への説明といったところですが、前期だけでも１４回、また、これからもずっと各地区を回らせていただきます。こちらにつきましては、柔軟に対応していきたいと思っているところです。","id":"exchange-002"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう場面をぜひつくっていただきたいと思うのですけれども、さまざまな活動をされていて、そういう方がいらっしゃると思うのです。ぜひこういうふうに、懇談会の中に一般区民も参加できるような形でぜひ行っていただきたいと思うのですけれども、改めてお願いします。","respondent":"大串福祉計画課長","answer":"そうした中でお話をするですので、一般の区民の方が入るのは少し難しいというふうに思っております。策定委員会が今月にも開かれる、そういった中でさまざまな皆様からご意見をいただけるというふうに考えております。","id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"こういう計画ができるときというのは一番の機会なので、ぜひ説明会を行っていただきたいと強く要望しておきたいと思います。ＰＤＣＡを具体的にどういう形でしていくのか、１年ごとにまとめを出して、その点についても説明を求めました。","respondent":"大串福祉計画課長","answer":"メンバー構成については今現在検討中ですけれども、ご意見をいただきながら、このＰＤＣＡを回していきたいというふうに考えているところです。基本的には、開催は１年に１回お願いしようというふうに考えております。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"では、来年４月からのメンバーということになるのでしょうか。１年間に１回ということなのですけれども、そのご意見をもとにしてまた１年間のまとめをつくるような、そのようなイメージになるのか尋ねました。","respondent":"大串福祉計画課長","answer":"我々のほうからの説明、またご意見、こういったスタイルで行っていくというふうに考えております。策定委員会は全部で３回行っておりますけれども、庁内の検討会、この計画をつくらせていただいております。","id":"exchange-005"},{"speaker":"こんの委員","kind":"質問・要望","question":"かかわってほしい人は、かかわってほしいと言える人もいれば、かかわってくださることに非常に大事だなというふうに思うところなのです。そうした考えはいかがか尋ねました。","respondent":"大串福祉計画課長","answer":"最終的には包括的な相談支援といったところで、また、対応できていくだろうといった構成にしています。一緒に考えながら、その課題について取り組んでいく、手間もかかると。","id":"exchange-006"},{"speaker":"若林委員","kind":"質問・要望","question":"この３つ、(3)までですか、地域福祉と共生社会と同じじゃんと言われます。その体系図との位置関係がどうなっているか、この施策の１）は、最近の計画はそういうふうにつくっているものではないか尋ねました。","respondent":"大串福祉計画課長","answer":"どういう形で入れられるか検討はしてみたいと思います。一定、色分け等はさせていただいているところですが、もう少しわかりやすくといったところで、検討させていただければと思います。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"３職種配置されていないので、それが支え愛・ほっとステーションになるのか、そういうところもよくわからないので教えてほしいと求めました。この重点課題というのはどういうところから出されてきたものなのかというあたりも教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"やはり品川区、支え愛・ほっとステーションを全１３地区に展開し、コーディネーターを配置しているといったところで今進めております。したがいまして、各課の個別計画、こういったものについては重点課題というふうにさせていただいているといった考え方をとっております。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"地域包括でやはり３職種配置して、そこのところが別々の組織になっているので、本当に連携というのがすごく難しい。やはり厚労省が求めている地域包括ケアシステムの拠点は地域包括支援センターがなるべきだと言っているので、その辺についていかがか尋ねました。","respondent":"大串福祉計画課長","answer":"今現在は主に高齢者というところで進めておりますけれども、あるいは在支の関係の方も入っていらっしゃる、総合的な地域での会議体になっております。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"だから、地域包括というのは本来、そういった地域での包括ケアシステムのやはり拠点としての役割という位置づけになっていると思うのです。やはりこういう地域福祉計画の中にも位置づけられるべきなのではないかという思いがするのですけれども、その点についてどうでしょうとの意見を述べました。","respondent":"大串福祉計画課長","answer":"地域包括といったところの位置づけ、または支え愛・ほっとステーションの位置づけ、それぞれ各自治体で異なっていることかと思います。これまでも２０在支をつくって、この地域福祉全体を進めるといったところで、この地域福祉計画の中にはそういったところを入れております。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"最後に要望だけ。私はやはり改めて、その３職種配置の地域包括支援センターはどうしてもしっかりとつくっていただきたいという要望をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"石田（秀）委員長","kind":"質問","question":"こういう部分がどうしてもなかなか教育で全員参加でやると言うと、そこを行っていかないと、育っていかないではないですか。イベントなどは今、地域の人は出てくるのだけれども、イベントだって支える人が少なくてどうしようかということになっているわけではないか尋ねました。","respondent":"大串福祉計画課長","answer":"なぜ核家族化が進んでいっているのかといったところも踏まえると、３世代を諸手を挙げてというのも難しいかというふうには思ったところです。いただいたご意見については検討します。","id":"exchange-012"}]},{"id":"topic-02","title":"国民年金第１号被保険者の産前産後期間の保険料免除","agenda":"国民年金第１号被保険者の産前産後期間の保険料免除","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"さまざま広報であったりとか、あると思うのですけれども、申請されていなければ抜けてしまうわけです。そのときにこれをまたもう１回、その辺の周知の仕方は、もう少し何かないのかと思うのですけれどもとの意見を述べました。","respondent":"三ツ橋国保医療年金課長","answer":"非常に、周知の仕方は広く周知したいと思っているところですが、この出生届の部分は非常に難しい問題がございまして、そのあたりもよく勘案しながら、できる限り広く周知をしてまいりたいと考えています。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"せっかくこういう形で４カ月間の国民年金が免除されて、それも払ったという形で年金が受け取れるという制度ができたのに、申請しなかったためにそれが適用されないということがないような形での取り組みをぜひ工夫していただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"}]},{"id":"topic-03","title":"産後ケア日帰り型事業の拡充","agenda":"産後ケア日帰り型事業の拡充","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"１１時から３時の間で、いわゆる４カ月未満までのお母さんなので、あるいは預けてご自分だけという場合もあるのでしょうかね。時間が限られている１日の中でのケアというのが、私としてはもう少し必要だと思うのですけれども、その辺はいかがか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"５項目ぐらい聞いているのですけれども、できなかったという回答は、９５％以上がとてもできたという回答をいただいております。利用が１回ということもありますので、例えば１回だけではこの方はまだちょっと、支援が必要かなと思う方につきましては。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"拡充ということで進めていっていただきたいのですけれども、助産師会との連携というのはどうなっているのかというところをお聞きしたいのと、助産師会との関係はどうなるか説明を求めました。","respondent":"榎本荏原保健センター所長","answer":"東京医療保健大学と助産師会と区と３者でずっと話し合いを進めて、ケアの内容も含めてつくり上げてきたというのが１つあります。話し合いながら事業を、訪問型のときもそうだったのですけれども、どのようにしていくか話し合いをして進めているというところです。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私が聞き違えていたのかと思ったので、何かあまり連携がとれていなかったようにとっていたので、その辺は続けて連携をとってください。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"この中で課題はやはり相談員の体制だと思うのですけれども、区として課題はどういうふうに捉えているのか、それから、相談員に対する研修体制とか、その辺まで考えているのかどうか、その辺はどうか尋ねました。","respondent":"松山障害者福祉課長","answer":"ご意見を１２月中に全ていただきまして、１月の相談支援部会、あるいはまた在支とも打ち合わせを重ねて行ってまいりたいと考えています。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"区としていつごろから実施を考えているのかというのと、それから、障害児者総合支援施設、今度できるところに区の分室をつくるということで、こういうところもいろいろな研修の場に使えるのではないかと思うのですけれども、この辺はどういうふうに考えているのか尋ねました。","respondent":"松山障害者福祉課長","answer":"実施予定ですけれども、まだ３月までに最終報告ということで、４月からの実施は難しいというふうに考えております。総合支援施設のところですけれども、確かに総合支援施設の中に区の分室が入るということで、福祉カレッジも含めてですけれども。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"意見","question":"もう１点だけ。当然、その辺は区としてはノータッチと言うか、フォローを考えなくていいのかというのが１点気になっているところですとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"確かに経費の部分、あるいは勤務の中での負担、研修に出て行くことへの負担感というのは、お話の中では聞いております。今すぐに何か具体策というのはまだ考えておりませんけれども、またフィードバックしたり、皆様方から意見を頂戴しながら考えていこうと考えています。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"まだこれから課題もあるし、地域の中で相談しやすい体制をつくっていく点では、ぜひうまく進めてもらいたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"こんの委員","kind":"質問","question":"ヒアリングをして対面式で聞き取りをしてくださっているということで、大変丁寧に聞き取ってくださっているなと思います。在宅介護支援センターは７カ所ということで、全体で何カ所のうち７カ所で、なぜここの７カ所で実施されようと思ったのかということを説明を求めました。","respondent":"松山障害者福祉課長","answer":"在支が２０カ所のうち７カ所ということで、まずは高齢障害の方、あるいは障害に何らかかかわりのあるところをピックアップさせていただきました。やはり具体的に、あとは地域バランスを考えまして、６圏域で１カ所以上はというところで選定したものです。","id":"exchange-022"},{"speaker":"こんの委員","kind":"質問","question":"バランスよくお聞きしていただいて、こういったご相談のはざまと言うのでしょうか、これまでもあったのだろうと思うのです。今まではどういうふうにそのご相談者の高齢福祉の部分、どのような形でご相談されていたのか、改めて状況を伺います。","respondent":"松山障害者福祉課長","answer":"は若くして障害を負っていた２号被保険者の方への対応ですけれども、比較的多いのは、障害を受けて高齢者になられる方というのは多くあります。２号被保険者の場合については、それぞれのところでの、制度上のサービスというものが主なものと考えています。","id":"exchange-023"},{"speaker":"こんの委員","kind":"質問","question":"手当てをしなければいけないというところが、他課と連携がとりやすい状況であったかどうかというのが、先ほどのお声で１つあったかと思います。では、在支に置くとこういったところはきちんと手当てされていくのか、その辺のところはどうなのか尋ねました。","respondent":"松山障害者福祉課長","answer":"もちろん在支ありきではないということは認識しており、民間支援事業所の誘致というのも、やはり推進していかなければならないと考えています。民間支援事業所の誘致をするほか、在支への障害者の相談支援員の配置というのは、このヒアリング調査から読みとることができます。","id":"exchange-024"},{"speaker":"こんの委員","kind":"質問","question":"ご家族もろもろ見ていくと、生活そのものはどうなのか。そうなると、そのほかの課との連携というのも考えられると思うのですが、その辺はどのようにお考えか尋ねました。","respondent":"松山障害者福祉課長","answer":"確かに障害の部分、非常にライフサイクルや、生活の中で支援をしておりますので、他課との連携というのは非常に複数回にわたっております。","id":"exchange-025"},{"speaker":"こんの委員","kind":"提案","question":"研修をしていくというところで、区のサービスをどれだけご存じで、その場で提案できるかというのが非常に大事であると思うのです。これは期待しておりますので、その辺のところのご相談の受け方と対応力と連携のとり方というところをお願いしたいと思いますが、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"例えば区の制度の知識、あとはご本人の状況や家族を含めてアセスメントするということ等々、かなり高度な対応力を要求されることかと思います。業務の棚卸、きちんと相談員が本来すべきことというのを洗い出して、その上でまた研修を通じて質の向上を図ってまいりたいと思います。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"６５歳を過ぎると基本的に介護保険優先ということになるので、それがなぜ７カ所なのかというのを、改めて教えていただきたいのが１点です。ヒアリングの結果では、聞き取りというのは大まかにこの項目でどういうご意見ですかという、そういう感じで対面で聞かれたということなのか尋ねました。","respondent":"松山障害者福祉課長","answer":"質問項目についてですけれども、なかなか課題があらわにならないということですので、１０項目に対して聞いております。お答えになった方というのは、在支の場合は管理者の方とケアマネージャーと聞いております。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"この７カ所がゆくゆく指定特定相談支援事業所を併設する可能性のある在支というふうになっているのでしょうかということが１つと、そうした場合、指定特定相談支援事業所の最低限度の人員体制の必要数というのはどうなっているのかについても説明を求めました。","respondent":"松山障害者福祉課長","answer":"指定特定相談支援事業所の基準ですけれども、管理者１人、これは兼務が可能だと考えています。は相談支援専門員は専従ということで１名以上ということになっています。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その辺の仕組みを教えていただきたいのですけれども、東京都の研修を受ける資格というのはどういう資格になるのか。そのもともと持っている資格というのはどういう資格で、実務経験がどれくらい必要になるのかということを教えていただきたいのと、説明を求めました。","respondent":"松山障害者福祉課長","answer":"東京都の相談支援専門員の研修というのを受けて、相談支援専門員としてきちんと従事することができるということなのですけれども、やはり。拠点相談支援センターに専門員がおりますので、研修プログラム等も含めまして、またご意見を頂戴しながら考えていきたいと思っています。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"もしも在支と一緒にやるというふうなことになるとしても、在支と別にこの新たな相談支援専門員を置いて、併設のような形でイメージすればいいのか尋ねました。","respondent":"松山障害者福祉課長","answer":"これから仕組みについて、その方が実際に支援員として相談を受けることになりますので、さまざまな課題というのはこれから出てくるかと考えています。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこの充実をしてほしいというのは、３年間の障害福祉計画が今年から始まりましたけれども、項目としてぜひ入れていただきたい。そして広く障害者の皆さんからご意見を伺うという形にぜひしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"委員ご指摘のとおり、来年度につきましては、障害児者の方に対しましてアンケートを、今後の計画に向けて実施する予定です。相談についての項目というのは、アンケートの中に入れていきたいと、既に私も思っております。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ぜひよろしくお願いいたします。在支のところに障害者の相談支援を併設するとなったときに、そういう点については、障害者の部分から見たらいかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"やはり障害のある方は、疾患によっては医療的な知識が必要と考えていますので、伴ったものが配置できれば一番よろしいかと考えています。ただ、現実的にはこれからということになりますので、具体的には１つずついろいろな課題をクリアしながら進めていきたいと考えています。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"社会福祉士、主任ケアマネの３職種配置の地域包括支援センターという形でぜひつくっていただきたいということで、要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"若林委員","kind":"確認","question":"確認です。２ページの6)の地域ケア会議でのケース協議ということで、こういう区の認識はありますか。","respondent":"松山障害者福祉課長","answer":"ケース会議についての認識ですけれども、実際に障害者の拠点相談支援センターの中には、これが全ての意見なのかというと難しい部分もあると思います。これは本当にヒアリングのお答えをそのまま持ってきているということなので、１つのお答えということになろうかと思います。","id":"exchange-034"},{"speaker":"石田（秀）委員長","kind":"提案","question":"私から１つだけ確認させてください。そこの確認だけ教えていただきたいとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"確かに、総合支援施設は指定管理ということなので、指定管理者が施設をまず活用していただきまして、当然ながら総合支援施設ですので、指定管理者と区が連携をとりながら、一緒に福祉カレッジも含めまして、研修をしてまいりたいと考えています。","id":"exchange-035"}]},{"id":"topic-05","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１点は子どもの均等割無料化を求めますということでの質問に対して、そして国から、国が求めている削減・解消すべき法定外繰入というのは。ですから、留意事項を守っているということにはならないのではないか、そこのところを改めてご説明いただきたいということでお願いしたいと思います。","respondent":"三ツ橋国保医療年金課長","answer":"これまでも区は納付相談や財産調査など丁寧に実施し、必要に応じて執行停止も実施しており、国保制度の安定性や公平性を引き続き図ってまいります。したがいまして、給与等の差押禁止の基準についても全件実施しておりますし、この差押禁止財産の考え方。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それともう１つ、差押禁止にかかる給付金もという判例のことなのですけれども、ほとんど年金にしても給与にしても預金口座に入ります。この１０万円であるとか、プラス４万５,０００円というのは残しますということで、それで改めていいのか尋ねました。","respondent":"三ツ橋国保医療年金課長","answer":"国保法第７７条または地方税法第７１７条と考えておりますので、今の段階では該当しないということで、決算補填目的の法定外繰入金と考えております。２番目の質問、その部分ですので、今までどおりのことを実施してまいります。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"二重に国が求めるものではないことで、ぜひご検討いただきたいということで、これは主張しておきます。区としては差押禁止財産として承継しないので、預貯金に入ったものであれば差押さえることができるという判断だということなのか尋ねました。","respondent":"三ツ橋国保医療年金課長","answer":"生活が厳しい方につきましては、今までも必要に応じて執行停止、また生活保護や就労支援へのご紹介を実施しております。引き続き、個々に応じた納付相談など、窓口や電話にて丁寧に対応してまいります。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/731730?Template=document&Id=3526#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":56592,"voices":121}},{"id":"h30-20181211-8","meetingId":"h30-cm12","date":"2018年12月11日","dateIso":"2018-12-11","committee":"建設委員会","time":"午前１０時００分～午前１１時４８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)平成３１年１月区営住宅入居者募集","agenda":"はじめに、(1)平成３１年１月区営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"区営住宅の募集は７月と１月の年２回だと思いますけれども、直近の７月の募集戸数と入居者数の数字があれば伺いたいと思います。この間、倍率が５０倍を超えて推移しているのですけれども、この倍率について、区は倍率が高いと考えているか、低いと考えているか、伺います。","respondent":"森住宅課長","answer":"７月の募集の結果ですが、１１戸募集しておりまして、９戸で入居済み、２件が審査中です。倍率は５０倍を超えていて、基本的には高い倍率だと認識しております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"単身者の申込資格は６０歳以上となっておりますので、もしわかれば、これはつかんでいるのか伺います。あわせて、単身・家族向けにかかわらず、応募者の所得の程度というか、所得分布は区としては把握や分析しているのでしょうか、伺います。","respondent":"森住宅課長","answer":"収入の内訳ですが、１０月現在の状況ですが、一番収入の低い第１分類の方が７９.４％、３４０世帯です。年齢構成については、６５歳以上の方が６０％ということで、高齢の方が多いと考えております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"２０代・３０代・４０代・５０代の方は大体何％になるか伺います。その改善の何らかの施策を講じる必要があると思うのですけれども、いかがか尋ねました。","respondent":"森住宅課長","answer":"４０代の方が３４世帯、５０代の方が３４世帯、残りが先ほど申しました６０歳代以上の方々になります。割合としては全部合わせますと７０程度ですので、基本的には区としては、そういったところも使いながら総合的にやっていきたいと考えております。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"区の施策の方針は今お話しされたのですけれども、私が伺ったのは、住宅ストックのことを聞いているわけではないのです。少し問題・課題があるのではないかと思うのですけれども、いかがでしょうかと伺いましたので、もう一度、答えるよう求めました。","respondent":"森住宅課長","answer":"区としましては、生活が苦しいという方につきましては、セーフティーネットなどさまざまな仕組みもあります。今後、居住支援協議会等も含めまして、そういった住宅確保が難しい方のためにどういう施策がとれるのか検討していきたいと思います。","id":"exchange-004"}]},{"id":"topic-02","title":"西五反田二丁目地区のまちづくり","agenda":"西五反田二丁目地区のまちづくり","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、駐車場が目黒川の両岸にあったと思うのですけれども、それは両岸の駐車場を撤去することになったのでしょうか。パーク２４の本社ビルとしてということですけれども、新日鉄興和が持っているビルにパーク２４が賃貸で入って本社ビルになるのでしょうか、伺います。","respondent":"稲田都市開発課長","answer":"高速道路の脇のパーク２４側の通りと、今まさに警視庁と協議中でして、今後協議しながら警視庁にもご理解を得てやってまいります。これはホームページから引用して申し上げました。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。２０１７年２月の建設委員会で質疑があったときに、アンケートをとっているようなところなどが具体的にあるのでしょうか、伺います。","respondent":"稲田都市開発課長","answer":"広報紙等でこの大街区化というのをこの地区でプランをつくりましたということで、２回ほど話は出しております。それから、西五反田一丁目のほうも大街区化できないかということで調査等は進めております。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"一丁目のほうの調査というのはどのような調査というか、どのような段階なのか。一丁目のほうからもそういった要望が出ているということなのでしょうか伺います。","respondent":"稲田都市開発課長","answer":"特に地元からやりたいとかそういう要望があるわけではありませんが、この地区は区画整理等はやられているのですが、狭隘な敷地であることから、適した場所があるかどうかということで、建物の老朽度とか道の幅とか、そういう部分を調査している状況です。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"高さについてはほぼ１.５倍になって、容積もそれにともなって相当な大きさになったと思います。こういった手法を一般化して機械的に広げることはできないし、やるべきではないと思うのですけれども、区のお考えをお伺いします。","respondent":"稲田都市開発課長","answer":"にぎわいづくりも含めながら、こういう共同化したまちづくり、大街区化したまちづくりができるといいと区は考えております。むやみやたらに進めるものではなくて、どうかというところで、区は地域の皆様方の意見を聞きながらやっている状況です。","id":"exchange-008"},{"speaker":"筒井委員","kind":"質問","question":"この大街区化促進に向けてのプランを五反田で行おうとしている取り組みなのですけれども、この範囲内のところには、有名な会社や銀行もありながら、そうではない会社のビルなどもあると思うのですけれども、今そのプランについての合意形成はどのぐらい進んでいるのか尋ねました。","respondent":"稲田都市開発課長","answer":"こういう考え方でこの地区はやったほうがいいのではないかということで、考え方のプランをお示ししている状況です。どうしたらいいかと、そういう話が出てくれば、この大街区化という考え方もあるということで進めております。","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問","question":"では、将来的には都市計画決定とかそういうことになっていくのか尋ねました。","respondent":"稲田都市開発課長","answer":"都市計画決定をするとかいうものではありませんで、都市計画決定するとかいう場面が出てくるかと思いますが、この大街区化については今のところ今回においてはありません。","id":"exchange-010"},{"speaker":"筒井委員","kind":"提案","question":"そのプランどおりになるのは大体どのくらいを予定しているのですか。それとも提案しただけであって、ガチガチにプラン通り完成することは求めていないのか尋ねました。","respondent":"稲田都市開発課長","answer":"こういうまちづくりをやってはどうですかという提案をしているものですので、いつまでに完成とか、いつまでにやらなければいけないというものではありません。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"パーク２４が新社屋になるということで、そのパラソル型の、周りに対する地盤等々の影響は大丈夫なのですか。自転車駐輪場と違って面積も広いと思うのですけれども。","respondent":"稲田都市開発課長","answer":"そういう意味では、地下を掘るということは周辺の地盤への影響は当然考えなければいけません。十分安定した周辺の地盤を保ちながら工事をやっていくということで、施工するときにはその辺はきちんと計算されながらやっております。","id":"exchange-012"},{"speaker":"大沢委員","kind":"質問","question":"地盤がやわらかいところもあるでしょうけれども、そのあたりのところで、これが設置できる場所と設置できない場所はあるのでしょうか。それとも、技術面が発達しているのでどこでもオールマイティにこのような駐車場はつくることができるのでしょうか、どちらか尋ねました。","respondent":"稲田都市開発課長","answer":"最近の技術はいろいろと過去の経験値等も踏まえながら、こういう構造物に関しては安定したものをつくってきていると考えております。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問・要望","question":"教えていただきたいのですけれども、確認なのですけれども、両面通行になるということなのでしょうか。これはいわゆる河川管理者である東京都との協議は必要ないというか、まだその段階ではないということなのですか、その辺について説明を求めました。","respondent":"稲田都市開発課長","answer":"そこを今回整備しまして、車の出入り口も北側の方に持っていき、歩道をつけて安全な通行をするという形で考えております。それと、河川管理用の通路もだぶりますが、現在区道として供用しているところですので、基本的には区の道路管理者と協議します。","id":"exchange-014"},{"speaker":"横山委員","kind":"確認","question":"１点だけ確認なのですけれども、近隣が２メートル以上なのですけれども、地下２階が全て機械式駐車場なのでしょうか。例えば、増水の際にはどのようになるのか確認させてください。","respondent":"稲田都市開発課長","answer":"駐車場は機械式駐車場です。委員ご指摘のとおり、ここは目黒川沿いですので、そういう浸水対策ということで、浸水防止板といったもので対応します。","id":"exchange-015"}]},{"id":"topic-03","title":"第二戸越幹線整備工事（上流部）ついて","agenda":"第二戸越幹線整備工事（上流部）ついて","exchanges":[{"speaker":"横山委員","kind":"質問","question":"こちらの全体事業の完了見込が平成３６年度なのですけれども、こちらは将来的な接続管の部分も含めての予定でしょうか。１時間５０ミリを超える雨量に対してもということですけれども、５０ミリ、７５ミリとかそれぐらい対応ということで想定されているのか尋ねました。","respondent":"持田河川下水道課長","answer":"１点目の事業の終了見込の平成３６年度というスケジュールは、あとその接続の部分も含めての予定で今のところ進めております。何ミリまで対応できるかにつきましては、また所管で検証して、これは整備とあわせてそういった検証もしていきたいと思います。","id":"exchange-016"},{"speaker":"安藤委員","kind":"確認","question":"それと、シールド工法による住民への影響はあるでしょうか。そのあるなしを含めて、その工事の住民への説明はどのようになされるのかお伺いします。","respondent":"持田河川下水道課長","answer":"２点目の工事の影響ですが、施工前にはいわゆる家屋調査をして、施工後何かあれば当然そこで再度調査をしてという対応をとるように進めております。工事に関しても、工事を契約した後には工事に関する車両の搬入等もありますので、地域への工事説明会を予定しております。","id":"exchange-017"}]},{"id":"topic-04","title":"ヒカリの水辺プロジェクト","agenda":"ヒカリの水辺プロジェクト","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"恐らくタイマーだと思うのですけれども、どういう形でやっているのか。どういうふうにやっているのかいつも疑問に思っていたのですけれども、それについて説明を求めました。","respondent":"持田河川下水道課長","answer":"今はいわゆるタイマーのようなもので考えていまして、５時、６時という形で点灯して２２時に消灯という形でのタイマーでの制御を考えております。設置した後にはそういったメンテナンスの契約が必要と考えておりまして、今年度設置ですので、メンテナンスをしていく予定です。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問","question":"イベントのときに配色を変えるということなのですけれども、色の変化ですとか動きのあるという。すごくきれいだなと思うのですが、事業者にお願いするのか、それとも区の職員が簡単に完璧にできるような仕組みになっているのか説明を求めました。","respondent":"持田河川下水道課長","answer":"ある期間からある期間までは何色でということを区で決めて、その期間だけ色を変えるですとか、そのような形での対応を今のところ考えております。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"東京２０２０大会のことが書いてあって、常設とあるのですけれども、機械は設置したら無期限で運用していくものなのか伺います。そして、国や都や区の負担割合はそれぞれ何％ぐらいになるのか、わかればお伺いします。","respondent":"持田河川下水道課長","answer":"１点目の期間ですが、基本的には設置しましたらずっとと言いますか、基本的には夜になればライトアップしていくというように考えております。事業に対して３,０００万円いただいておりまして、また取得に向けて調整していきたいと考えております。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"８,６００万円とか９億という話がありましたけれども、もう少しどういう感じになるのか、もう少し説明を求めました。","respondent":"持田河川下水道課長","answer":"来年については、ほぼ来年１年間で事業は基本的には完成させたいと考えておりますが、来年以降でおおむね８億ぐらいの事業費になってくると思います。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"結構イニシャルコストがかかるものなのだなと思いましたけれども、１度つけたら大体何年ぐらいもつのか尋ねました。","respondent":"持田河川下水道課長","answer":"つけてみないとわからないところもありますが、一般的なこういった電気関係のものにつきましては、１０年で全てが壊れるわけではないと思いますが、１０年が１つの目安、耐用年数だと聞いております。","id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"これは特に京浜運河のところなどに設置する場合、海水の関係でさびとか発生しやすいとか、地域によって耐久の程度は違ってくるものですか。説明を求めました。","respondent":"持田河川下水道課長","answer":"やはり運河のエリアにつきましては、海水の影響は多少はあると考えております。今、設計中ですが、使う製品や電気の接続については、海水がかぶらないようなカバーをするですとか、そういった対応になると考えております。","id":"exchange-023"},{"speaker":"松永副委員長","kind":"質問","question":"新品川橋と品川橋、荏川橋と箇所がばらばらになっているのですけれども、その理由について教えてください。イメージのほうなのですけれども、これを見ていると上のほうもライトアップしたほうがいいのではないかと思うのですが、いかがか尋ねました。","respondent":"持田河川下水道課長","answer":"そして、その上流の荏川橋ということで、この地区では３橋になったところです。横方向の柵が３本ほどあって、ライトアップの効果が出にくいと所管では考えておりまして、ここについては桁のライトアップのみにしたところです。","id":"exchange-024"},{"speaker":"松永副委員長","kind":"質問","question":"この３つの橋についてなのですが、この桁側面と高欄は、先ほどの説明でわかったのですが、ライトアップ箇所は下と横の部分ということで、３橋に関して、何でこういうふうに分けたのかお伺いしたので、それについて伺いたいのですが。","respondent":"持田河川下水道課長","answer":"品川橋はなまこ壁のような高欄のデザインになっていまして、荏川橋のほうも流れが表現されているような、鉄でできた少し変わった高欄です。そういったデザインも生かせるようにということで、その２橋については高欄のライトアップをするというコンセプトで考えております。","id":"exchange-025"},{"speaker":"大沢委員","kind":"質問","question":"旧東海道の品川宿のこのあたり、ライトアップということは、明るくすることが目的なのですか、それとも、周りの暗さを醸し出すのが主眼なのか、どちらに力点を置いてこの事業を進めようとしているのか尋ねました。","respondent":"持田河川下水道課長","answer":"このライトアップは基本的にはある程度暗い中で橋梁等公共物を浮かび上がらせるということでやっております。これは影響がありますので、所管として考えましたのが、今回はこの桁および高欄のライトアップを考えました。","id":"exchange-026"},{"speaker":"大沢委員","kind":"質問","question":"課長の答弁の中で受けた印象なのですけれども、当然ながら土地事情を加味しながら、護岸も含めてやっていただけると。旧東海道周辺は歴史のあるところなので、よろしいかなと思うのですけれども、そこのところはどうお考えか尋ねました。","respondent":"持田河川下水道課長","answer":"ライトアップはやっていきたいと考えていますが、護岸にツタが垂れ下がっているところがあったり、また護岸も場所によって状況が変わります。護岸も明る過ぎるとまたまぶしいということもありますので、照らし方など慎重に検討していきます。","id":"exchange-027"},{"speaker":"松永副委員長","kind":"質問・要望","question":"将来的に進めていっていただきたいと、これは要望で、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-05","title":"本日は防災対策","agenda":"本日は防災対策","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"区民防災組織ということですから、大分そこのところを意識されたのかなと思って、本当に実践的な訓練が行われたなと私自身は思っています。以前議会でも何度か要望しましたけれども、障害者の方の団体に直接お話を伺うことは予定されているのかどうか、まずそこを確認します。","respondent":"古巻防災課長","answer":"障害者団体のご意見の反映ということですけれども、今現在、障害者福祉課と協議いたしまして、今、１３の障害者団体にアンケートを実施しています。このアンケートの結果を踏まえて、内容について運営マニュアルに反映していくことで考えております。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問・要望","question":"やはり直接面と向かってお話を伺わないとわからない部分もあると思いますので、できれば少しお話を伺っていただきたいと要望しておきます。要するに、収容しきれないのではないかという、これは以前から町会関係者の方々からお声が上がっていましたが、それについての見解を伺います。","respondent":"古巻防災課長","answer":"避難スペースは、特に人が生活する空間に関してはかなり制約があることは区としても十分認識しております。３.３平米に２人と今ご紹介いただきましたけれども、いかに工夫していくか、どういった施設利用ができるかは十分考えて対応していきます。","id":"exchange-030"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それから、今回の新しい防災ハンドブックのほうで若干伺います。すごく基礎的というか単純なことなのですが、今までわが家の防災ハンドブックだったのが、しながわ防災ハンドブックに変わった理由について伺います。","respondent":"古巻防災課長","answer":"もう少しさまざまな観点からということもあって、「品川区の防災ハンドブックです」ということが前面に出るようなタイトルに変えたという考え方です。","id":"exchange-031"},{"speaker":"あくつ委員","kind":"質問","question":"もう一つだけ伺います。来年５月中旬から６月中旬にかけての配布ということなのですが、更新に間に合う、これには反映されるということでよろしいか尋ねました。","respondent":"古巻防災課長","answer":"今現在、東京都の正式な公表の時期がまだ出ていないのですけれども、基本的にはそれに間に合わせて更新をかけるというスケジュールで考えております。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"ですから、防災対策というのは、予防となる防災対策が何と言っても中心に座っていなくてはならないことを前提にしつつ伺います。この避難所運営における行政の役割とか責任について、災害救助法との関係でどのように考えておられるか、改めてお伺いします。","respondent":"古巻防災課長","answer":"法的なたてつけではそういったことになると思っていますので、今ご質問いただいた点については、最終的には区が運営に関しては責任を持つというのが区の基本的な考え方だとご理解ください。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ、災害救助法ということで、そちらの責任を果たせるような役割をこれからも努力してほしいと求めました。少し伺いたいのは、具体的にはどういうことを反映していくのでしょうか、そこら辺をもう少し伺いたいと思います。","respondent":"古巻防災課長","answer":"子どもたちへの対応、ペットに関する対応につきましても、基本的なマニュアルの中でガイドライン的な形で例示しています。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"一般質問でもやりましたけれども、まずそこに移動するということと、体を動かすということですね。体を動かしやすいという点でも段ボールベッドの配備ですね、それはこのマニュアルの中にどのようにガイドラインとして入っているのか伺います。","respondent":"古巻防災課長","answer":"仮設トイレ等も備蓄している中で、なるべくトイレが足りなくならないような形での確保を今後も進めていきたいと思います。想定として具体的なところはありませんので、段ボールベッド等については、準備ができた段階で判断していきます。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういうアドバイスもあったわけですから、具体的にそういった視点を改定の中に入れていただきたいと思うのですけれども、いかがでしょうか。１人１人のスペースが明確になるわけですから、なるべくふだんの生活に近づけるという点では、どうしても最低限必要なのかなと思っています。","respondent":"古巻防災課長、曽田災害対策担当部長","answer":"そういう形の協定もあり得るかもしれませんけれども、あくまでも供給していただく側ができる範囲でご協力いただくというのが、基本的な考え方です。優先度を考えながら進めることも重要だと思いますので… 実際にどうなるかと言いますと、発災後、全国を見て、被害を受けていない会社で協定先が作成を開始します。量的にも備蓄倉庫の容積的にも、それも無理ですということでお答え申し上げました。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですので、ぜひ必要数はどれぐらいなのかを定めた上で、それを確保できる方策をこれから整えていただきたいと要望したいと思います。ハンドブックの中に耐震化支援事業などの啓発はあるのでしょうか、ぜひこれは今後の改定で必要なのではないかと思いますが、いかがか尋ねました。","respondent":"古巻防災課長","answer":"今ご質問のあった事項ですけれども、６章の「(1)区の取り組み」の中に、各ご家庭への助成ということで制度一覧を掲載しまして、お問い合わせ先も庁内のしかるべき所管をご紹介する形で、わかりやすく掲載する予定ですので、そのように進めております。","id":"exchange-037"},{"speaker":"横山委員","kind":"提案","question":"具体的にはトイレトレーラーのご提案なのですけれども、区民の防災や避難所のトイレの問題を解決していくことについてのお考えをお聞かせください。こちらはマニュアルのほうにどういった状況によってこうしてくださいという内容は掲載されていくのでしょうか、説明を求めました。","respondent":"古巻防災課長","answer":"さまざまな広域の取り組みにつきましては、いろいろな事例がありますので、研究を進めてまいります。こちらはハンドブックと避難所運営マニュアルのほうに、確認の必要性等についてはきちんと掲載していく予定です。","id":"exchange-038"},{"speaker":"横山委員","kind":"確認","question":"一家に１冊配付されるのですけれども、１人１人が家族で確認できるようなデータであったり、スマホ版やアプリなどの展開はどのように考えているのか。こちらは日本語版だけなのでしょうか、多言語の対応をどのように考えているのか説明を求めました。","respondent":"古巻防災課長","answer":"新しい防災ハンドブックについても、こちらのカタログポケットに掲載して、スマホ等で見られる形を今考えております。カタログポケットは基本的には多言語対応ということで、多言語にも対応して、ひとまずその対応をした上で。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"この間、そういったこともありますので、しっかりと区民の方々が命を守っていけるような情報の届け方をぜひ進めていただけたらと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"あのくみ取り式の仮設トイレは何年前のものでしょうか。おおよそでいいのでお知らせください。","respondent":"古巻防災課長","answer":"正確に何年前とは、多分学校によって違うと思います。ほかの避難所も配備していると聞いておりますので、具体的な数字が言えないのですけれども、それなりの年数がたったものだと思います。","id":"exchange-041"},{"speaker":"筒井委員","kind":"意見","question":"小さいお子さんも来ていましたけれども、今の小さいお子さんは和式トイレの使い方を知らないので、「これ使える？そろそろ古いので、あの組立式仮設トイレの洋式化をぜひお願いしたいのですけれども、その点の見解をお知らせくださいとの意見を述べました。","respondent":"古巻防災課長","answer":"古い仮設トイレは和式がメインだと思います。洋式の台座を準備して、洋式化ができるような対応も進めていますので、順次そこら辺は対応していきます。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"内容はより品川区に特化した内容になるのでしょうか、当たり前かもしれませんけれども、その確認をしたいのでお答えいただきたい。まず区民が読むべき優先順位としては、しながわ防災ハンドブックが最優先になるのでしょうか、その点ご見解をお知らせください。","respondent":"古巻防災課長","answer":"最後の６章以外にも、マンション対策などを踏まえた区の取り組みを記述しておりますので、品川区に特化したものと考えております。そういった使い方をしていただけるとよりいいのかなと考えておりますので、そういった使い方も折に触れてご紹介していきたいと思います。","id":"exchange-043"},{"speaker":"松永副委員長","kind":"質問・要望","question":"先ほど、このしながわ防災ハンドブックの外国語版に関しては、後ほど順次やっていくというお話だったのですけれども、避難所運営マニュアルのほうで、外国人への対応というのがないのですけれども、あればあるでいいのですけれども。","respondent":"古巻防災課長","answer":"避難所運営マニュアルの外国人への対応ですけれども、受け付け等の際の配慮については、記載があります。掲示物とか、そういった基本的な配慮については記載していく形で考えていますので、今ご提案いただいたような中身はできるように進めてまいります。","id":"exchange-044"},{"speaker":"松永副委員長","kind":"質問・要望","question":"ぜひそうした団体の方々との連携も含めて進めていただけたらと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/146532?Template=document&Id=4252#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":30499,"voices":121}},{"id":"h30-20181211-9","meetingId":"h30-cm12","date":"2018年12月11日","dateIso":"2018-12-11","committee":"文教委員会","time":"午前１０時００分～午後 ０時２２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件整理しています。","topics":[{"id":"topic-01","title":"平成３１年度入学希望申請の状況","agenda":"平成３１年度入学希望申請の状況","exchanges":[{"speaker":"鈴木（博）副委員長","kind":"質問","question":"では、この数字をもとに戻してもいいという理由は何か尋ねました。","respondent":"篠田学務課長","answer":"例年の数字が大体３割程度ですので、一応教育委員会としては、３割ぐらいの方が外に出るということで、７割ぐらいの方が利用されるだろうということで、考えているところです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"小学校も中学校も、抽選校が増えているということですけれども、増えている理由をどういうふうに、教育委員会は分析しているのでしょうか。そのあたりを説明を求めました。","respondent":"篠田学務課長","answer":"確かに中学校全般に、受入枠に対して入学予定者数が上回っているところがあるのですが、実際にはどこの学校もきちんと受入ができているところです。そういったものを踏まえた形で、受入枠等の設定や今後の見込みについて出しているものです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"例年３割は私立に行っているという問題ですが、それについて、３割という数字はどういうふうになっているのか。当初の一貫校をつくるときの教育委員会の考え方に対して、現状はどういうふうにしていっているのか、その辺について伺います。","respondent":"篠田学務課長","answer":"過去の推移を見てまいりますと、中学校進学での流出といいますか、そちらを志望される方はここ数年、大体３割程度という形になってあります。そういったものに対してどこまでできているのかというのは、品川の教育の充実とともに判断すべきものではないかと考えているところです。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"しかし私立に３割が流れているという数字に、変化はないというふうに見ていいのですか。その辺について伺います。","respondent":"篠田学務課長","answer":"これは品川区で取り組んできた結果の数字ですので、逆に言いますと何もしなければもっと、私立に流れる数は増えていた可能性も十分考えられる中で、こういった結果が出ているというふうに見ているところです。","id":"exchange-004"},{"speaker":"つる委員","kind":"質問・要望","question":"表現とか捉え方、実際は教育委員会の中でもそういう評価になっているのかということも含めて、感想を改めて伺いたいと思います。１つの中学校、所管内での資料も含めて、あるのかどうか説明を求めました。","respondent":"篠田学務課長、熊谷指導課長","answer":"さまざまな検討資料をつくってきたのですけれども、結局お子さんの流れ等、細かい部分については表には出てきていないところです。一応そういったものは、当然検討の中で土台では使っておりますけれども… ３割が私学等に流れるですけれども、やはり親御さんの考えというのも、特に小学校段階においてはあろうかと思います。９年間の一貫教育をしっかり定着させて、こちらについては引き続き、自信を持ってやってまいりたいと思います。","id":"exchange-005"},{"speaker":"つる委員","kind":"確認","question":"他区のいろいろな方に伺う中でも、私も非常に高く伺っていますし、品川区の公立の教育はいいよねというのはたくさん聞きます。それを表に公表してくださいという話ではないですけれど、しっかりとそうしたものを持ってやっていただいているのかなという、確認でした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問","question":"一方で公立は、生徒を確保するために私学のようにさまざまな手を打つというか、いわゆる広告を打つとか、そういうことはしないわけではないですか。それとも待ちの姿勢でやっていくものなのか、その辺の考え方というのはどういうふうになっているのか、改めて教えてもらいたいと思います。","respondent":"篠田学務課長、熊谷指導課長","answer":"当然区民の方は地元の学校に来ていただくというのが一番、本当に私どもはそのために取り組んでいるということが大前提です。そのための取り組みをかかすことはないということでやっているものです。 平成２９年度、学校満足度が９２.２％ということで、国は７０％ぐらいしかないのです。ただやはりさまざまなお考えや子どもたちのそれぞれの特徴、ご家庭のお考え、また子どもの考えもあろうかと考えています。","id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問","question":"これをなぜ聞いたかというと、いわゆる品川区の教育委員会としても、さまざまやっているわけではないですか。どう考えていらっしゃるのか疑問なので、もちろん想像とは違うけれど、どういうふうに考えているのか説明を求めました。","respondent":"篠田学務課長","answer":"一つは実態としてそういう形で例年、それぞれの学校で想定されるお子さんをこちらで見込みまして、それに合わせて受け入れ枠を設定しています。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問","question":"受入枠６０のところは、７０入れるわけじゃないですか。平成３２年度から選択制も若干見直しが、今かかっている状況ですから、受入枠についてはやってほしいです。","respondent":"篠田学務課長","answer":"それから、２点目の受入枠の関係で、出すこと自体どうなのかというご指摘です。出さないこと自体がどうかというのも検討してみないと何とも言えないのですが、来年度に向けて一度、検討してみたいと考えているところです。","id":"exchange-009"},{"speaker":"渡部委員","kind":"質問","question":"小学校１３校のうち、１０校が全員待機ということで、逆に３校はどういう状況なのか、教えてほしいです。兄弟枠の数のところだけ、説明を求めました。","respondent":"篠田学務課長","answer":"それから京陽小学校ですけれども、８名の方が希望されまして、７名の方が受け入れられて、１名が待機になっている状況です。日野学園は２６名の兄弟枠のご希望がございまして、１９名が受け入れられて、７名が待機されているという状況です。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"やはりそこを活かしていくのが、公立の姿ではないかと常々訴えていますが、そう思っています。抽選校が小学校は２校、３校増えているといった状況の中で、説明を求めました。","respondent":"篠田学務課長","answer":"抽選の人数ですが、合計数が出ていないので、後ほどお答えいたします。それから待機の人数が、小学校は全部で３２６名、中学校も同じく３２６名が待機になってあります。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味で、選択制がなかったときと、始まってからの現在と、事務量がどのぐらい違っているのでしょうか。その辺はいかがか尋ねました。","respondent":"篠田学務課長","answer":"学校選択に関しましては１０月１日から３１日まで受付をするということ、１１月末に抽選をする、そういった作業が発生するものと思います。当然集約されているものもあるということで、極端に事務量が増えているといったことはないと、認識しています。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１１月末に抽選ということで、待機者が３２６名ですか、多く聞いているのですね。費用対効果でどうなのかという意味で、その効果をどう評価しているのか、そこも説明を求めました。","respondent":"篠田学務課長","answer":"毎年それぞれ事業内容等も変わってまいりますし、必要な人員等の配置はされており、適切に事務が進んでいるかと考えているところです。学校選択制自体は、きちんとした形で、学校選択制というのはこれまで続いているものというふうに認識しているものです。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その学校に行ったけれども、実際的にどうだったのかという意味での、詳しいアンケートもとるべきではないか。実際にどうなったのかというところまで、しっかりと検証してほしいと求めましたが、いかがか尋ねました。","respondent":"篠田学務課長","answer":"全体の制度の見直し等もあって、近隣校に限定するといった形で、地域への回帰といったことも含めて検討を進めているところです。新しい制度はまたこれから出てくるものですけれども、そういったことを踏まえて、教育委員会として対応しているというものです。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"よくしてほしいと求めましたし、一生懸命教員の方たちの声を聞いて育てていただければ、いい教員がたくさん増えると思うのです。私は、学校選択制はプラス面よりもマイナスのほうがずっと多いので、本当にやめていただきたい、これは意見を言って終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問","question":"やられていないとすると、選択の仕組みが変わったときの方式はどういうふうになるか、検討する予定があるのでしょうか。何対何とか、そういうことを高校のほうはやっているのですけれど、中学校はそれは特にないのか尋ねました。","respondent":"大関教育総合支援センター長、篠田学務課長","answer":"進路指導に関する後半の２点のお尋ねですが、都立高校と私立高校のような形は、中学校に関しては数字の影響等はございません。ぜひ上がってもらいたい連携の中学校を実際に生で子ども自身が体験してもらうことで… 選択の仕方ですとか、そういった前提条件を踏まえた上で、引き続き検討してきているものです。改めて周知徹底していきながら、学校選択の際、ご家庭でも参考にしていただけるような形での周知に努めてまいりたいと考えているところです。","id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"意見","question":"今お話があったように何とか入れるように、いろいろなご努力をされていると考えていますので、ぜひ今年も去年のように入れるようにお願いします。中学校の教員の方が区立中学、しっかりやられていると思うのですけれど、そのあたりのお話をお願いしますとの意見を述べました。","respondent":"大関教育総合支援センター長","answer":"生活指導主任が毎月実施して、保護者のほうにも可能な範囲で情報共有をしながら、安心して地域の中学校を選んでいただける土壌づくりに励んでおります。","id":"exchange-017"}]},{"id":"topic-02","title":"平成３０年 特別区人事委員会勧告に対する対応","agenda":"平成３０年 特別区人事委員会勧告に対する対応","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"非常に単純なことなのですが、公民較差という、この示されている金額が４桁で、今までこの間は３桁、１００円台、２００円台と低い金額だったのですが、今回９,６７１円と、こんなに数字が違っているというのは、なぜこんなふうに違いが出たかというところを教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"月例給の公民較差の要因ですけれども、人事委員会によれば、平成３０年４月に実施しました行政系人事・給与制度の改正に伴い、職員構成に変化があったことによる影響というふうに聞いております。","id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"職員構成の変化というか、具体的にわからないのですけれども。〔「総務委員会の方で行っているのですから」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"そうなのだけれど、ここだって具体的に示されているから、当然ご存じのことと思いますので、教えてください。わかる範囲で結構です。","respondent":"熊谷指導課長","answer":"こちらにつきましては、本日総務委員会でご説明するところですけれども、実際に今申し上げたとおり、こちらの行政系人事・給与制度の改正で、職員構成に変化があったことから、給料表がそれについて偏りが見られたというところしか、私のほうではご説明できないところです。","id":"exchange-020"}]},{"id":"topic-03","title":"大崎図書館分館の開館","agenda":"大崎図書館分館の開館","exchanges":[{"speaker":"南委員","kind":"質問","question":"蔵書数が示されているのですけれども、移転をしていった大崎図書館と合算してみたほうがいいのか、よくわからないのですけれど、この４万点という規模は、品川区内１０カ所ある図書館のどのぐらいか伺います。","respondent":"横山品川図書館長","answer":"分館の資料、４万点の予定ですが、区内の図書館でいいますと、源氏前図書館が３万８,０００点、大井図書館が４万６,０００点、二葉図書館２万８,０００点ですので、小規模な地区館と同等の蔵書数の予定です。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"裏面にレイアウト図が示されていて、ちょっと小さくてあまりよくわからないので、１点だけ伺いたいです。２つのパートに分かれて設定されているということはわかったのですけれども、入り口が大体どこまであって、右側のほうは児童の図書か尋ねました。","respondent":"横山品川図書館長","answer":"入り口から左側一帯が一般の書架になりまして、ここに一般図書も、児童図書も、絵本のスペース等もあります。その右側にトイレスペースと廊下がありまして、突き当たりが多目的室で、こちらで行事等を行う予定になっております。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この図の中で、前は読み聞かせのとてもすてきなお部屋があったのですけれども、その読み聞かせはどういうところで行われるのか、教えていただきたい。座って読む場所というか、席はどのぐらい確保されているのか、その辺も説明を求めました。","respondent":"横山品川図書館長","answer":"読み聞かせのスペースですが、こちらの多目的室のほうで行う予定になっております。それと、脇に今、机といすを設定しているのですが、まだ確定ができない状況なので、面積を調整しながら、できるだけ席を確保しようとしています。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここは地下ですよね、半地下ですか。出入りがあるかと思うのですが、どのくらいの人数をキャパシティとして受け入れられるのか、その辺の想定があったら説明を求めました。","respondent":"横山品川図書館長","answer":"ロビーの１カ所があるのですが、そういう意味では１階の平面に面しておりますので、窓からも出られるような形で対応しようと思います。収容人数として席でご案内はできない、出入りの激しいところなので、今のところは設定しておりません。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ充実した読み聞かせをしてほしいと求めましたが、読み聞かせも含めて行事はどのぐらいの間隔でやられるのか、教えてください。特に読み聞かせのところを。","respondent":"横山品川図書館長","answer":"読み聞かせにつきましては、ほかの図書館と同様に毎週１回を予定しております。そのほかに、今年度実施しております高齢者支援事業についても、こちらで拡大していこうと考えています。","id":"exchange-025"},{"speaker":"つる委員","kind":"確認","question":"書架があるほうは、上がメディアセンターとかになると思うので、そんなに影響はないのかなと。位置的にはステージ直下になるのですか、そういう意味では大丈夫か確認だけ、お願いします。","respondent":"横山品川図書館長","answer":"多目的室やトイレ、事務室のスペースをそちらのほうにあてる形で、工夫しています。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問","question":"細かい部分ですけれど、この図書館部分にＡＥＤは設置されるのでしょうか。もしされるのであれば、どのあたりに設置しますか。","respondent":"横山品川図書館長","answer":"ＡＥＤについては各図書館に設置していくところですので、分館についても設置していきたいと考えています。場所については、まだ引き渡し前ですので、そちらを確認してから設置場所を確定していきたいと考えています。","id":"exchange-027"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。収容人数は決められていないという話だったのですが、そこを改めて、何の収容人数が決められていないのか説明を求めました。","respondent":"横山品川図書館長","answer":"１日そちらに在館される方は少なくて、定員はここまでなので入ってはいけませんということはできませんし、これ以上が収容人数ですというご案内の仕方はしてないです。","id":"exchange-028"},{"speaker":"石田（し）委員","kind":"質問","question":"その施設のキャパシティに対して、どれだけの人が入れるかというのは、ある程度決まっているものですよね。一定の収容人数というのは、設定しておかないといけないのではないのかと思うのですが、その辺もう一度説明を求めました。","respondent":"横山品川図書館長","answer":"法令上で、例えば消防法で１００人とか１,０００人とか、大まかな規定の制限はあると思うのですけれども、図書館を建てるとき、何人予定でというような決まり自体はない形になります。","id":"exchange-029"},{"speaker":"石田（し）委員","kind":"質問","question":"例えば２８８人ですとかいうのではなくて、３００人ですというものなのかあれですが、収容人数というのはあるのではないか。施設はどこでもそうだと思うので、それを説明を求めました。","respondent":"横山品川図書館長","answer":"そのような意味ですと、席で各図書館をご案内しているような形で、非常に出入りの人数よりは少ない形ですが……。","id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"図書館という施設そのものが２方向避難を基準として捉えていないのかどうか、その点と、左側のほうは１階の設定になっていると。もしもの場合にはどうするのかなと、そのあたりの避難も含めて、２方向避難との関係も含めて説明を求めました。","respondent":"横山品川図書館長","answer":"多目的室の前も窓で、外に出られる状態、多目的室の前は駐車場になりますので、段差としてはそんなにない状態になっています。２方向避難については、出入り口としては１カ所しか設けていないのですが、建築されていると聞いております。","id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"２方向避難との関係で、今わからなかったのですが、消防法でクリアされているということはわかったのですけれども、２方向避難が設定されていなくてもいいという、そういう理解でいいのか尋ねました。","respondent":"横山品川図書館長","answer":"申しわけございません。２方向避難について、これでいいというような確認のところまで把握しておりませんので、後日確認します。","id":"exchange-032"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"南委員","kind":"質問","question":"最近は４月当初ぐらいから午睡をしなくなる保育体制になっていると聞いているのですけれども、そのことの効果というところを伺いたいと思います。４歳児の当初からではないと思うのですけれど、その点についての見解を伺いたいと、伺いたいと思います。","respondent":"佐藤保育課長","answer":"お子さんの体調や状況によって、午睡をしない場合もあるかもしれませんが、それは個別に対応しています。基本は５歳児からというふうに考えております。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"その１日過ごせる体力という点で、どういうふうに捉えてやってくださっているか、伺いたいです。先ほどの説明ではなかったので、教えてほしいと求めました。","respondent":"佐藤保育課長","answer":"それはもちろん、そういうお子さんに関しましては個別に４歳児の部屋等で保育士が付き添うなどして、なれていくような工夫は当然しております。","id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"保育園での保育されている状況もあるわけですから、過去のいろいろな経験、きちんとした考え方のもとでの指導が必要なのではないかと思います。もしそういう状況があれば慎んでいくべきではないかと思いますので、そのことは意見として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"この資料は、どういう方が携わってつくってくださったのかというのが一つ。研修の中身を作成するのは、どういった方が携わっているのか、その２点を説明を求めました。","respondent":"佐藤保育課長","answer":"１点目の、本日ご説明しております所管事務調査の資料作成者ですけれど、その園長に基本となる資料をほとんどつくっていただいたというところです。２点目のご質問にもつながりますけれど、ＯＢの園長も５人ほどいらっしゃいますけれど、さまざまな研修を実施しているところです。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区がどの程度まで、これから広げていかなければいけないと思っているのですけれども、その辺のお考えをお聞かせいただきたい。保育の現場のことを知っていただくという意味で、保育課の職員の方の研修というのはされているのか、その辺も説明を求めました。","respondent":"佐藤保育課長","answer":"先ほどご説明したように各事業所や園の方針で保育を行っておりますし、品川区として力を入れている特別支援であったり、保護者支援等。１日保育士体験というのを保護者の方向けにやっておりますが、そちらに保育課の職員も今年から参加するようにしております。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり人員的な配慮というのはすごく大事であると思っているのですが、その辺、現場から声は出ていないのかどうか。その辺もプラスアルファしていくことで、より充実した研修ができるかと思うのですが、その辺の考えを説明を求めました。","respondent":"佐藤保育課長","answer":"本課に６人の園長ＯＢがいますので、現場で若い保育士の指導をするという形式に、ある程度シフトしています。現場に訪ねていって、今年度は研修の再構築をしておりますから、その中でまたさまざまな検討をしていきたいと考えています。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"保育園だけではないと思います、ほかの職場でもそうだと思いますが、ぜひ検討してほしいと求めました。課長だけの問題ではないので、部長にもしっかり聞いていただいたと思いますので、ぜひ検討の材料にしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"鈴木（博）副委員長","kind":"提案","question":"一通り救急対応を保育士ができるので、まとめてやったらいいのではないかと、これは提案します。けがをした、そういうときの初期対応を保育士がある程度できるようにするトレーニングというのは必要ですから、その点はいかがか尋ねました。","respondent":"佐藤保育課長","answer":"事故対応の研修もやるべきというところですが、さまざまな事故等の対応も細かくするということで、大体２１項目ぐらい対応が入っております。委員ご指摘の事故の関係の対応についても、十分保育士のほうで学ぶ機会を設ける予定です。","id":"exchange-040"},{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"親との関係もすごく大事なので、コミュニケーション能力というのは非常に大切です。特に今はいろいろな親の方がいらっしゃるので、そういう研修も十分やるように、これは要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問","question":"受けていないとしたら、異動で今後、保育園に行ったとき、どうなるのかというところを伺いたいです。コミュニケーションのほうですが、現在は保護者に対する対応についての研修は、されているのか尋ねました。","respondent":"佐藤保育課長","answer":"２点目の保護者支援に関しましては、保護者ニーズが多様化しているという理解を進める関係で、講義等の研修を実施しております。クラスだよりや連絡帳等を利用した、わかりやすい情報伝達などの実技の研修を加える予定で、考えております。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問","question":"児童センターにはいらっしゃらないのでしたか。いらっしゃったら、保育園のお仕事と違うので、その後についてどうなのか説明を求めました。","respondent":"高山子ども育成課長","answer":"児童センターサイドとしましては、独自の研修プログラムを子ども育成課のほうで企画しておりまして、そちらのほうを受講していただくことになります。","id":"exchange-043"},{"speaker":"石田（し）委員","kind":"意見","question":"１点だけ。私はほぼほぼ保育士の、いわゆる働き方がどうなのかがイコール保育の質に見えるのですけれど、区としてどういうふうに考えられているのかとの意見を述べました。","respondent":"佐藤保育課長","answer":"保育の質というのは３つの柱があると考えております。この３点と考えておりまして、どれもバランスよく進めていきたいと考えているところですが、まとめさせていただいているところです。","id":"exchange-044"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"突然の報告だったので、受けとめられないのですが、これは７月１９日に都と合同検査に入ったということですが、きっかけは一体何でこの合同検査に入ったのか、保育士が適正に配置されていないというのはどこの部分に適正に配置されていなかったのか、まず２点お伺いします。","respondent":"佐藤保育課長","answer":"それで都と相談をした結果、合同検査が必要ではないかということで、７月１９日に行われたものです。７月１９日に実際に指導検査に行ったところ、朝の保育士の体制が１名不足しているというのを確認しました。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"朝の配置というのは、早番の保育の体制が、多分何カ所かでやられているところに、正規の保育士がいなかったということですか。非正規の資格のない人がやっていたということなのか、それも何人必要なところに何人しか配置されていなかったなど、もう少し具体的に説明を求めました。","respondent":"大澤保育支援課長","answer":"早番は７時半からになりますけれども、本来は７時半から２名、保育士がいなければいけないところを、１名しか配置していなくて、具体的には８時から出勤する職員が次のシフトになりますので、７時半から８時の３０分間、１名で対応していたです。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"朝の保育のところは、本当に１名しかいなかったということは、ほかに非正規の人がいたのですか。これは大問題だと思うのですが、そこのところはどう判断をされているのか尋ねました。","respondent":"大澤保育支援課長","answer":"保育士の急な退職等により、体制が整えられずに平成３０年４月から１人で対応していたということでございました。私どもも大変、これは重要な案件だと考えております。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"これは、ほかでもあり得るというか、今、職員の出入りが結構あったりするので、こういうのは相談するものではないのですか。この辺の防止策というか、この４６０万円というのは単純にその間の職員に対しての給与関係なのかどうか、そこも説明を求めました。","respondent":"大澤保育支援課長","answer":"防止策というのは、保育士の数については毎月必ずチェックは入れております。保育士が規定どおりに配置されていることを前提に、加配している保育士に対する加算部分を、４月から７月分を返していただくという考え方です。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問","question":"今、毎月保育士の数は把握していますということにおいて、報告に不正があったのですか。報告上はちゃんとされていたのか数字がごまかされていたのかどちらか尋ねました。","respondent":"大澤保育支援課長","answer":"基準の保育士の配置としては足りています。ただ、シフト上、早番の方を２名入れていなかったという考え方になります。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そうやって少しずつ、自分の中で緩和していって、ここはしようがないのだと言っていくというのは、とても怖いなと思っています。チェックできる方策を考えていただきたいし、たかだか３０分といっても、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"南委員","kind":"質問","question":"２０分とか１５分とか、朝は出勤すること自体が大変ですから、そういういろいろなシフトの形態があると思うのです。２人の配置をしないと、その点についてはどういうふうに説明があり、どうなっていたのか伺います。","respondent":"大澤保育支援課長、吉田保育施設調整担当課長","answer":"今回の指摘につきましてあざみ会は、もちろん反省しておりまして、８月からすぐに非常勤の方を雇ってシフトをきちんと整える対応をしております。１４万円というのは、病後児保育のほうの保育士が不足していた１０日間ですので… ４名受け付けた際は、本来ですと保育士は２名必要です。その４名を受け入れたにもかかわらず、保育士が１名しかいなかった、この状態が１０日あったです。","id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"そういう方のご意見も伺っておきたいと思いますけれども、私はこれ、非常に重く受けとめました。品川区としての見解と、どういうふうに捉えているのか、伺っておきたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"今回定員４名の際に、保育士の確保ができていなかったことについては、大変残念なことだと考えています。委託事業者との契約の仕様の変更、より正しいやり方でやれるよう、対応してまいります。","id":"exchange-052"},{"speaker":"南委員","kind":"意見","question":"１週間とか、そこをどういうふうに保育の手当をしようかというところなので、一定程度期間も予想できると思います。気持ち的には、いい、悪い別にして……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"南委員","kind":"質問","question":"４人というふうになって、そういうことも含めて、やはり考えていかなくてはいけないと思うのです。その点について、見解があれば伺いたいし、なければ強力な意見として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"渡部委員","kind":"確認","question":"端的に、７月にそういうことがあって、８月から大丈夫ということで、そこはいいと思います。品川区内のほかの保育園はどうなのだろうと、当然聞き取りなり何なりなさっていただいたと思いますけれど、問題はないという確認だけさせてください。","respondent":"大澤保育支援課長","answer":"先ほど申し上げましたように、保育士の数、またシフト表は保育支援課でチェックしておりますが、今回のことを受けまして、９月１１日の私立保育園長会で、職員配置のルールにつきまして、改めて確認しています。","id":"exchange-055"},{"speaker":"高橋（し）委員","kind":"質問","question":"もう１つは、どこからのお金をどこに返還するのでしょうか。４６０万円で４カ月なので、２５日で割ると１日４万円ぐらいか尋ねました。","respondent":"大澤保育支援課長","answer":"８月から改善されていますので、４月から７月分の返還ということで、今回は考えております。４６０万円の金額ですけれども、運営費の一部になりますので、具体的には今後の運営費からの相殺という形をとろうというふうに考えております。","id":"exchange-056"},{"speaker":"高橋（し）委員","kind":"質問","question":"運営費という大枠の中で、というお話ですね。その加配の分の４６０万円というのは、どういう計算で出たのか、説明を求めました。","respondent":"大澤保育支援課長","answer":"保育士が規定どおり配置されていることがまずあって、その上に加配をした場合の加算部分ですので、具体的には主任保育士加算、３歳児配置改善加算、特別支援保育加算の部分を返還していただくという計算になっております。","id":"exchange-057"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、ほかの委員からもありましたけれども、非常に大変なことであったわけなので、今後このようなことが起きないようにお願いいたします。それも東京都からの話で発覚したということですので、ぜひその辺をきちんと、先ほどの改善策をしっかりやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/971992?Template=document&Id=4960#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":42041,"voices":154}},{"id":"h30-20181211-5","meetingId":"h30-cm12","date":"2018年12月11日","dateIso":"2018-12-11","committee":"総務委員会","time":"午前１０時００分～午後 ０時２４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１２ページの財務４表増減額内訳が一番整理されていると思うので、ここから伺いたいと思います。指定管理者制度も含めて運営委託が進んでおりますけれども、そういうものは、ここで言うと物件費に当たるということなのか尋ねました。","respondent":"品川財政課長","answer":"基本的に、委託関係につきましては、この表の中では物件費という形で出しています。反対に人件費は、俗に言う区職員の給与、それから退職金等になるという形になってあります。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"実際には区がやっていたものを委託という形で物件費に置きかえたという実態があるかと思うのですけれども、いかがですか。実際の姿がわかりにくく実態との乖離が生まれてしまうのではないかと思うのですけれども、その点についてはどのようにお考えか尋ねました。","respondent":"品川財政課長","answer":"この表の中でということになると、人件費が物件費に流れているのかどうかというところは、はっきりと示すことができません。要するに、前年度の退職人数等、なかなかこの表だけでは一概にいろんなことが示せるものではないと思っています。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これは、一般的に民間の会社ですと、６ページの普通会計の貸借対照表を見れば、大まかなことはわかると思うのです。公表時期としてパンフレットは、「同時期」と資料に書いてありますけれど、どの程度の内容を掲載するお考えかお聞きしたいと思います。","respondent":"品川財政課長","answer":"パンフレットは、多分もう皆さんご覧になっているかと思うのですけど、「品川区の経営状況」ということで、このレベルです。いろいろ民間の貸借対照表とは、いろいろ疑問点は出ると思いますけれども、行政の財務諸表のあらわし方にのっとって現在やっております。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"それはどうなっていくのでしょうかというあたりはお答えいただいたのですけど、その辺をどういうふうな扱いにしていくのか、ぜひ伺いたいのと。その辺が、今後の公表の仕方でどういうふうにしていくのか、教えていただきたいです。","respondent":"品川財政課長","answer":"平成３０年度の決算から財務諸表を新しくつくるのですけれども、より民間のやり方に近い方法で今後やっていくというような方向で、現在のところ進めているという状況です。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"パンフレットもそのとき検討するということでよろしいか尋ねました。","respondent":"品川財政課長","answer":"財務４表関係で、貸借対照表の部分といったところは、少し変更点が出てくるかと思います。詳細については、今現在、検討しているところですので、少しお待ちいただければと思います。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり減価償却費の扱いというのはどういうふうにしていくのかということを、きちんと私たちも理解できるような形にしていっていただきたいです。区民の方で財政のことがすごくよくわかる方もたくさんいらっしゃると思うので、そういう公表の仕方も、その辺は何かお考えがあれば説明を求めました。","respondent":"品川財政課長","answer":"表記の方法については、今後どうしていくか、検討していくということになると思います。いろいろと新しい方式を用いた財務諸表を作っているところもありますので、そういうところも参考にして考えていきたいと思ってあります。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ検討していただきたいです。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"学校など」とありますが、これは、つくったときのコストがこのまま資産として残っているということなのでしょうか。説明を求めました。","respondent":"品川財政課長","answer":"次に、「公共資産」のところです。今、そういったところで固定資産という考え方とちょっとずれがあるというところが、今のやり方の問題点です。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"公共資産の中の土地の評価は、ここに出す金額は、路線価をもとにして表記しているという解釈でよろしいのでしょうか。それとも別のやり方で算出した資産額をここに載せているのか尋ねました。","respondent":"品川財政課長","answer":"ですので、本来は固定資産という形も出したいというところがあるのですが、それは今度の財務諸表で多分なってくるのではないかと考えています。そこが、先ほど申しました検討次第ということになります。","id":"exchange-009"},{"speaker":"須貝委員","kind":"意見","question":"それに流動資産をたしあわせる総額１,０００億円を超えるというのは、すごい健全財政というのか、すごいと評価されるというのか。一応感想だけ述べしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]},{"id":"topic-02","title":"特別区人事委員会勧告に対する特別区長会の対応","agenda":"特別区人事委員会勧告に対する特別区長会の対応","exchanges":[{"speaker":"いながわ委員","kind":"意見","question":"特別区人事委員会がどういう形でやるかわからないですが、そういう想定はせず、今回の引き下げに関しては従わないということなのか。ダブルパンチとなるのではないかと、すごく危惧するところなのですけれど、実際にどこまでお考えになっているのかとの意見を述べました。","respondent":"黒田人事課長","answer":"今回の一過性のゆがみというのが、職層を８層制から６層制に変更したことにより職員の構成が変わったというところが大きな要因となっています。特例選考というのを実施するということで、一定程度、職員の構成について２３区全体で取り組んでいくというような内容もあります。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"では毎回、何も人事委員会の意見を聞く必要もないし、区は区の独自の考え方でやればいいという制度に見られてしまうのではないですか。その辺についてご見解を説明を求めました。","respondent":"黒田人事課長","answer":"先ほど資料でもご説明があったように、人事委員会勧告については尊重するのが基本だと。８層制から６層制に変えた中で、情勢適応の原則から考えてもどうなのかというところで、区長会として異例の対応として今回見送ったというものです。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"決して２３区の職員の皆さんの給与が安いわけではなくて、各自治体がそういうふうな方向に持っていくということに関しては非常に違和感を覚えます。人事委員会からこういうふうに勧告されるわけですから、やはりその辺に疑問を非常に感じますので、それだけはちょっと指摘しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"特別区長会はそこをどう考えているのか伺いたいと思います。この点も伺いたいと思います。","respondent":"黒田人事課長","answer":"１点目の条例改正につきましては、特別給の改正を実施いたしませんで、現在の条例の中に定めた給与でいくということになります。５０代後半の職員が多いですので、職員構成自体が変わっていくということの中では解消されるものと考えていますが、現時点ではひずみがあるです。","id":"exchange-014"}]},{"id":"topic-03","title":"上場株式等に係る配当所得等に関する住民税の税額再算定","agenda":"上場株式等に係る配当所得等に関する住民税の税額再算定","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"２３区全体を見て、こういうことが、あちらこちらの区で間違った解釈をし税額の再算定になっているのか。できれば、増額分の一番多い人に幾らぐらいの増額になって、減額の方でどれぐらいが減額になるのかというのがわかれば説明を求めました。","respondent":"伊東税務課長","answer":"それと、大体の額ですけれども、追徴の場合で最高で８万円余というところと、減額での最高で１２万３,０００円というような形です。少ないところでは数百円からという形になってあります。","id":"exchange-015"},{"speaker":"いながわ委員","kind":"質問・要望","question":"中身を確認していただけるような形で、８０名程度ということなので、しっかり手元に届くようにしてほしいと求めました。急に来て８万円、１２万円が戻ってくるという人はうれしいのかもしれないですし、そういう部分も含めてしっかりやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"は具体的な手続の中でもそういうことが必要ではないかと思うのですけれども、その点を伺いたいと思います。その点についても伺いたいと思います。","respondent":"伊東税務課長","answer":"そのとき、自治体まで、正確に説明が伝わり切れていなかったというところはあるのかと思っているところです。これは今年の初めに、ある区から話が出たのが、たしか９月ぐらいだったかと思います。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"今年の９月に、２３区の例えば課長会などで共有しながら対応を考えていたということになるのか、伺いたいと思います。いわゆる全国的なことになるのか尋ねました。","respondent":"伊東税務課長","answer":"それが過去までさかのぼってやらなくてはいけないのかというところをいろいろと検討してというか、今の時期になったということだと思います。それが全国レベルなのかというところまでは、記録は持っていないので、多々あるのではないかと、感覚的ですが思っております。","id":"exchange-018"},{"speaker":"中塚委員","kind":"意見","question":"こういったことがないよう、今後とも点検をよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"税務関係ですから、これは平成１５年に創設されたということですから、多くの人数の方に迷惑をかけているのですよね。本当に一度ぐらい、国に謝罪を求めますというような意見書を出していいのではないかと思いますけれど、いかがか尋ねました。","respondent":"伊東税務課長","answer":"平成１５年の改正で、なぜ我々がそういう解釈になったのかというところについても説明を求めたところですが、国は条文に書いてあるとおりだと。我々もそのときの説明会の資料等を引っ張り出してみたのですけれど、いや、条文を読めばそのとおりでしょうという一点張りです。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"１つだけ、かなうのであれば、私はやはり、区が悪かったというようなことは書かないで、区民に報告してほしいです。やはりそもそもどこが決めたんだという話ですから、私はちょっとそういうふうにしていただきたいという意見を言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"企業に向けて、品川区は何かやっているのですか。品川区の企業も大きな企業がありますので、そういうところにはどういう周知というかをしているのか、説明を求めました。","respondent":"島袋人権啓発課長","answer":"平成２７年度に関しましても若干低目に出ているものがありますが、対応してくれているという回答がございまして、すぐに警察対応になっていく。市民科の中で確実に実施しているところですし、今年の７月ですが、２名の参加をいただいたという経緯があります。","id":"exchange-022"},{"speaker":"いながわ委員","kind":"質問","question":"数値は出ているわけですから、東京都に聞いたらそう言っていますというのはちょっと違うのではないかと思うので、しっかりやってくださいということ。そういう時期なわけですから、いろいろな組織・団体もあるわけですから、逆にそういったところの人事課か何かにいろいろなものを送付して。","respondent":"島袋人権啓発課長","answer":"企業に関してなのですけれども、昨年の１１月に初めて企業に対しまして、アンケートでＬＧＢＴの方に対する対応等をお聞きしています。","id":"exchange-023"},{"speaker":"いながわ委員","kind":"質問・要望","question":"それで、来た企業は、品川区は全部チェックするぐらいやらないと、人権啓発というのは全然前に進まないと思うのです。そういうのをしっかりと、各企業とも連携をとって進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"暴力を肯定していたり、さまざまあるかと思うのですけれども、区の認識を伺いたいと思います。私も含めて自分自身をそのとき点検できるような形になっていくと、一歩ずつまた進んでいくのかと思うのですけれども、いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"いろいろと検討していくということで、今、進めているところです。あるいは重要なケースにつながりましたら、きちんと対応していただけるように努めるものが責務だと考えておるところです。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"暴力というのは感度の問題や程度の問題ではなく、個人の尊厳を力で奪うもの、踏みにじるものであって、相手がどう思うかというところだと思うのです。高齢者、障害者、配偶者への暴力やパートナーによる暴力とは何かを改めて伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"やはり、相手がどう思うかということが非常に重要だと思います。きちんと実施すると言うと変なのですけれども、品川区で申しますと人権尊重都市品川宣言ですが、この宣言文を。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"性的マイノリティについて若干伺いたいのですけれども、資料にある３ページの一番下に、区もこの立場と同じなのか。区もこの東京都の条例の性自認・性的指向を理由とする不当な差別をしてはならないという立場かどうか、ご説明ほしいと求めました。","respondent":"島袋人権啓発課長","answer":"オリンピックに関しましては、この１０月にまさに条例を改正いたしまして、東京都がこのような条例を策定いたしましたという文言も入ってあります。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は、こだわっているのは、性自認および性的指向を理由とする不当な差別をしてはいけないとしているのと同じ認識か改めて伺いたいと思います。品川区としては、この性自認および性的指向を理由とする不当な差別をしてはいけないと思っているのかどうか、確認させてほしいと求めました。","respondent":"島袋人権啓発課長","answer":"実は、この問題について関心と理解を深めていくことが必要ということで、やはり啓発活動等を含めながら進めてまいりたいと考えているところです。性自認を理由とする偏見や差別をなくそうということに関しましても、同様に進めてまいりたいと考えているところです。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"マジョリティに対しても、要するに一人ひとりの問題なのだというメッセージが必要だと私は思うのですけれども、いかがでしょうか。求めてまいりましたが、同性パートナーシップ制度についても前向きに議論を進めていただけたらと思うのですけれども、あわせていかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"この実現のために、「マイセルフ品川プラン～誰もが自分らしく～」をもう一歩、進める段階で検討してまいりたいと考えているところです。スポーツと暴力というところで、部活動におきましては、運動部活動指導者講習会等などで体罰について触れていると認識しております。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば聞き方が変わったり、「恋人はいないですか」という聞き方に変えてみたり、さまざま接し方が変わってくると思うのです。ぜひ、アンケート調査の実施や同性パートナーシップ制度についても前向きな検討が進められたらと思うのですけれども、改めていかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"いつも答弁させていただいているところなのですが、実際にそれを書くことによって、人に知られてしまう。やはり性的マイノリティの方のこと等の設問を検討しておりますので、その辺は今後の課題として検討を進めてまいりたいと思っているところです。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問・要望","question":"片隅でもいいですから、ここへ行かれたらどうですかとか、そのような対応をこれからもやっていただきたいと私は思います。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"どういうときにどういうふうに、誰の呼びかけでどういうふうに開かれているのかとか、その辺の情報があれば伺いたいと思います。全庁的な仕組みだと思いますので、今お答えできる範囲で結構ですので、お答えいただきたいのですけれど。","respondent":"島袋人権啓発課長","answer":"確かに、別紙１のしながわ見守りホットラインの４つの番号ですが、こちらは区役所の中の各対応していただく課につながります。一方で、本当に命に危険がある場合は、こちらの対応を待たずに警察にも一報をということをさせていただいているという流れになっておるところです。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"誰によってどういうふうに処理されていて、それは緊急ですから１１０番してくださいと、そこが言うのか。その辺が、どういうふうに考えられているのかということを伺いたいのと、それからＤＶの所管課は、人権啓発課か尋ねました。","respondent":"島袋人権啓発課長","answer":"それと同時に、宿直職員は、１１０番対応をした後、所管課長にも連絡を入れて、そのような事例があったことを報告していると聞いております。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"まずは本当に大事なことだと思うのですけれども、なかなか２４時間、できる限りきちんと命を守るということをやっていってほしいと求めました。それぞれの所管でやるべきことは当然として、人権啓発というところから、その辺についてももし見解をいただければと思っています。","respondent":"島袋人権啓発課長","answer":"ですので、先ほども申し上げましたけれども、それを若いときから知っていただくような状況をつくってまいりたいと考えているところです。その後、まずは各ケース対応というところでしっかりと対応していただき、よい結果をつくっていただくということを思っているところです。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"引き続きそういうものについては講座を企画していただければということでお願いしたいと思います。これは要望です。","respondent":"島袋人権啓発課長","answer":"ネグレクトに関しての歯科医師会の件ですけれども、虐待防止ネットワーク協議会の中に歯科医師会は入っていらっしゃいます。第５８号からは、今後も何かあったら連携したいというお声をいただいておりますので、進めてまいりたいと考えているところです。","id":"exchange-035"}]},{"id":"topic-05","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"１２月６日の本多議員からの「区政運営について」というご質問の項目の中で、今、試行中であるというようなご答弁があったように理解しております。試行中ということがどういう形で試行されていて、今、もしわかれば今後の方向性ということをどのようにお考えか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"平成２８年度に１回、社会保険労務士との検討の中で、またそこから平成２８・２９・３０年度において試行という形で続けているといった状況です。今後の進め方、どういう形にするかで検討中ですけれども、そういったことをやりながら評価していきたいと。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"(2)の事業・運営状況調査なのですけれど、財務状況の確認というところに、公認会計士が入ってくると理解していいのでしょうかというのが１つ。財務状況は公認会計士だと思うのですが、利用者へのアンケートの内容などはどこで検討されて、どういうふうに実施されたのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"では評価の仕方について、例えば面接の時間を少し変えてみるとか、そういったところの変更をやっていったというのが途中の経過です。その事業者のほうにも公認会計士がいらっしゃいますので、今回はそういう事業者にもお願いしながら進めていった状況です。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"今のお話を伺っていると、今、検討中というような理解でよろしいのでしょうか。全施設を対象にしていただきたいというのと、結果についてぜひ公表していただきたいと希望いたしますが、その辺についてコメントはいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"例えば何年かに１回、例えば５年という１つのサイクルがありますので、そういったことも含めて検討しています。それに伴いまして、それをどういった形で、議会にお知らせできるかというのも、あわせて検討していくといった状況です。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"こういう指定管理者はすごくやはりいいよねという評価にもつながるわけですから、ぜひその方向で進めてほしいと求めました。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"多岐にわたって伺いたいと思いますが、資料に、どのような共通項目でチェックしているのか伺いたいと思います。さまざま労働環境といっても把握の仕方があるかと思うのですけれども、どこを共通項目としてチェックされているのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"労働環境チェックのところですけれども、今ご指摘があったところ、いわゆる一般的に言われる労働の環境、休暇であったり給与の面であったり福利厚生であったり、法令に照らし合わせながらということで、この部分については、ほぼ全てチェック内容に入るというものです。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"指定管理者の状況がどうなっているのかというのは大事なポイントだと考えていますし、法人によってはさまざま努力もされていると伺っております。しっかり議会に資料を示してほしいと求めましたが、その労働条件を把握するという立場なのか、伺いたいと思います。","respondent":"柏原企画調整課長","answer":"検討しているですので、中身についてはもう少々お時間をいただきながら、お示しできる形に持っていきたいと思ってあります。我々は施設管理、請け負っている事業者の状態であったり、１点だけを集中してやるということではないというところはご理解いただければと思います。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど伺ったのは、ぜひ把握していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"繰り返しの部分はあるのですけれども、公の施設としてきちんと運営、事業がなされているか、人云々ということにフォーカスするのではなく、事業を運営するためにきちんとした状態にあるかどうかというのを確認するという趣旨でやってきているものです。","id":"exchange-042"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"たしかにホームページ上も任意になっているのです。ただ、任意であるけれども、その表現というところはまた今後しっかりとご検討をほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/147246?Template=document&Id=2126#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":41537,"voices":123}},{"id":"h30-20181212-14","meetingId":"h30-cm12","date":"2018年12月12日","dateIso":"2018-12-12","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時４２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"改めまして、新公会計制度に関することのうち、財務諸表等の活用","agenda":"改めまして、新公会計制度に関することのうち、財務諸表等の活用","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"１ページ目に、要は企業会計で用いられている考え方の複式簿記・発生主義会計であるのかどうか、確認をお願いしたいと思います。複式簿記・発生主義とは、新公会計制度においては何を意味するのか、簡単に説明していただけないかと思います。","respondent":"齋藤会計管理者","answer":"先ほどちょっと話をさせてもらった、１００万円の車を買うと、１０年後に廃車するときまで１００万円の価値があるものという形しかできません。例えば庁舎であれば５０年、庁舎以外の建物であれば４０年、１円になるまで物の価値が下がっていくという計算で物を考えます。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"あったと思うのですけれども、減価償却費を計算に入れる必要があるのかなというか、従来どおりのやり方で事足りるのではないかと。なぜあえて発生主義や減価償却という考え方を導入するのか、伺いたいと思います。","respondent":"齋藤会計管理者","answer":"何が言いたいかというと、インフラ資産というものは５０年、６０年と使うので、今の住民の方ではなくて、将来世代にも負担してもらおうという考え方。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"なぜセグメント分析というのが受益者負担の適正化、こういったマクロ的視点を導入することで徴収体制の強化につながっていくのかも伺いたい。最後に、ＰＰＰ／ＰＦＩでの活用も進んでいくと書いてありますけれども、なぜ進んでいくのか、それぞれ簡潔にお伺いしたいと思います。","respondent":"齋藤会計管理者","answer":"５つあるうち２つしかできない、３つしかできないということになったときに、選択をするにあたっての基礎的な資料となるということになります。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"ですから私は、自分が投資した資金がどれだけの利益を生み出すか、企業会計の一番の目的というのは利益を産出することになっているわけです。いいのかもしれませんけれども、住民福祉の増進を使命とする自治体の公会計ではなじまないのではないかと思いますが、いかがか尋ねました。","respondent":"齋藤会計管理者","answer":"納税者の立場で考えますと、自分の税の使われ方がどのようになっているかが見えてくるというのは、大きい意義があるのだと思います。そういった議論もあるかもしれませんし、統廃合、廃止ありきではないのだろうと考えております。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"コスト主義で考えるやり方というのは、私は区民サービスの削減や低下につながってくると思うのですけれども、いかがでしょうか。新公会計制度で作成される財務諸表等の活用というのは、私は慎重にすべきだと思うのですけれども、いかがか尋ねました。","respondent":"齋藤会計管理者","answer":"公会計制度はあくまでフルコストを見ていただく、あるいは財務状況がどのような状況か見せることでありまして、新公会計制度があると福祉サービスが削減されるということはないものと考えております。","id":"exchange-005"},{"speaker":"安藤委員","kind":"意見","question":"現状のままで、新公会計制度の活用をどんどん進めていくということには反対です。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"須貝委員","kind":"確認","question":"たしか１０％だと思ったのですけれども、例えば機械とか施設とかを減価償却していくと、最後は残額が１円になるのですか。その辺だけ確認させてください。","respondent":"齋藤会計管理者","answer":"７００近い事業がありますが、来年度の決算議会でどれほどお出しできるかを検討中で、行く行くはお出ししたいと考えております。物がある以上は１円で、１円の価値しかないという会計上の区切りでありまして、あくまで会計上の処理のお話です。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"今、簿価が最後は１円という話でしたけれども、たしか民間は１０％を残すような、簿価を減価償却で残していると思ったのですが、もし行政が違うやり方なら、それをまた説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問","question":"須貝委員からもありましたけれども、説明を改めてお伺いさせていただいて、細かく教えていただきまして、ありがとうございました。それぞれにこれだけかかるというのが見えるような形に変えていってもいいのかなと思ったのだけれども、そういう考えというのはあるのか尋ねました。","respondent":"齋藤会計管理者、品川財政課長","answer":"最小の経費で最大の効果というのが地方自治法にも書いてありますし、区長が毎回お話ししているとおり、行革の理念は、本区にはあります。それが新公会計制度によって、数字的にも裏打ちをして、かつ委員の皆様をはじめ、区民の皆様に… 基金の見せ方なのですけれども、当然こういう貸借対照表の中で、資産という形の部分で出していくことになりますので、そういう見せ方についても今後いろいろと検討していきたいと考えています。","id":"exchange-009"},{"speaker":"渡部委員","kind":"質問","question":"そのような形で見せるのであれば、そこも細分化していけばいいのかなという思いがあったので、そういう質問をしました。総くくりで１,０００億円という形にするのか、私はいいのかなと思いましたので、考え方としてお示しさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"ＩＣＴなどの活用に関することのうち、区民サービスの電子化","agenda":"ＩＣＴなどの活用に関することのうち、区民サービスの電子化","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"８月に、区民の皆さんが身近な地域に関心を持ち行動するきっかけや区政に参加する機会も増えるといったいい効果があるのではないかと思うのです。区でもこうした仕組みというのを検討してはいかがかと思うのですけれども、お考えがあれば伺います。","respondent":"山本情報推進課長","answer":"確かにＩＣＴを活用して、リアルタイムでそういった破損箇所等を行政に伝達できる仕組みというのは、大変有効な手段であると考えています。","id":"exchange-011"},{"speaker":"渡部委員","kind":"質問","question":"多分、私の選択できる学校はどこですかとか、通学区域はどこですかとか、ある程度質問も想定される。もう１年を切っているわけで、これはやってほしいと思うのですけれども、どうか尋ねました。","respondent":"山本情報推進課長","answer":"既に想定されているところかと思いますので、そういうところの導入に向けまして、所管と連携をとりながら検討はしていきたいと考えています。まだ調整中なのですけれども、こちらも把握していますので、そういうところも踏まえながら検討させていただきたいと考えています。","id":"exchange-012"},{"speaker":"渡部委員","kind":"質問・要望","question":"要望という形でお話を入れていたのですけれども、選択行為が始まる前に間に合わせてほしいという思いがありますので、よろしくお願いします。さまざまな情報もお示しできるような形で、そういう情報も入れていただければうれしいなと思いますので、所管と研究を続けてもらえればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"だから、ＡＩを構築するまでに大変な労力が要るということなのですか。その情報がなかったらＡＩは正確に回答できないわけですから、導入するには膨大な作業を要することなのかなというのを、本日質問したかったのです。","respondent":"山本情報推進課長","answer":"渋谷区の場合は３００件のＦＡＱデータを作成して学習させたというところで、３００程度のＦＡＱを作成し、かなり大きくなってくるかと思います。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"だから、こちらからすれば買うような方法で、どなたかつくってくれるところがあればいいのかなと思ったのです。そういうところは実際ないのか尋ねました。","respondent":"山本情報推進課長","answer":"そこまで詳しく話は聞いていないのですが、そういった形でパッケージ販売とかを今、検討しているという事業者もあると聞いてあります。精査しなくてはいけないという負担もありますので、そういうところは引き続き、情報収集等は続けてまいりたいと考えています。","id":"exchange-015"},{"speaker":"須貝委員","kind":"提案","question":"それはそれで議会に提案していただければいいのかなと思います。ただ、相当膨大な日数はかかるのだと思いますので、少しずつ、一歩ずつ、慎重に進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"若林委員","kind":"質問・要望","question":"例えばこの1)番のアプリに対しては、具体的にこういうアドバイス等をしてかかわりましたとか、そういう具体例があれば教えてほしいと求めました。","respondent":"山本情報推進課長","answer":"今年１１月から始まっているものになりますけれども、1)のしながわパパママ応援アプリでも、そこはうまくできませんでした。そういった形でこちらから幾つか提案等はさせていただいているところです。","id":"exchange-017"},{"speaker":"こんの委員","kind":"質問","question":"今後のＩＣＴ活用というところで、１つお伺いしたいと思うのですが、４の（２）番のデジタル化の推進ということで、今後考えていることで、オンライン上での手続の一元化とされているのですけれども、何かもう具体的にどういったことを行うお考えがあるのか、まずその点をお伺いしたいと思います。","respondent":"山本情報推進課長","answer":"国が指定した子育て分野４業務について、ここで手続の電子申請であったり、内容を確認できたりというところでの運用を始めてあります。こちらもこれから本格的に進めていきたいと考えています。","id":"exchange-018"},{"speaker":"こんの委員","kind":"質問","question":"区民の方の利便性向上ということで、一元化をして手続が簡素化できるというのは、考え方として非常に大事だと思います。こういうものの一元化というのはどうなのかというところなのですけれども、こうした煩雑な手続が、どのようにお考えか尋ねました。","respondent":"山本情報推進課長","answer":"予定としては平成３１年度、３２年度ぐらいに、民間を含めた死亡相続のワンストップサービスを行うというところで予定はしているところです。ただ、具体的にどう進めていくかというところは、早急に対応できるように準備等はしていきたいと考えています。","id":"exchange-019"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ進めていただきたい分野でありますし、もう一歩お聞きしたいところなのですけれども、本当にこの手続は煩雑なのです。こんな考え方はいかがか尋ねました。","respondent":"山本情報推進課長","answer":"例えば国保と戸籍だと、そこの連携というのはできない状態なので、そこでのワンストップサービスについては対応ができていない状況です。","id":"exchange-020"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ研究をしていただいて、やはり品川区はそういったところまでしてくれるのだというところまで、ぜひつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"新妻委員","kind":"確認","question":"ＩＣＴ化が進んでいるところが確認されたのですが、特にアプリの配信というのは非常に有効かなと考えています。ここに４つ挙げられておりまして、逆に情報推進課から、アプリでこういうことができるのだというアドバイスというのはされているのか尋ねました。","respondent":"山本情報推進課長","answer":"情報推進課と各課連携の話かと思いますけれども、情報推進課が後から入っていき、一緒に進めていくという方法で進めているところです。具体的に、こういったアプリがあるのでというところの実例は、まだないのが実情です。","id":"exchange-022"},{"speaker":"新妻委員","kind":"質問・要望","question":"個別にやっているのですけれども、横串となってそれらを１つとしてまとめていければ、課を超えたワンストップ化というのはできてくると思うのです。これは１つにできる、ぜひ情報推進課からしてほしいと求めましたし、今後その辺はいかがか尋ねました。","respondent":"山本情報推進課長","answer":"システムの連携といいますか、一元化というところは、こちらで必要な部分について研究を進めていきたいと考えているところです。そういった形で、こちらからもいろいろな情報発信というのを引き続き行っていきたいと考えています。","id":"exchange-023"}]},{"id":"topic-03","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"正副提案どおりの調査事項でまとめを行うことでよいと思いますけれども、幾つか意見を述べさせてほしいと求めました。仕組みを見直すような国への働きかけを進めてほしいということを求めましたので、委員会としてはなかなか一致していないのではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"渡部委員","kind":"質問","question":"それぞれいろいろな意見というのが出てきたわけで、それはこの委員会の中で、さまざまな議論から生まれたところだと思います。ですから、個人からの意見というのは尊重されるべきなのでしょうから、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/237826?Template=document&Id=6062#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":32402,"voices":69}}]);
